import { User, Pizza, Order, Day, DayStatus } from '../types';
import { INITIAL_USERS, INITIAL_PIZZAS } from '../constants';

const STORAGE_KEYS = {
  USERS: 'pizzastaff_users',
  PIZZAS: 'pizzastaff_pizzas',
  ORDERS: 'pizzastaff_orders',
  DAYS: 'pizzastaff_days',
};

class DB {
  private get<T>(key: string, defaultValue: T): T {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultValue;
  }

  private set(key: string, data: any): void {
    localStorage.setItem(key, JSON.stringify(data));
  }

  // Users
  getUsers(): User[] {
    return this.get<User[]>(STORAGE_KEYS.USERS, INITIAL_USERS);
  }
  saveUser(user: User): void {
    const users = this.getUsers();
    const index = users.findIndex(u => u.id === user.id);
    if (index >= 0) users[index] = user;
    else users.push(user);
    this.set(STORAGE_KEYS.USERS, users);
  }
  deleteUser(id: string): void {
    const users = this.getUsers().filter(u => u.id !== id);
    this.set(STORAGE_KEYS.USERS, users);
  }

  // Pizzas
  getPizzas(): Pizza[] {
    return this.get<Pizza[]>(STORAGE_KEYS.PIZZAS, INITIAL_PIZZAS);
  }
  savePizza(pizza: Pizza): void {
    const pizzas = this.getPizzas();
    const index = pizzas.findIndex(p => p.id === pizza.id);
    if (index >= 0) pizzas[index] = pizza;
    else pizzas.push(pizza);
    this.set(STORAGE_KEYS.PIZZAS, pizzas);
  }
  deletePizza(id: string): void {
    const pizzas = this.getPizzas().filter(p => p.id !== id);
    this.set(STORAGE_KEYS.PIZZAS, pizzas);
  }

  // Days
  getDays(): Day[] {
    return this.get<Day[]>(STORAGE_KEYS.DAYS, []);
  }
  getCurrentDay(): Day | undefined {
    const today = new Date().toISOString().split('T')[0];
    return this.getDays().find(d => d.date === today);
  }
  openDay(): Day {
    const today = new Date().toISOString().split('T')[0];
    const days = this.getDays();
    let day = days.find(d => d.date === today);
    if (!day) {
      day = {
        id: crypto.randomUUID(),
        date: today,
        status: DayStatus.OPEN,
        openedAt: new Date().toISOString()
      };
      days.push(day);
      this.set(STORAGE_KEYS.DAYS, days);
    } else {
      day.status = DayStatus.OPEN;
      this.set(STORAGE_KEYS.DAYS, days);
    }
    return day;
  }
  closeDay(): void {
    const today = new Date().toISOString().split('T')[0];
    const days = this.getDays();
    const day = days.find(d => d.date === today);
    if (day) {
      day.status = DayStatus.CLOSED;
      day.closedAt = new Date().toISOString();
      this.set(STORAGE_KEYS.DAYS, days);
    }
  }

  // Orders
  getOrders(): Order[] {
    return this.get<Order[]>(STORAGE_KEYS.ORDERS, []);
  }
  getOrdersByDay(dayId: string): Order[] {
    return this.getOrders().filter(o => o.dayId === dayId);
  }
  getUserOrderToday(userId: string): Order | undefined {
    const currentDay = this.getCurrentDay();
    if (!currentDay) return undefined;
    return this.getOrders().find(o => o.userId === userId && o.dayId === currentDay.id);
  }
  saveOrder(order: Order): void {
    const orders = this.getOrders();
    const index = orders.findIndex(o => o.id === order.id || (o.userId === order.userId && o.dayId === order.dayId));
    if (index >= 0) orders[index] = order;
    else orders.push(order);
    this.set(STORAGE_KEYS.ORDERS, orders);
  }
  deleteOrder(id: string): void {
    const orders = this.getOrders().filter(o => o.id !== id);
    this.set(STORAGE_KEYS.ORDERS, orders);
  }
}

export const db = new DB();

import { CUTOFF_TIME } from '../constants';

export const isBeforeCutoff = (): boolean => {
  const now = new Date();
  const [cutoffHour, cutoffMinute] = CUTOFF_TIME.split(':').map(Number);

  const cutoff = new Date(now);
  cutoff.setHours(cutoffHour, cutoffMinute, 0, 0);

  return now < cutoff;
};

export const formatTime = (date: string | Date): string => {
  return new Date(date).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' });
};

export const formatDate = (date: string | Date): string => {
  return new Date(date).toLocaleDateString('it-IT', { 
    weekday: 'long', 
    day: 'numeric', 
    month: 'long', 
    year: 'numeric' 
  });
};

