import { Order, Pizza, User, SlotTime } from '../types';
import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

// Extend jsPDF with autotable type
declare module 'jspdf' {
  interface jsPDF {
    autoTable: any;
  }
}

export const exportToCSV = (date: string, data: any[]) => {
  const header = ['Orario', 'Dipendente', 'Pizza', 'Note'];
  const rows = data.map(o => [o.slotTime, `${o.user.firstName} ${o.user.lastName}`, o.pizza.name, o.note]);

  const csvContent = [header, ...rows].map(e => e.join(",")).join("\n");
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.setAttribute("href", url);
  link.setAttribute("download", `ordini_${date}.csv`);
  link.click();
};

export const exportToXLSX = (date: string, orders: any[]) => {
  const workbook = XLSX.utils.book_new();
  const worksheetData = orders.map(o => ({
    Orario: o.slotTime,
    Dipendente: `${o.user.firstName} ${o.user.lastName}`,
    Pizza: o.pizza.name,
    Note: o.note
  }));

  const ws = XLSX.utils.json_to_sheet(worksheetData);
  XLSX.utils.book_append_sheet(workbook, ws, "Ordini");
  XLSX.writeFile(workbook, `ordini_${date}.xlsx`);
};

export const exportToPDF = (date: string, ordersBySlot: Record<SlotTime, any[]>, totalByPizza: Record<string, number>) => {
  const doc = new jsPDF();
  doc.setFontSize(20);
  doc.text("Riepilogo Ordini Pizza", 14, 22);
  doc.setFontSize(12);
  doc.text(`Data: ${date}`, 14, 30);

  let yPos = 40;

  (['17:30', '18:00', '19:00'] as SlotTime[]).forEach(slot => {
    const slotOrders = ordersBySlot[slot] || [];
    if (slotOrders.length > 0) {
      doc.setFontSize(14);
      doc.text(`Slot Orario: ${slot}`, 14, yPos);
      yPos += 5;

      const body = slotOrders.map(o => [
        `${o.user.firstName} ${o.user.lastName}`,
        o.pizza.name,
        o.note || '-'
      ]);

      doc.autoTable({
        startY: yPos,
        head: [['Dipendente', 'Pizza', 'Note']],
        body: body,
      });

      yPos = doc.autoTable.previous.finalY + 15;
      if (yPos > 260) { doc.addPage(); yPos = 20; }
    }
  });

  // Summary by Pizza
  doc.setFontSize(14);
  doc.text("Totali per Pizza", 14, yPos);
  yPos += 5;
  const pizzaTotalsBody = Object.entries(totalByPizza).map(([name, qty]) => [name, qty]);
  doc.autoTable({
    startY: yPos,
    head: [['Pizza', 'Quantità']],
    body: pizzaTotalsBody,
  });

  doc.save(`ordini_${date}.pdf`);
};

import React, { useState, useEffect } from 'react';
import { AuthState, User, Role, Day, Order, DayStatus } from './types';
import { db } from './services/db';
import LoginView from './views/Login';
import WorkerDashboard from './views/WorkerDashboard';
import AdminDashboard from './views/AdminDashboard';
import AdminPizzas from './views/AdminPizzas';
import AdminUsers from './views/AdminUsers';
import AdminHistory from './views/AdminHistory';

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('pizzastaff_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const [view, setView] = useState<'dashboard' | 'pizzas' | 'users' | 'history'>('dashboard');

  useEffect(() => {
    localStorage.setItem('pizzastaff_auth', JSON.stringify(auth));
  }, [auth]);

  const handleLogin = (user: User) => {
    setAuth({ user, isAuthenticated: true });
  };

  const handleLogout = () => {
    setAuth({ user: null, isAuthenticated: false });
    setView('dashboard');
  };

  if (!auth.isAuthenticated || !auth.user) {
    return <LoginView onLogin={handleLogin} />;
  }

  // RBAC Navigation
  const renderView = () => {
    if (auth.user?.role === Role.ADMIN || auth.user?.role === Role.SUPERVISOR) {
      switch (view) {
        case 'pizzas': return <AdminPizzas onBack={() => setView('dashboard')} />;
        case 'users': return <AdminUsers onBack={() => setView('dashboard')} />;
        case 'history': return <AdminHistory onBack={() => setView('dashboard')} />;
        default: return <AdminDashboard 
          user={auth.user!} 
          onLogout={handleLogout} 
          onNavigate={(v: any) => setView(v)} 
        />;
      }
    }

    return <WorkerDashboard user={auth.user!} onLogout={handleLogout} />;
  };

  return (
    <div className="bg-[#F2F2F7] min-h-screen">
      {renderView()}
    </div>
  );
};

export default App;

