import React, { useState, useEffect } from 'react';
import { User, Day, DayStatus, Order, SlotTime, Role } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button } from '../components/UI';
import { 
  Plus, 
  ClockIcon, 
  UsersIcon, 
  PizzaIcon, 
  History, 
  Unlock, 
  Lock, 
  FileText, 
  Download,
  TableIcon
} from '../components/Icons';
import { formatDate } from '../services/utils';
import { exportToCSV, exportToXLSX, exportToPDF } from '../services/exportService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  onNavigate: (view: 'pizzas' | 'users' | 'history') => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout, onNavigate }) => {
  const [currentDay, setCurrentDay] = useState<Day | undefined>(db.getCurrentDay());
  const [orders, setOrders] = useState<any[]>([]);
  const [viewMode, setViewMode] = useState<'byUser' | 'byPizza'>('byUser');

  useEffect(() => {
    if (currentDay) {
      const dayOrders = db.getOrdersByDay(currentDay.id);
      const users = db.getUsers();
      const pizzas = db.getPizzas();

      const hydratedOrders = dayOrders.map(o => ({
        ...o,
        user: users.find(u => u.id === o.userId),
        pizza: pizzas.find(p => p.id === o.pizzaId)
      }));
      setOrders(hydratedOrders);
    } else {
      setOrders([]);
    }
  }, [currentDay]);

  const handleOpenDay = () => {
    const day = db.openDay();
    setCurrentDay(day);
  };

  const handleCloseDay = () => {
    if (window.confirm("Chiudere gli ordini per oggi?")) {
      db.closeDay();
      setCurrentDay(db.getCurrentDay());
    }
  };

  const totalsBySlot = orders.reduce((acc, o) => {
    acc[o.slotTime] = (acc[o.slotTime] || 0) + 1;
    return acc;
  }, {} as any);

  const totalsByPizza = orders.reduce((acc, o) => {
    acc[o.pizza.name] = (acc[o.pizza.name] || 0) + 1;
    return acc;
  }, {} as any);

  const ordersBySlot = orders.reduce((acc, o) => {
    if (!acc[o.slotTime]) acc[o.slotTime] = [];
    acc[o.slotTime].push(o);
    return acc;
  }, {} as Record<string, any[]>);

  const handleExport = (type: 'pdf' | 'xlsx' | 'csv') => {
    if (!currentDay) return;
    const dateStr = currentDay.date;

    switch(type) {
      case 'csv': exportToCSV(dateStr, orders); break;
      case 'xlsx': exportToXLSX(dateStr, orders); break;
      case 'pdf': exportToPDF(dateStr, ordersBySlot as any, totalsByPizza); break;
    }
  };

  const isReadOnly = user.role === Role.SUPERVISOR;

  return (
    <Layout title="Dashboard Admin" onLogout={onLogout}>
      <div className="space-y-6">
        {/* Gestione Giornata */}
        <Card className="p-4">
          <div className="flex justify-between items-center mb-4">
            <div>
              <p className="text-xs font-bold text-[#8E8E93] uppercase">Stato Giornata</p>
              <h2 className="text-lg font-bold">{formatDate(new Date())}</h2>
            </div>
            <div className={`px-3 py-1 rounded-full text-xs font-bold ${
              currentDay?.status === DayStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
            }`}>
              {currentDay ? (currentDay.status === DayStatus.OPEN ? 'APERTA' : 'CHIUSA') : 'MAI APERTA'}
            </div>
          </div>

          <div className="flex gap-2">
            {!currentDay || currentDay.status === DayStatus.CLOSED ? (
              <Button 
                onClick={handleOpenDay} 
                className="flex-1" 
                variant="primary"
                disabled={isReadOnly}
              >
                <Unlock size={18} /> Apri Giornata
              </Button>
            ) : (
              <Button 
                onClick={handleCloseDay} 
                className="flex-1" 
                variant="danger"
                disabled={isReadOnly}
              >
                <Lock size={18} /> Chiudi Giornata
              </Button>
            )}
          </div>
        </Card>

        {/* Quick Stats */}
        <div className="grid grid-cols-3 gap-3">
          {(['17:30', '18:00', '19:00'] as SlotTime[]).map(slot => (
            <Card key={slot} className="p-3 text-center">
              <p className="text-[10px] font-bold text-[#8E8E93] uppercase">{slot}</p>
              <p className="text-xl font-bold text-[#007AFF]">{totalsBySlot[slot] || 0}</p>
            </Card>
          ))}
        </div>

        {/* Riepilogo Ordini */}
        {orders.length > 0 && (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <h3 className="font-bold text-lg">Ordini di oggi ({orders.length})</h3>
              <div className="flex bg-[#E5E5EA] p-1 rounded-lg">
                <button 
                  onClick={() => setViewMode('byUser')}
                  className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${viewMode === 'byUser' ? 'bg-white shadow-sm' : 'text-[#8E8E93]'}`}
                >
                  Dipendente
                </button>
                <button 
                  onClick={() => setViewMode('byPizza')}
                  className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${viewMode === 'byPizza' ? 'bg-white shadow-sm' : 'text-[#8E8E93]'}`}
                >
                  Pizza
                </button>
              </div>
            </div>

            {viewMode === 'byUser' ? (
              <div className="space-y-6">
                {(['17:30', '18:00', '19:00'] as SlotTime[]).map(slot => (
                  <div key={slot} className="space-y-2">
                    {ordersBySlot[slot]?.length > 0 && (
                      <>
                        <h4 className="text-xs font-bold text-[#8E8E93] uppercase pl-1">{slot}</h4>
                        <div className="space-y-2">
                          {ordersBySlot[slot].map(o => (
                            <Card key={o.id} className="p-3">
                              <div className="flex justify-between items-start">
                                <div>
                                  <p className="font-bold text-sm">{o.user.firstName} {o.user.lastName}</p>
                                  <p className="text-xs text-[#007AFF] font-medium">{o.pizza.name}</p>
                                  {o.note && <p className="text-[10px] italic text-[#8E8E93] mt-1">"{o.note}"</p>}
                                </div>
                              </div>
                            </Card>
                          ))}
                        </div>
                      </>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-3">
                {Object.entries(totalsByPizza).map(([name, qty]) => (
                  <Card key={name} className="p-4 flex justify-between items-center">
                    <p className="font-bold">{name}</p>
                    <div className="bg-[#007AFF] text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm">
                      {qty as any}
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Export Actions */}
        {orders.length > 0 && (
          <Card className="p-4">
            <h3 className="font-bold text-sm uppercase text-[#8E8E93] mb-3">Esporta Riepilogo</h3>
            <div className="grid grid-cols-3 gap-2">
              <Button variant="secondary" onClick={() => handleExport('pdf')} className="!p-2 text-xs">
                <FileText size={16} /> PDF
              </Button>
              <Button variant="secondary" onClick={() => handleExport('xlsx')} className="!p-2 text-xs">
                <TableIcon size={16} /> XLSX
              </Button>
              <Button variant="secondary" onClick={() => handleExport('csv')} className="!p-2 text-xs">
                <Download size={16} /> CSV
              </Button>
            </div>
          </Card>
        )}

        {/* Quick Links */}
        <div className="grid grid-cols-1 gap-2">
          <Button variant="secondary" fullWidth onClick={() => onNavigate('pizzas')} className="justify-start">
            <PizzaIcon size={20} className="text-[#007AFF]" /> Gestione Menu Pizze
          </Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('users')} className="justify-start">
            <UsersIcon size={20} className="text-[#5856D6]" /> Gestione Dipendenti
          </Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('history')} className="justify-start">
            <History size={20} className="text-[#FF9500]" /> Storico Ordini
          </Button>
        </div>
      </div>
    </Layout>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Pizza } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { Plus, Edit2, Trash2, X, Check } from '../components/Icons';

interface AdminPizzasProps {
  onBack: () => void;
}

const AdminPizzas: React.FC<AdminPizzasProps> = ({ onBack }) => {
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [editing, setEditing] = useState<Partial<Pizza> | null>(null);

  useEffect(() => {
    setPizzas(db.getPizzas());
  }, []);

  const handleSave = () => {
    if (!editing?.name) return;

    const pizza: Pizza = {
      id: editing.id || crypto.randomUUID(),
      name: editing.name,
      description: editing.description || '',
      ingredients: editing.ingredients || [],
      allergens: editing.allergens || [],
      active: editing.active ?? true,
      isVegetarian: editing.isVegetarian ?? false
    };

    db.savePizza(pizza);
    setPizzas(db.getPizzas());
    setEditing(null);
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Eliminare questa pizza dal menu?")) {
      db.deletePizza(id);
      setPizzas(db.getPizzas());
    }
  };

  const handleToggleActive = (pizza: Pizza) => {
    db.savePizza({ ...pizza, active: !pizza.active });
    setPizzas(db.getPizzas());
  };

  return (
    <Layout title="Gestione Pizze" onBack={onBack}>
      <div className="space-y-4">
        <Button fullWidth onClick={() => setEditing({})}>
          <Plus size={20} /> Aggiungi Nuova Pizza
        </Button>

        <div className="space-y-3">
          {pizzas.map(p => (
            <Card key={p.id} className={`p-4 ${!p.active ? 'opacity-50 grayscale' : ''}`}>
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-bold text-lg">{p.name}</h3>
                  <p className="text-xs text-[#8E8E93]">{p.ingredients.join(', ')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => setEditing(p)} className="p-2 text-[#007AFF] bg-[#F2F2F7] rounded-full">
                    <Edit2 size={16} />
                  </button>
                  <button onClick={() => handleDelete(p.id)} className="p-2 text-[#FF3B30] bg-red-50 rounded-full">
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
              <div className="mt-3 pt-3 border-t border-[#F2F2F7] flex justify-between items-center">
                <span className="text-xs font-bold text-[#8E8E93] uppercase">
                  Stato: {p.active ? 'ATTIVA' : 'DISATTIVATA'}
                </span>
                <button 
                  onClick={() => handleToggleActive(p)}
                  className={`text-xs font-bold px-3 py-1 rounded-full ${p.active ? 'bg-orange-100 text-orange-600' : 'bg-green-100 text-green-600'}`}
                >
                  {p.active ? 'DISATTIVA' : 'ATTIVA'}
                </button>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {editing && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => setEditing(null)} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-4 shadow-2xl overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">{editing.id ? 'Modifica Pizza' : 'Nuova Pizza'}</h2>
              <button onClick={() => setEditing(null)} className="p-2 bg-[#F2F2F7] rounded-full">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Nome Pizza</label>
                <Input value={editing.name || ''} onChange={e => setEditing({...editing, name: e.target.value})} />
              </div>
              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Ingredienti (separati da virgola)</label>
                <Input 
                  value={editing.ingredients?.join(', ') || ''} 
                  onChange={e => setEditing({...editing, ingredients: e.target.value.split(',').map(s => s.trim())})} 
                />
              </div>
              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Allergeni (separati da virgola)</label>
                <Input 
                  value={editing.allergens?.join(', ') || ''} 
                  onChange={e => setEditing({...editing, allergens: e.target.value.split(',').map(s => s.trim())})} 
                />
              </div>
              <div className="flex items-center gap-2">
                <input 
                  type="checkbox" 
                  checked={editing.isVegetarian || false} 
                  onChange={e => setEditing({...editing, isVegetarian: e.target.checked})}
                />
                <label className="text-sm font-medium">Pizza Vegetariana</label>
              </div>
            </div>

            <Button fullWidth onClick={handleSave} className="mt-4">
              Salva Pizza
            </Button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default AdminPizzas;

