import { createClient } from '@supabase/supabase-js';
import { User, Pizza, Order, Day, DayStatus, SlotTime } from '../types';

// Nota: Questi valori andrebbero in variabili d'ambiente. 
// Per l'esecuzione immediata, l'utente dovrà sostituirli con i propri dati di progetto Supabase.
const SUPABASE_URL = (process.env.SUPABASE_URL || 'https://your-project.supabase.co').trim();
const SUPABASE_ANON_KEY = (process.env.SUPABASE_ANON_KEY || 'your-anon-key').trim();

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

class DB {
  // Users
  async getUsers(): Promise<User[]> {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .order('last_name', { ascending: true });
    if (error) throw error;
    return data.map(u => ({
      id: u.id,
      firstName: u.first_name,
      lastName: u.last_name,
      pin: u.pin,
      role: u.role,
      active: u.active
    }));
  }

  async getUserByPin(pin: string): Promise<User | null> {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('pin', pin)
      .eq('active', true)
      .single();
    if (error) return null;
    return {
      id: data.id,
      firstName: data.first_name,
      lastName: data.last_name,
      pin: data.pin,
      role: data.role,
      active: data.active
    };
  }

  async saveUser(user: Partial<User>): Promise<void> {
    const payload = {
      first_name: user.firstName,
      last_name: user.lastName,
      pin: user.pin,
      role: user.role,
      active: user.active
    };
    if (user.id) {
      const { error } = await supabase.from('users').update(payload).eq('id', user.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('users').insert([payload]);
      if (error) throw error;
    }
  }

  async deleteUser(id: string): Promise<void> {
    const { error } = await supabase.from('users').delete().eq('id', id);
    if (error) throw error;
  }

  // Pizzas
  async getPizzas(): Promise<Pizza[]> {
    const { data, error } = await supabase
      .from('pizzas')
      .select('*')
      .order('name', { ascending: true });
    if (error) throw error;
    return data;
  }

  async savePizza(pizza: Partial<Pizza>): Promise<void> {
    if (pizza.id) {
      const { error } = await supabase.from('pizzas').update(pizza).eq('id', pizza.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('pizzas').insert([pizza]);
      if (error) throw error;
    }
  }

  async deletePizza(id: string): Promise<void> {
    const { error } = await supabase.from('pizzas').delete().eq('id', id);
    if (error) throw error;
  }

  // Days
  async getDays(): Promise<Day[]> {
    const { data, error } = await supabase
      .from('days')
      .select('*')
      .order('date', { ascending: false });
    if (error) throw error;
    return data.map(d => ({
      id: d.id,
      date: d.date,
      status: d.status,
      openedAt: d.opened_at,
      closedAt: d.closed_at
    }));
  }

  async getCurrentDay(): Promise<Day | null> {
    const today = new Date().toISOString().split('T')[0];
    const { data, error } = await supabase
      .from('days')
      .select('*')
      .eq('date', today)
      .maybeSingle();
    if (error) return null;
    if (!data) return null;
    return {
      id: data.id,
      date: data.date,
      status: data.status,
      openedAt: data.opened_at,
      closedAt: data.closed_at
    };
  }

  async openDay(): Promise<Day> {
    const today = new Date().toISOString().split('T')[0];
    const { data: existing } = await supabase.from('days').select('*').eq('date', today).maybeSingle();

    if (existing) {
      const { data, error } = await supabase.from('days').update({ status: 'OPEN' }).eq('id', existing.id).select().single();
      if (error) throw error;
      return data;
    } else {
      const { data, error } = await supabase.from('days').insert([{ date: today, status: 'OPEN' }]).select().single();
      if (error) throw error;
      return data;
    }
  }

  async closeDay(): Promise<void> {
    const today = new Date().toISOString().split('T')[0];
    const { error } = await supabase.from('days').update({ status: 'CLOSED', closed_at: new Date().toISOString() }).eq('date', today);
    if (error) throw error;
  }

  // Orders
  async getOrdersByDay(dayId: string): Promise<Order[]> {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('day_id', dayId);
    if (error) throw error;
    return data.map(o => ({
      id: o.id,
      dayId: o.day_id,
      userId: o.user_id,
      pizzaId: o.pizza_id,
      slotTime: o.slot_time as SlotTime,
      note: o.note,
      createdAt: o.created_at,
      updatedAt: o.updated_at
    }));
  }

  async getUserOrderToday(userId: string): Promise<Order | null> {
    const currentDay = await this.getCurrentDay();
    if (!currentDay) return null;
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('user_id', userId)
      .eq('day_id', currentDay.id)
      .maybeSingle();
    if (error) return null;
    if (!data) return null;
    return {
      id: data.id,
      dayId: data.day_id,
      userId: data.user_id,
      pizzaId: data.pizza_id,
      slotTime: data.slot_time as SlotTime,
      note: data.note,
      createdAt: data.created_at,
      updatedAt: data.updated_at
    };
  }

  async saveOrder(order: Partial<Order>): Promise<void> {
    const payload = {
      day_id: order.dayId,
      user_id: order.userId,
      pizza_id: order.pizzaId,
      slot_time: order.slotTime,
      note: order.note,
      updated_at: new Date().toISOString()
    };
    if (order.id) {
      const { error } = await supabase.from('orders').update(payload).eq('id', order.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('orders').insert([payload]);
      if (error) throw error;
    }
  }
}

export const db = new DB();

import React, { useState } from 'react';
import { db } from '../services/db';
import { User } from '../types';
import { Button, Input, Card } from '../components/UI';
import { PizzaIcon, Lock } from '../components/Icons';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (pin.length < 4) return;

    setLoading(true);
    setError('');

    try {
      const user = await db.getUserByPin(pin);
      if (user) {
        onLogin(user);
      } else {
        setError('PIN non valido o utente disattivato');
        setPin('');
      }
    } catch (err) {
      setError('Errore di connessione al server');
    } finally {
      setLoading(false);
    }
  };

  const appendPin = (digit: string) => {
    if (pin.length < 6) setPin(prev => prev + digit);
  };

  const clearPin = () => setPin('');

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#F2F2F7]">
      <div className="w-full max-w-sm flex flex-col items-center gap-8">
        <div className="flex flex-col items-center gap-3">
          <div className="w-20 h-20 bg-[#007AFF] rounded-3xl flex items-center justify-center shadow-lg transform -rotate-3">
            <PizzaIcon color="white" size={40} />
          </div>
          <h1 className="text-3xl font-bold tracking-tight mt-4">Staff Pizza</h1>
          <p className="text-[#8E8E93] font-medium text-center px-4">Inserisci il tuo codice personale per accedere</p>
        </div>

        <div className="w-full">
          <div className="flex justify-center gap-4 mb-8">
            {[1, 2, 3, 4].map((_, i) => (
              <div 
                key={i} 
                className={`w-4 h-4 rounded-full border-2 transition-all duration-200 ${
                  pin.length > i ? 'bg-[#007AFF] border-[#007AFF] scale-110' : 'bg-transparent border-[#C6C6C8]'
                }`}
              />
            ))}
          </div>

          <div className="h-6 mb-2">
            {error && <p className="text-[#FF3B30] text-center text-sm font-medium animate-bounce">{error}</p>}
          </div>

          <div className="grid grid-cols-3 gap-4">
            {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d => (
              <button
                key={d}
                disabled={loading}
                onClick={() => { setError(''); appendPin(d); }}
                className="h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA] transition-colors disabled:opacity-50"
              >
                {d}
              </button>
            ))}
            <button 
              disabled={loading}
              onClick={clearPin} 
              className="h-16 rounded-full text-sm font-semibold text-[#FF3B30] disabled:opacity-50"
            >
              CANCELLA
            </button>
            <button
              disabled={loading}
              onClick={() => { setError(''); appendPin('0'); }}
              className="h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA] transition-colors disabled:opacity-50"
            >
              0
            </button>
            <button 
              onClick={() => handleLogin()}
              disabled={pin.length < 4 || loading}
              className="h-16 rounded-full bg-[#007AFF] text-white text-sm font-bold shadow-md active:opacity-80 transition-opacity disabled:opacity-40 flex items-center justify-center"
            >
              {loading ? <div className="loading-spinner border-white border-t-transparent" /> : 'OK'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

