  const handleConfirmOrder = async () => {
    if (!selectedPizza || !currentDay) return;

    setSubmitting(true);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay.id,
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        note: note
      };

      await db.saveOrder(order);
      const updatedOrder = await db.getUserOrderToday(user.id);
      setMyOrder(updatedOrder);
      setSelectedPizza(null);
      setNote('');
      setIsEditing(false);
      setMessage({ text: "Ordine confermato con successo! ✅", type: "success" });
      setTimeout(() => setMessage(null), 3000);
    } catch (err) {
      setMessage({ text: "Errore durante il salvataggio", type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  const handleEdit = () => {
    if (!myOrder) return;
    const pizza = pizzas.find(p => p.id === myOrder.pizzaId);
    if (pizza) {
      setSelectedPizza(pizza);
      setSlot(myOrder.slotTime);
      setNote(myOrder.note);
      setIsEditing(true);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex flex-col items-center justify-center py-20 gap-4">
          <div className="loading-spinner !w-10 !h-10" />
          <p className="text-[#8E8E93] font-medium">Recupero menu in corso...</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Ordina Pizza" onLogout={onLogout}>
      {/* Banner Stato */}
      {!currentDay ? (
        <div className="bg-[#FF9500] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <AlertCircle size={24} />
          <div>
            <p className="font-bold">Giornata non ancora aperta</p>
            <p className="text-xs opacity-90">L'admin aprirà le ordinazioni a breve.</p>
          </div>
        </div>
      ) : !canOrder ? (
        <div className="bg-[#FF3B30] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <AlertCircle size={24} />
          <div>
            <p className="font-bold">Ordini chiusi 🔒</p>
            <p className="text-xs opacity-90">Oltre le 16:30 o giornata terminata. Non puoi più ordinare o modificare.</p>
          </div>
        </div>
      ) : (
        <div className="bg-[#34C759] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <Check size={24} />
          <div>
            <p className="font-bold">Ordini Aperti</p>
            <p className="text-xs opacity-90">Puoi ordinare o modificare fino alle 16:30.</p>
          </div>
        </div>
      )}

      {message && (
        <div className={`p-4 rounded-2xl mb-6 flex items-center gap-3 animate-pulse ${
          message.type === 'success' ? 'bg-[#34C759] text-white' : 'bg-[#FF3B30] text-white'
        }`}>
          <Check size={20} />
          <p className="font-medium text-sm">{message.text}</p>
        </div>
      )}

      {/* Ordine Esistente */}
      {myOrder && !selectedPizza && !isEditing && (
        <Card className="p-4 mb-6 border-2 border-[#34C759]">
          <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-xs font-bold text-[#34C759] uppercase mb-1">Il tuo ordine di oggi</p>
              <h2 className="text-xl font-bold">
                {pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza non disponibile'}
              </h2>
            </div>
            <div className="bg-[#F2F2F7] px-3 py-1 rounded-full flex items-center gap-1">
              <ClockIcon size={14} />
              <span className="text-sm font-bold">{myOrder.slotTime}</span>
            </div>
          </div>
          {myOrder.note && (
            <div className="bg-[#F2F2F7] p-2 rounded-lg mb-4">
              <p className="text-xs text-[#8E8E93]">Nota:</p>
              <p className="text-sm italic">"{myOrder.note}"</p>
            </div>
          )}
          {canOrder && (
            <Button onClick={handleEdit} variant="secondary" fullWidth>
              Modifica Ordine
            </Button>
          )}
        </Card>
      )}

      {/* Menu Pizze */}
      {(!myOrder || isEditing) && !selectedPizza && (
        <>
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
            <Input 
              placeholder="Cerca pizza o ingrediente..." 
              className="pl-10 bg-white"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="space-y-3">
            {filteredPizzas.length > 0 ? filteredPizzas.map(pizza => (
              <Card 
                key={pizza.id} 
                className={`p-4 cursor-pointer active:scale-95 transition-all ${
                  selectedPizza?.id === pizza.id ? 'ring-2 ring-[#007AFF]' : ''
                }`}
              >
                <div onClick={() => handleSelectPizza(pizza)}>
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase">Veg</span>}
                  </div>
                  <p className="text-sm text-[#8E8E93] line-clamp-2">{pizza.ingredients?.join(', ')}</p>
                  <div className="mt-2 flex gap-1 flex-wrap">
                    {pizza.allergens?.map(a => (
                      <span key={a} className="text-[10px] bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100 font-medium">
                        {a}
                      </span>
                    ))}
                  </div>
                </div>
              </Card>
            )) : (
              <p className="text-center text-[#8E8E93] py-10">Nessuna pizza trovata</p>
            )}
          </div>
        </>
      )}

      {/* Bottom Sheet Order Detail */}
      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => { if (!submitting) { setSelectedPizza(null); setIsEditing(false); } }} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-[#E5E5EA] rounded-full mx-auto mb-2" />

            <div className="flex justify-between items-start">
              <div>
                <h2 className="text-2xl font-bold">{selectedPizza.name}</h2>
                <p className="text-[#8E8E93]">{selectedPizza.ingredients?.join(', ')}</p>
              </div>
              <button disabled={submitting} onClick={() => { setSelectedPizza(null); setIsEditing(false); }} className="bg-[#F2F2F7] p-2 rounded-full disabled:opacity-50">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-3">
              <label className="text-sm font-bold text-[#8E8E93] uppercase">Orario Consegna</label>
              <SegmentedControl 
                options={SLOT_TIMES}
                selected={slot}
                onChange={(v) => setSlot(v as SlotTime)}
              />
            </div>

            <div className="space-y-3">
              <label className="text-sm font-bold text-[#8E8E93] uppercase">Note (opzionale)</label>
              <Input 
                placeholder="Es. Senza cipolla, ben cotta..."
                value={note}
                disabled={submitting}
                onChange={(e) => setNote(e.target.value)}
              />
            </div>

            <div className="pt-2">
              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting}>
                {submitting ? <div className="loading-spinner border-white border-t-transparent" /> : (isEditing ? 'Aggiorna Ordine' : 'Conferma Ordine')}
              </Button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default WorkerDashboard;

import React, { useState, useEffect } from 'react';
import { User, Day, DayStatus, SlotTime, Role } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button } from '../components/UI';
import { 
  UsersIcon, 
  PizzaIcon, 
  History, 
  Unlock, 
  Lock, 
  FileText, 
  Download,
  TableIcon
} from '../components/Icons';
import { formatDate } from '../services/utils';
import { exportToCSV, exportToXLSX, exportToPDF } from '../services/exportService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  onNavigate: (view: 'pizzas' | 'users' | 'history') => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout, onNavigate }) => {
  const [currentDay, setCurrentDay] = useState<Day | null>(null);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [viewMode, setViewMode] = useState<'byUser' | 'byPizza'>('byUser');

  const fetchData = async () => {
    setLoading(true);
    try {
      const day = await db.getCurrentDay();
      setCurrentDay(day);
      if (day) {
        const [dayOrders, users, pizzas] = await Promise.all([
          db.getOrdersByDay(day.id),
          db.getUsers(),
          db.getPizzas()
        ]);

        const hydratedOrders = dayOrders.map(o => ({
          ...o,
          user: users.find(u => u.id === o.userId),
          pizza: pizzas.find(p => p.id === o.pizzaId)
        }));
        setOrders(hydratedOrders);
      } else {
        setOrders([]);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleOpenDay = async () => {
    setActionLoading(true);
    try {
      await db.openDay();
      await fetchData();
    } catch (err) {
      alert("Errore nell'apertura giornata");
    } finally {
      setActionLoading(false);
    }
  };

  const handleCloseDay = async () => {
    if (window.confirm("Chiudere gli ordini per oggi?")) {
      setActionLoading(true);
      try {
        await db.closeDay();
        await fetchData();
      } catch (err) {
        alert("Errore nella chiusura giornata");
      } finally {
        setActionLoading(false);
      }
    }
  };

  const totalsBySlot = orders.reduce((acc, o) => {
    acc[o.slotTime] = (acc[o.slotTime] || 0) + 1;
    return acc;
  }, {} as any);

  const totalsByPizza = orders.reduce((acc, o) => {
    const pizzaName = o.pizza?.name || 'Sconosciuta';
    acc[pizzaName] = (acc[pizzaName] || 0) + 1;
    return acc;
  }, {} as any);

  const ordersBySlot = orders.reduce((acc, o) => {
    if (!acc[o.slotTime]) acc[o.slotTime] = [];
    acc[o.slotTime].push(o);
    return acc;
  }, {} as Record<string, any[]>);

  const handleExport = (type: 'pdf' | 'xlsx' | 'csv') => {
    if (!currentDay) return;
    const dateStr = currentDay.date;

    switch(type) {
      case 'csv': exportToCSV(dateStr, orders); break;
      case 'xlsx': exportToXLSX(dateStr, orders); break;
      case 'pdf': exportToPDF(dateStr, ordersBySlot as any, totalsByPizza); break;
    }
  };

  const isReadOnly = user.role === Role.SUPERVISOR;

  if (loading) {
    return (
      <Layout title="Admin" onLogout={onLogout}>
        <div className="flex flex-col items-center justify-center py-20">
          <div className="loading-spinner !w-10 !h-10" />
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Dashboard Admin" onLogout={onLogout}>
      <div className="space-y-6">
        {/* Gestione Giornata */}
        <Card className="p-4">
          <div className="flex justify-between items-center mb-4">
            <div>
              <p className="text-xs font-bold text-[#8E8E93] uppercase">Stato Giornata</p>
              <h2 className="text-lg font-bold">{formatDate(new Date())}</h2>
            </div>
            <div className={`px-3 py-1 rounded-full text-xs font-bold ${
              currentDay?.status === DayStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
            }`}>
              {currentDay ? (currentDay.status === DayStatus.OPEN ? 'APERTA' : 'CHIUSA') : 'MAI APERTA'}
            </div>
          </div>

          <div className="flex gap-2">
            {!currentDay || currentDay.status === DayStatus.CLOSED ? (
              <Button 
                onClick={handleOpenDay} 
                className="flex-1" 
                variant="primary"
                disabled={isReadOnly || actionLoading}
              >
                {actionLoading ? <div className="loading-spinner border-white border-t-transparent" /> : <><Unlock size={18} /> Apri Giornata</>}
              </Button>
            ) : (
              <Button 
                onClick={handleCloseDay} 
                className="flex-1" 
                variant="danger"
                disabled={isReadOnly || actionLoading}
              >
                {actionLoading ? <div className="loading-spinner border-white border-t-transparent" /> : <><Lock size={18} /> Chiudi Giornata</>}
              </Button>
            )}
          </div>
        </Card>

        {/* Quick Stats */}
        <div className="grid grid-cols-3 gap-3">
          {(['17:30', '18:00', '19:00'] as SlotTime[]).map(slot => (
            <Card key={slot} className="p-3 text-center">
              <p className="text-[10px] font-bold text-[#8E8E93] uppercase">{slot}</p>
              <p className="text-xl font-bold text-[#007AFF]">{totalsBySlot[slot] || 0}</p>
            </Card>
          ))}
        </div>

        {/* Riepilogo Ordini */}
        {orders.length > 0 && (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <h3 className="font-bold text-lg">Ordini di oggi ({orders.length})</h3>
              <div className="flex bg-[#E5E5EA] p-1 rounded-lg">
                <button 
                  onClick={() => setViewMode('byUser')}
                  className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${viewMode === 'byUser' ? 'bg-white shadow-sm' : 'text-[#8E8E93]'}`}
                >
                  Dipendente
                </button>
                <button 
                  onClick={() => setViewMode('byPizza')}
                  className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${viewMode === 'byPizza' ? 'bg-white shadow-sm' : 'text-[#8E8E93]'}`}
                >
                  Pizza
                </button>
              </div>
            </div>

            {viewMode === 'byUser' ? (
              <div className="space-y-6">
                {(['17:30', '18:00', '19:00'] as SlotTime[]).map(slot => (
                  <div key={slot} className="space-y-2">
                    {ordersBySlot[slot]?.length > 0 && (
                      <>
                        <h4 className="text-xs font-bold text-[#8E8E93] uppercase pl-1">{slot}</h4>
                        <div className="space-y-2">
                          {ordersBySlot[slot].map(o => (
                            <Card key={o.id} className="p-3">
                              <div className="flex justify-between items-start">
                                <div>
                                  <p className="font-bold text-sm">{o.user?.firstName} {o.user?.lastName}</p>
                                  <p className="text-xs text-[#007AFF] font-medium">{o.pizza?.name}</p>
                                  {o.note && <p className="text-[10px] italic text-[#8E8E93] mt-1">"{o.note}"</p>}
                                </div>
                              </div>
                            </Card>
                          ))}
                        </div>
                      </>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-3">
                {Object.entries(totalsByPizza).map(([name, qty]) => (
                  <Card key={name} className="p-4 flex justify-between items-center">
                    <p className="font-bold">{name}</p>
                    <div className="bg-[#007AFF] text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm">
                      {qty as any}
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Export Actions */}
        {orders.length > 0 && (
          <Card className="p-4">
            <h3 className="font-bold text-sm uppercase text-[#8E8E93] mb-3">Esporta Riepilogo</h3>
            <div className="grid grid-cols-3 gap-2">
              <Button variant="secondary" onClick={() => handleExport('pdf')} className="!p-2 text-xs">
                <FileText size={16} /> PDF
              </Button>
              <Button variant="secondary" onClick={() => handleExport('xlsx')} className="!p-2 text-xs">
                <TableIcon size={16} /> XLSX
              </Button>
              <Button variant="secondary" onClick={() => handleExport('csv')} className="!p-2 text-xs">
                <Download size={16} /> CSV
              </Button>
            </div>
          </Card>
        )}

        {/* Quick Links */}
        <div className="grid grid-cols-1 gap-2">
          <Button variant="secondary" fullWidth onClick={() => onNavigate('pizzas')} className="justify-start">
            <PizzaIcon size={20} className="text-[#007AFF]" /> Gestione Menu Pizze
          </Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('users')} className="justify-start">
            <UsersIcon size={20} className="text-[#5856D6]" /> Gestione Dipendenti
          </Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('history')} className="justify-start">
            <History size={20} className="text-[#FF9500]" /> Storico Ordini
          </Button>
        </div>
      </div>
    </Layout>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Pizza } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { Plus, Edit2, Trash2, X } from '../components/Icons';

interface AdminPizzasProps {
  onBack: () => void;
}

const AdminPizzas: React.FC<AdminPizzasProps> = ({ onBack }) => {
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [editing, setEditing] = useState<Partial<Pizza> | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const fetchPizzas = async () => {
    setLoading(true);
    try {
      const data = await db.getPizzas();
      setPizzas(data);
    } catch (err) {
      alert("Errore caricamento pizze");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPizzas();
  }, []);

  const handleSave = async () => {
    if (!editing?.name) return;
    setSaving(true);
    try {
      await db.savePizza(editing);
      await fetchPizzas();
      setEditing(null);
    } catch (err) {
      alert("Errore nel salvataggio");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Eliminare questa pizza dal menu?")) {
      try {
        await db.deletePizza(id);
        await fetchPizzas();
      } catch (err) {
        alert("Errore nella cancellazione");
      }
    }
  };

  const handleToggleActive = async (pizza: Pizza) => {
    try {
      await db.savePizza({ ...pizza, active: !pizza.active });
      await fetchPizzas();
    } catch (err) {
      alert("Errore aggiornamento stato");
    }
  };

  return (
    <Layout title="Gestione Pizze" onBack={onBack}>
      <div className="space-y-4">
        <Button fullWidth onClick={() => setEditing({})}>
          <Plus size={20} /> Aggiungi Nuova Pizza
        </Button>

        {loading ? (
          <div className="flex justify-center py-20"><div className="loading-spinner" /></div>
        ) : (
          <div className="space-y-3">
            {pizzas.map(p => (
              <Card key={p.id} className={`p-4 ${!p.active ? 'opacity-50 grayscale' : ''}`}>
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="font-bold text-lg">{p.name}</h3>
                    <p className="text-xs text-[#8E8E93]">{p.ingredients?.join(', ')}</p>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setEditing(p)} className="p-2 text-[#007AFF] bg-[#F2F2F7] rounded-full">
                      <Edit2 size={16} />
                    </button>
                    <button onClick={() => handleDelete(p.id)} className="p-2 text-[#FF3B30] bg-red-50 rounded-full">
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
                <div className="mt-3 pt-3 border-t border-[#F2F2F7] flex justify-between items-center">
                  <span className="text-xs font-bold text-[#8E8E93] uppercase">
                    Stato: {p.active ? 'ATTIVA' : 'DISATTIVATA'}
                  </span>
                  <button 
                    onClick={() => handleToggleActive(p)}
                    className={`text-xs font-bold px-3 py-1 rounded-full ${p.active ? 'bg-orange-100 text-orange-600' : 'bg-green-100 text-green-600'}`}
                  >
                    {p.active ? 'DISATTIVA' : 'ATTIVA'}
                  </button>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      {editing && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => !saving && setEditing(null)} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-4 shadow-2xl overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">{editing.id ? 'Modifica Pizza' : 'Nuova Pizza'}</h2>
              <button onClick={() => setEditing(null)} className="p-2 bg-[#F2F2F7] rounded-full">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Nome Pizza</label>
                <Input value={editing.name || ''} onChange={e => setEditing({...editing, name: e.target.value})} />
              </div>
              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Ingredienti (separati da virgola)</label>
                <Input 
                  value={editing.ingredients?.join(', ') || ''} 
                  onChange={e => setEditing({...editing, ingredients: e.target.value.split(',').map(s => s.trim())})} 
                />
              </div>
              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Allergeni (separati da virgola)</label>
                <Input 
                  value={editing.allergens?.join(', ') || ''} 
                  onChange={e => setEditing({...editing, allergens: e.target.value.split(',').map(s => s.trim())})} 
                />
              </div>
              <div className="flex items-center gap-2">
                <input 
                  type="checkbox" 
                  checked={editing.isVegetarian || false} 
                  onChange={e => setEditing({...editing, isVegetarian: e.target.checked})}
                />
                <label className="text-sm font-medium">Pizza Vegetariana</label>
              </div>
            </div>

            <Button fullWidth onClick={handleSave} disabled={saving}>
              {saving ? <div className="loading-spinner border-white border-t-transparent" /> : 'Salva Pizza'}
            </Button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default AdminPizzas;

import React, { useState, useEffect } from 'react';
import { User, Role } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { Plus, Edit2, Trash2, X, Lock } from '../components/Icons';

interface AdminUsersProps {
  onBack: () => void;
}

const AdminUsers: React.FC<AdminUsersProps> = ({ onBack }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [editing, setEditing] = useState<Partial<User> | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const data = await db.getUsers();
      setUsers(data);
    } catch (err) {
      alert("Errore caricamento utenti");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleSave = async () => {
    if (!editing?.firstName || !editing?.lastName || !editing?.pin) return;
    setSaving(true);
    try {
      await db.saveUser(editing);
      await fetchUsers();
      setEditing(null);
    } catch (err) {
      alert("Errore nel salvataggio. Forse il PIN è già in uso?");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Eliminare questo dipendente?")) {
      try {
        await db.deleteUser(id);
        await fetchUsers();
      } catch (err) {
        alert("Errore nella cancellazione");
      }
    }
  };

  const generatePin = () => {
    const pin = Math.floor(1000 + Math.random() * 9000).toString();
    setEditing({ ...editing, pin });
  };

  return (
    <Layout title="Gestione Personale" onBack={onBack}>
      <div className="space-y-4">
        <Button fullWidth onClick={() => setEditing({ role: Role.WORKER, pin: '' })}>
          <Plus size={20} /> Aggiungi Dipendente
        </Button>

        {loading ? (
          <div className="flex justify-center py-20"><div className="loading-spinner" /></div>
        ) : (
          <div className="space-y-3">
            {users.map(u => (
              <Card key={u.id} className={`p-4 ${!u.active ? 'opacity-50 grayscale' : ''}`}>
                <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white ${
                      u.role === Role.ADMIN ? 'bg-[#FF3B30]' : u.role === Role.SUPERVISOR ? 'bg-[#5856D6]' : 'bg-[#007AFF]'
                    }`}>
                      {u.firstName[0]}{u.lastName[0]}
                    </div>
                    <div>
                      <h3 className="font-bold">{u.firstName} {u.lastName}</h3>
                      <p className="text-[10px] font-bold text-[#8E8E93] uppercase tracking-wider">{u.role}</p>
                    </div>
                  </div>
                  <div className="flex gap-1">
                    <button onClick={() => setEditing(u)} className="p-2 text-[#007AFF] bg-[#F2F2F7] rounded-full">
                      <Edit2 size={16} />
                    </button>
                    <button onClick={() => handleDelete(u.id)} className="p-2 text-[#FF3B30] bg-red-50 rounded-full">
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
                <div className="mt-3 pt-3 border-t border-[#F2F2F7] flex justify-between items-center">
                  <div className="flex items-center gap-1 text-[#8E8E93]">
                    <Lock size={12} />
                    <span className="text-xs font-mono font-bold tracking-widest">{u.pin}</span>
                  </div>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${u.active ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                    {u.active ? 'ATTIVO' : 'SOSPESO'}
                  </span>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      {editing && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => !saving && setEditing(null)} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-4 shadow-2xl">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">{editing.id ? 'Modifica Dipendente' : 'Nuovo Dipendente'}</h2>
              <button onClick={() => setEditing(null)} className="p-2 bg-[#F2F2F7] rounded-full">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Nome</label>
                  <Input value={editing.firstName || ''} onChange={e => setEditing({...editing, firstName: e.target.value})} />
                </div>
                <div>
                  <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Cognome</label>
                  <Input value={editing.lastName || ''} onChange={e => setEditing({...editing, lastName: e.target.value})} />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Ruolo</label>
                <select 
                  className="w-full px-4 py-3 rounded-xl bg-white border border-[#C6C6C8] outline-none"
                  value={editing.role}
                  onChange={e => setEditing({...editing, role: e.target.value as Role})}
                >
                  <option value={Role.WORKER}>Worker (Dipendente)</option>
