import { createClient } from '@supabase/supabase-js';
import { User, Pizza, Order, Day, DayStatus, SlotTime } from '../types';

/**
 * CONFIGURAZIONE SUPABASE
 * Sostituisci i valori qui sotto con quelli trovati in: 
 * Supabase Project Settings > API
 */
const SUPABASE_URL = 'https://URL_DEL_TUO_PROGETTO.supabase.co';
const SUPABASE_ANON_KEY = 'CHIAVE_ANON_DEL_TUO_PROGETTO';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

class DB {
  // --- USERS ---
  async getUsers(): Promise<User[]> {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .order('last_name', { ascending: true });

    if (error) throw error;

    return data.map(u => ({
      id: u.id,
      firstName: u.first_name,
      lastName: u.last_name,
      pin: u.pin,
      role: u.role,
      active: u.active
    }));
  }

  async getUserByPin(pin: string): Promise<User | null> {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('pin', pin)
      .eq('active', true)
      .maybeSingle();

    if (error || !data) return null;

    return {
      id: data.id,
      firstName: data.first_name,
      lastName: data.last_name,
      pin: data.pin,
      role: data.role,
      active: data.active
    };
  }

  async saveUser(user: Partial<User>): Promise<void> {
    const payload = {
      first_name: user.firstName,
      last_name: user.lastName,
      pin: user.pin,
      role: user.role,
      active: user.active
    };

    if (user.id) {
      const { error } = await supabase.from('users').update(payload).eq('id', user.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('users').insert([payload]);
      if (error) throw error;
    }
  }

  async deleteUser(id: string): Promise<void> {
    const { error } = await supabase.from('users').delete().eq('id', id);
    if (error) throw error;
  }

  // --- PIZZAS ---
  async getPizzas(): Promise<Pizza[]> {
    const { data, error } = await supabase
      .from('pizzas')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;

    return data.map(p => ({
      id: p.id,
      name: p.name,
      description: p.description,
      ingredients: p.ingredients,
      allergens: p.allergens,
      active: p.active,
      isVegetarian: p.is_vegetarian
    }));
  }

  async savePizza(pizza: Partial<Pizza>): Promise<void> {
    const payload = {
      name: pizza.name,
      description: pizza.description,
      ingredients: pizza.ingredients,
      allergens: pizza.allergens,
      active: pizza.active,
      is_vegetarian: pizza.isVegetarian
    };

    if (pizza.id) {
      const { error } = await supabase.from('pizzas').update(payload).eq('id', pizza.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('pizzas').insert([payload]);
      if (error) throw error;
    }
  }

  async deletePizza(id: string): Promise<void> {
    const { error } = await supabase.from('pizzas').delete().eq('id', id);
    if (error) throw error;
  }

  // --- DAYS ---
  async getDays(): Promise<Day[]> {
    const { data, error } = await supabase
      .from('days')
      .select('*')
      .order('date', { ascending: false });

    if (error) throw error;

    return data.map(d => ({
      id: d.id,
      date: d.date,
      status: d.status,
      openedAt: d.opened_at,
      closedAt: d.closed_at
    }));
  }

  async getCurrentDay(): Promise<Day | null> {
    const today = new Date().toISOString().split('T')[0];
    const { data, error } = await supabase
      .from('days')
      .select('*')
      .eq('date', today)
      .maybeSingle();

    if (error || !data) return null;

    return {
      id: data.id,
      date: data.date,
      status: data.status,
      openedAt: data.opened_at,
      closedAt: data.closed_at
    };
  }

  async openDay(): Promise<Day> {
    const today = new Date().toISOString().split('T')[0];
    // Usiamo upsert per sicurezza se la giornata esiste già ma vogliamo riaprirla
    const { data, error } = await supabase
      .from('days')
      .upsert({ 
        date: today, 
        status: 'OPEN', 
        opened_at: new Date().toISOString() 
      }, { onConflict: 'date' })
      .select()
      .single();

    if (error) throw error;
    return {
      id: data.id,
      date: data.date,
      status: data.status,
      openedAt: data.opened_at,
      closedAt: data.closed_at
    };
  }

  async closeDay(): Promise<void> {
    const today = new Date().toISOString().split('T')[0];
    const { error } = await supabase
      .from('days')
      .update({ status: 'CLOSED', closed_at: new Date().toISOString() })
      .eq('date', today);

    if (error) throw error;
  }

  // --- ORDERS ---
  async getOrdersByDay(dayId: string): Promise<Order[]> {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('day_id', dayId);

    if (error) throw error;

    return data.map(o => ({
      id: o.id,
      dayId: o.day_id,
      userId: o.user_id,
      pizzaId: o.pizza_id,
      slotTime: o.slot_time as SlotTime,
      note: o.note,
      createdAt: o.created_at,
      updatedAt: o.updated_at
    }));
  }

  async getUserOrderToday(userId: string): Promise<Order | null> {
    const currentDay = await this.getCurrentDay();
    if (!currentDay) return null;

    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('user_id', userId)
      .eq('day_id', currentDay.id)
      .maybeSingle();

    if (error || !data) return null;

    return {
      id: data.id,
      dayId: data.day_id,
      userId: data.user_id,
      pizzaId: data.pizza_id,
      slotTime: data.slot_time as SlotTime,
      note: data.note,
      createdAt: data.created_at,
      updatedAt: data.updated_at
    };
  }

  async saveOrder(order: Partial<Order>): Promise<void> {
    // Sfruttiamo il vincolo UNIQUE(day_id, user_id) di Supabase per gestire l'upsert
    const payload = {
      day_id: order.dayId,
      user_id: order.userId,
      pizza_id: order.pizzaId,
      slot_time: order.slotTime,
      note: order.note,
      updated_at: new Date().toISOString()
    };

    const { error } = await supabase
      .from('orders')
      .upsert(payload, { onConflict: 'day_id,user_id' });

    if (error) throw error;
  }
}

