  const renderNumpad = (value: string, setValue: (v: string) => void, onConfirm: () => void, maxLength = 6) => (
    <div className="w-full">
      <div className="flex justify-center gap-4 mb-8">
        {[...Array(4)].map((_, i) => (
          <div key={i} className={`w-4 h-4 rounded-full border-2 transition-all ${value.length > i ? 'bg-[#007AFF] border-[#007AFF] scale-110' : 'bg-transparent border-[#C6C6C8]'}`} />
        ))}
      </div>
      <div className="grid grid-cols-3 gap-4">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d => (
          <button key={d} onClick={() => { if(value.length < maxLength) setValue(value + d); setError(''); }} className="h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA]">{d}</button>
        ))}
        <button onClick={() => setValue('')} className="h-16 rounded-full text-xs font-bold text-[#FF3B30]">CANCELLA</button>
        <button onClick={() => { if(value.length < maxLength) setValue(value + '0'); setError(''); }} className="h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA]">0</button>
        <button onClick={onConfirm} disabled={value.length < 4 || loading} className="h-16 rounded-full bg-[#007AFF] text-white text-sm font-bold shadow-md flex items-center justify-center">
          {loading ? <div className="loading-spinner border-white border-t-transparent" /> : 'OK'}
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#F2F2F7]">
      <div className="w-full max-w-sm flex flex-col items-center gap-8">

        <div className="flex flex-col items-center gap-3">
          <div className="w-32 h-32 bg-white rounded-full flex items-center justify-center shadow-xl p-0.5 overflow-hidden">
            <img 
              src="/logo.png" 
              alt="Pizza InTavola Logo" 
              className="w-full h-full object-contain scale-[1.05]"
              onError={(e) => {
                (e.target as HTMLImageElement).src = 'https://raw.githubusercontent.com/google/material-design-icons/master/png/maps/local_pizza/black/48dp/2x/local_pizza_black_48dp.png';
              }}
            />
          </div>
          <h1 className="text-3xl font-black tracking-tighter mt-4 text-[#1c1c1e]">Pizza InTavola</h1>
          <p className="text-[#8E8E93] font-medium text-center px-4">
            {mode === 'pin' ? 'Inserisci il tuo PIN personale' : 
             mode === 'reset-search' ? 'Cerca il tuo nome nella lista' :
             mode === 'reset-verify' ? `Ciao ${selectedUser?.firstName}, inserisci il Codice Locale` :
             'Imposta il tuo nuovo PIN di 4 cifre'}
          </p>
        </div>

        <div className="w-full">
          <div className="h-6 mb-4">
            {error && <p className={`text-center text-sm font-bold leading-tight px-4 ${error.includes('aggiornato') ? 'text-[#34C759]' : 'text-[#FF3B30]'}`}>{error}</p>}
          </div>

          {mode === 'pin' && (
            <>
              {renderNumpad(pin, setPin, handleLogin)}
              <button onClick={startReset} className="w-full mt-8 text-[#007AFF] font-bold text-sm">
                Non hai un PIN o l'hai dimenticato?
              </button>
            </>
          )}

          {mode === 'reset-search' && (
            <Card className="flex flex-col h-[400px]">
              <div className="p-3 border-b">
                <Input placeholder="Cerca il tuo nome..." value={search} onChange={e => setSearch(e.target.value)} autoFocus />
              </div>
              <div className="flex-1 overflow-y-auto">
                {filteredUsers.length > 0 ? filteredUsers.map(u => (
                  <button key={u.id} onClick={() => { setSelectedUser(u); setMode('reset-verify'); setError(''); }} className="w-full p-4 flex justify-between items-center border-b active:bg-[#F2F2F7]">
                    <span className="font-bold">{u.firstName} {u.lastName}</span>
                    <ChevronRight size={18} className="text-[#C6C6C8]" />
                  </button>
                )) : (
                  <p className="p-10 text-center text-[#8E8E93] text-sm italic">Nessun dipendente trovato</p>
                )}
              </div>
              <Button variant="ghost" onClick={() => setMode('pin')}>Annulla</Button>
            </Card>
          )}

          {mode === 'reset-verify' && (
            <div className="space-y-6">
              <div className="bg-white p-6 rounded-2xl ios-shadow space-y-4">
                <p className="text-xs font-bold text-[#8E8E93] uppercase text-center">Inserisci Codice Locale</p>
                <Input 
                  placeholder="Es: PIZZA2025" 
                  className="text-center font-bold tracking-widest uppercase" 
                  value={masterCodeInput} 
                  onChange={e => setMasterCodeInput(e.target.value)}
                  autoFocus
                />
                <Button fullWidth onClick={handleVerifyMasterCode} disabled={!masterCodeInput || loading}>Verifica Codice</Button>
                <Button variant="ghost" fullWidth onClick={() => setMode('reset-search')}>Torna indietro</Button>
              </div>
            </div>
          )}

          {mode === 'reset-new-pin' && renderNumpad(newPin, setNewPin, handleSetNewPin)}
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { User, Role } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { Plus, Edit2, Trash2, X, Lock, AlertCircle } from '../components/Icons';

interface AdminUsersProps {
  onBack: () => void;
}

const AdminUsers: React.FC<AdminUsersProps> = ({ onBack }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [editing, setEditing] = useState<Partial<User> | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const data = await db.getUsers();
      setUsers(data);
    } catch (err) {
      alert("Errore caricamento utenti");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleSave = async () => {
    if (!editing?.firstName || !editing?.lastName || !editing?.pin) return;
    setSaving(true);
    setError('');
    try {
      // CONTROLLO UNICITÀ PIN
      const isAvailable = await db.isPinAvailable(editing.pin, editing.id);
      if (!isAvailable) {
        setError('Questo PIN è già in uso da un altro utente attivo!');
        setSaving(false);
        return;
      }

      await db.saveUser(editing);
      await fetchUsers();
      setEditing(null);
    } catch (err) {
      setError("Errore nel salvataggio dei dati.");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Eliminare questo dipendente?")) {
      try {
        await db.deleteUser(id);
        await fetchUsers();
      } catch (err) {
        alert("Errore nella cancellazione");
      }
    }
  };

  const generatePin = async () => {
    let pin = '';
    let isUnique = false;
    let attempts = 0;

    // Proviamo a generare un PIN unico (max 10 tentativi per sicurezza)
    while (!isUnique && attempts < 10) {
      pin = Math.floor(1000 + Math.random() * 9000).toString();
      isUnique = await db.isPinAvailable(pin, editing?.id);
      attempts++;
    }

    setEditing(prev => prev ? { ...prev, pin } : null);
    setError('');
  };

  return (
    <Layout title="Gestione Personale" onBack={onBack}>
      <div className="space-y-4">
        <Button fullWidth onClick={() => { setEditing({ role: Role.WORKER, pin: '', active: true }); setError(''); }}>
          <Plus size={20} /> Aggiungi Dipendente
        </Button>

        {loading ? (
          <div className="flex justify-center py-20"><div className="loading-spinner" /></div>
        ) : (
          <div className="space-y-3">
            {users.map(u => (
              <Card key={u.id} className={`p-4 ${!u.active ? 'opacity-50 grayscale' : ''}`}>
                <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white ${
                      u.role === Role.ADMIN ? 'bg-[#FF3B30]' : u.role === Role.SUPERVISOR ? 'bg-[#5856D6]' : 'bg-[#007AFF]'
                    }`}>
                      {u.firstName[0]}{u.lastName[0]}
                    </div>
                    <div>
                      <h3 className="font-bold">{u.firstName} {u.lastName}</h3>
                      <p className="text-[10px] font-bold text-[#8E8E93] uppercase tracking-wider">{u.role}</p>
                    </div>
                  </div>
                  <div className="flex gap-1">
                    <button onClick={() => { setEditing(u); setError(''); }} className="p-2 text-[#007AFF] bg-[#F2F2F7] rounded-full">
                      <Edit2 size={16} />
                    </button>
                    <button onClick={() => handleDelete(u.id)} className="p-2 text-[#FF3B30] bg-red-50 rounded-full">
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
                <div className="mt-3 pt-3 border-t border-[#F2F2F7] flex justify-between items-center">
                  <div className="flex items-center gap-1 text-[#8E8E93]">
                    <Lock size={12} />
                    <span className="text-xs font-mono font-bold tracking-widest">{u.pin}</span>
                  </div>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${u.active ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                    {u.active ? 'ATTIVO' : 'SOSPESO'}
                  </span>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      {editing && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => !saving && setEditing(null)} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-4 shadow-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">{editing.id ? 'Modifica Dipendente' : 'Nuovo Dipendente'}</h2>
              <button onClick={() => setEditing(null)} className="p-2 bg-[#F2F2F7] rounded-full">
                <X size={20} />
              </button>
            </div>

            {error && (
              <div className="bg-red-50 p-3 rounded-xl border border-red-100 flex items-center gap-2 text-[#FF3B30] text-sm font-bold">
                <AlertCircle size={18} />
                {error}
              </div>
            )}

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Nome</label>
                  <Input value={editing.firstName || ''} onChange={e => setEditing({...editing, firstName: e.target.value})} />
                </div>
                <div>
                  <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Cognome</label>
                  <Input value={editing.lastName || ''} onChange={e => setEditing({...editing, lastName: e.target.value})} />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">Ruolo</label>
                <select 
                  className="w-full px-4 py-3 rounded-xl bg-white border border-[#C6C6C8] outline-none"
                  value={editing.role}
                  onChange={e => setEditing({...editing, role: e.target.value as Role})}
                >
                  <option value={Role.WORKER}>Worker (Dipendente)</option>
                  <option value={Role.SUPERVISOR}>Supervisor (Solo Lettura)</option>
                  <option value={Role.ADMIN}>Admin (Completo)</option>
                </select>
              </div>

              <div className="flex items-end gap-2">
                <div className="flex-1">
                  <label className="text-xs font-bold text-[#8E8E93] uppercase pl-1">PIN Personale</label>
                  <Input 
                    placeholder="4-6 cifre"
                    value={editing.pin || ''} 
                    onChange={e => { setError(''); setEditing({...editing, pin: e.target.value}); }} 
                  />
                </div>
                <Button variant="secondary" onClick={generatePin} className="!py-[14px]">
                  Genera
                </Button>
              </div>

              <div className="flex items-center gap-2 p-1">
                <input 
                  id="user-active"
                  type="checkbox" 
                  className="w-5 h-5 accent-[#007AFF]"
                  checked={editing.active ?? true} 
                  onChange={e => setEditing({...editing, active: e.target.checked})}
                />
                <label htmlFor="user-active" className="text-sm font-medium">Utente Attivo / Abilitato</label>
              </div>
            </div>

            <Button fullWidth onClick={handleSave} disabled={saving}>
              {saving ? <div className="loading-spinner border-white border-t-transparent" /> : 'Salva Dipendente'}
            </Button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default AdminUsers;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { PizzaIcon, ClockIcon, Search, Check, AlertCircle, X } from '../components/Icons';
import { isBeforeCutoff } from '../services/utils';
import { SLOT_TIMES } from '../constants';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
}

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout }) => {
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [note, setNote] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);

  const canOrder = useMemo(() => {
    return currentDay?.status === DayStatus.OPEN && isBeforeCutoff();
  }, [currentDay]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, day, order] = await Promise.all([
          db.getPizzas(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id)
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setCurrentDay(day);
        setMyOrder(order);
      } catch (err) {
        setMessage({ text: "Errore nel caricamento dei dati", type: "error" });
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const filteredPizzas = pizzas.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
  );

  const handleSelectPizza = (pizza: Pizza) => {
    if (!canOrder && !isEditing) return;
    setSelectedPizza(pizza);
  };

  const handleConfirmOrder = async () => {
    if (!selectedPizza || !currentDay) return;

    setSubmitting(true);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay.id,
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        note: note
      };

      await db.saveOrder(order);
      const updatedOrder = await db.getUserOrderToday(user.id);
      setMyOrder(updatedOrder);
      setSelectedPizza(null);
      setNote('');
      setIsEditing(false);

      // Messaggio di successo personalizzato come richiesto
      setMessage({ text: "Ordine Confermato ed inviato", type: "success" });

      // Auto-dismiss dopo 3 secondi
      setTimeout(() => setMessage(null), 3000);
    } catch (err) {
      setMessage({ text: "Errore durante il salvataggio", type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  const handleEdit = () => {
    if (!myOrder) return;
    const pizza = pizzas.find(p => p.id === myOrder.pizzaId);
    if (pizza) {
      setSelectedPizza(pizza);
      setSlot(myOrder.slotTime);
      setNote(myOrder.note);
      setIsEditing(true);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex flex-col items-center justify-center py-20 gap-4">
          <div className="loading-spinner !w-10 !h-10" />
          <p className="text-[#8E8E93] font-medium">Recupero menu in corso...</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Ordina Pizza" onLogout={onLogout}>
      {/* Toast / Banner Messaggio di Successo/Errore stile iOS */}
      {message && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl flex items-center gap-3 transition-all transform animate-in fade-in slide-in-from-top-10 duration-500 ease-out ${
          message.type === 'success' ? 'bg-[#34C759] text-white' : 'bg-[#FF3B30] text-white'
        }`}>
          {message.type === 'success' ? <Check size={20} /> : <AlertCircle size={20} />}
          <p className="font-bold text-sm flex-1">{message.text}</p>
          <button onClick={() => setMessage(null)} className="opacity-70 hover:opacity-100 p-1">
            <X size={18} />
          </button>
        </div>
      )}

      {/* Banner Stato */}
      {!currentDay ? (
        <div className="bg-[#FF9500] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <AlertCircle size={24} />
          <div>
            <p className="font-bold">Giornata non ancora aperta</p>
            <p className="text-xs opacity-90">L'admin aprirà le ordinazioni a breve.</p>
          </div>
        </div>
      ) : !canOrder ? (
        <div className="bg-[#FF3B30] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <AlertCircle size={24} />
          <div>
            <p className="font-bold">Ordini chiusi 🔒</p>
            <p className="text-xs opacity-90">Oltre le 16:30 o giornata terminata. Non puoi più ordinare o modificare.</p>
          </div>
        </div>
      ) : (
        <div className="bg-[#34C759] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <Check size={24} />
          <div>
            <p className="font-bold">Ordini Aperti</p>
            <p className="text-xs opacity-90">Puoi ordinare o modificare fino alle 16:30.</p>
          </div>
        </div>
      )}

      {/* Messaggio di Benvenuto */}
      <div className="mb-6 px-1">
        <h1 className="text-2xl font-bold tracking-tight text-[#1c1c1e]">
          Ciao! {user.firstName},
        </h1>
        <p className="text-[#8E8E93] font-medium">quale pizza mangi oggi?</p>
      </div>

      {/* Ordine Esistente */}
      {myOrder && !selectedPizza && !isEditing && (
        <Card className="p-4 mb-6 border-2 border-[#34C759]">
          <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-xs font-bold text-[#34C759] uppercase mb-1">Il tuo ordine di oggi</p>
              <h2 className="text-xl font-bold">
                {pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza non disponibile'}
              </h2>
            </div>
            <div className="bg-[#F2F2F7] px-3 py-1 rounded-full flex items-center gap-1">
              <ClockIcon size={14} />
              <span className="text-sm font-bold">{myOrder.slotTime}</span>
            </div>
          </div>
          {myOrder.note && (
            <div className="bg-[#F2F2F7] p-2 rounded-lg mb-4">
              <p className="text-xs text-[#8E8E93]">Nota:</p>
              <p className="text-sm italic">"{myOrder.note}"</p>
            </div>
          )}
          {canOrder && (
            <Button onClick={handleEdit} variant="secondary" fullWidth>
              Modifica Ordine
            </Button>
          )}
        </Card>
      )}

      {/* Menu Pizze */}
      {(!myOrder || isEditing) && !selectedPizza && (
        <>
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
            <Input 
              placeholder="Cerca pizza o ingrediente..." 
              className="pl-10 bg-white"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="space-y-3">
            {filteredPizzas.length > 0 ? filteredPizzas.map(pizza => (
              <Card 
                key={pizza.id} 
                className={`p-4 cursor-pointer active:scale-95 transition-all ${
                  selectedPizza?.id === pizza.id ? 'ring-2 ring-[#007AFF]' : ''
                }`}
              >
                <div onClick={() => handleSelectPizza(pizza)}>
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase">Veg</span>}
                  </div>
                  <p className="text-sm text-[#8E8E93] line-clamp-2">{pizza.ingredients?.join(', ')}</p>
                  <div className="mt-2 flex gap-1 flex-wrap">
                    {pizza.allergens?.map(a => (
                      <span key={a} className="text-[10px] bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100 font-medium">
                        {a}
                      </span>
                    ))}
                  </div>
                </div>
              </Card>
            )) : (
              <p className="text-center text-[#8E8E93] py-10">Nessuna pizza trovata</p>
            )}
          </div>
        </>
      )}

      {/* Bottom Sheet Order Detail */}
      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => { if (!submitting) { setSelectedPizza(null); setIsEditing(false); } }} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-[#E5E5EA] rounded-full mx-auto mb-2" />

            <div className="flex justify-between items-start">
              <div>
                <h2 className="text-2xl font-bold">{selectedPizza.name}</h2>
                <p className="text-[#8E8E93]">{selectedPizza.ingredients?.join(', ')}</p>
              </div>
              <button disabled={submitting} onClick={() => { setSelectedPizza(null); setIsEditing(false); }} className="bg-[#F2F2F7] p-2 rounded-full disabled:opacity-50">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-3">
              <label className="text-sm font-bold text-[#8E8E93] uppercase">Orario Consegna</label>
              <SegmentedControl 
                options={SLOT_TIMES}
                selected={slot}
                onChange={(v) => setSlot(v as SlotTime)}
              />
            </div>

            <div className="space-y-3">
              <label className="text-sm font-bold text-[#8E8E93] uppercase">Note (opzionale)</label>
              <Input 
                placeholder="Es. Senza cipolla, ben cotta..."
                value={note}
                disabled={submitting}
                onChange={(e) => setNote(e.target.value)}
              />
            </div>

            <div className="pt-2">
