    const payload = { 
      day_id: order.dayId, 
      user_id: order.userId, 
      pizza_id: order.pizzaId, 
      slot_time: order.slotTime, 
      note: order.note, 
      updated_at: new Date().toISOString() 
    };
    const { error } = await supabase.from('orders').upsert(payload, { onConflict: 'day_id,user_id' });
    if (error) throw error;
  }
}

