export interface GlobalSettings {
  master_code: string;
  override_cutoff: boolean;
}

class DB {
  async getSettings(): Promise<GlobalSettings> {
    const { data, error } = await supabase.from('settings').select('*').eq('id', 'global').maybeSingle();
    if (error || !data) return { master_code: 'PIZZA2025', override_cutoff: false }; 
    return {
      master_code: data.master_code,
      override_cutoff: !!data.override_cutoff
    };
  }

  async getMasterCode(): Promise<string> {
    const settings = await this.getSettings();
    return settings.master_code;
  }

  async updateMasterCode(newCode: string): Promise<void> {
    const { error } = await supabase.from('settings').upsert({ id: 'global', master_code: newCode }, { onConflict: 'id' });
    if (error) throw error;
  }

  async updateOverrideCutoff(value: boolean): Promise<void> {
    const { error } = await supabase.from('settings').upsert({ id: 'global', override_cutoff: value }, { onConflict: 'id' });
    if (error) throw error;
  }

  async getUsers(): Promise<User[]> {
    const { data, error } = await supabase.from('users').select('*').order('last_name', { ascending: true });
    if (error) throw error;
    return data.map(u => ({ 
      id: u.id, 
      firstName: u.first_name, 
      lastName: u.last_name, 
      email: u.email || '', 
      pin: u.pin, 
      role: u.role, 
      active: u.active 
    }));
  }

  async getUserByPin(pin: string): Promise<User | null> {
    if (!pin) return null;
    const { data, error } = await supabase.from('users').select('*').eq('pin', pin).eq('active', true).maybeSingle();
    if (error || !data) return null;
    return { 
      id: data.id, 
      firstName: data.first_name, 
      lastName: data.last_name, 
      email: data.email || '',
      pin: data.pin, 
      role: data.role, 
      active: data.active 
    };
  }

  async isPinAvailable(pin: string, excludeUserId?: string): Promise<boolean> {
    let query = supabase.from('users').select('id').eq('pin', pin).eq('active', true);
    if (excludeUserId) {
      query = query.neq('id', excludeUserId);
    }
    const { data, error } = await query.maybeSingle();
    if (error) return true; 
    return !data;
  }

  async updateUserPin(userId: string, newPin: string): Promise<void> {
    const { error } = await supabase.from('users').update({ pin: newPin }).eq('id', userId);
    if (error) throw error;
  }

  async saveUser(user: Partial<User>): Promise<void> {
    const payload = { 
      first_name: user.firstName, 
      last_name: user.lastName, 
      email: user.email?.toLowerCase().trim(), 
      pin: user.pin, 
      role: user.role, 
      active: user.active 
    };

    if (user.id) {
      const { error } = await supabase.from('users').update(payload).eq('id', user.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('users').insert([payload]);
      if (error) throw error;
    }
  }

  async deleteUser(id: string): Promise<void> {
    const { error } = await supabase.from('users').delete().eq('id', id);
    if (error) throw error;
  }

  async recoverPin(email: string): Promise<{ success: boolean; message?: string }> {
    try {
      const { data, error } = await supabase.functions.invoke('recover-pin', {
        body: { email: email.toLowerCase().trim() }
      });

      if (error) {
        if (error.message?.includes('404')) {
          return { success: false, message: 'Funzione di invio email non configurata su Supabase.' };
        }
        throw error;
      }

      return { success: true };
    } catch (err: any) {
      console.error("Errore recupero PIN:", err);
      return { success: false, message: err.message || 'Errore tecnico durante l\'invio.' };
    }
  }

  async getPizzas(): Promise<Pizza[]> {
    const { data, error } = await supabase.from('pizzas').select('*').order('name', { ascending: true });
    if (error) throw error;
    return data.map(p => ({ 
      id: p.id, 
      name: p.name, 
      description: p.description, 
      ingredients: p.ingredients, 
      allergens: p.allergens, 
      active: p.active, 
      isVegetarian: p.is_vegetarian 
    }));
  }

  async savePizza(pizza: Partial<Pizza>): Promise<void> {
    const payload = { 
      name: pizza.name, 
      description: pizza.description, 
      ingredients: pizza.ingredients, 
      allergens: pizza.allergens, 
      active: pizza.active, 
      is_vegetarian: pizza.isVegetarian 
    };
    if (pizza.id) {
      const { error } = await supabase.from('pizzas').update(payload).eq('id', pizza.id);
      if (error) throw error;
    } else {
      const { error } = await supabase.from('pizzas').insert([payload]);
      if (error) throw error;
    }
  }

  async deletePizza(id: string): Promise<void> {
    const { error } = await supabase.from('pizzas').delete().eq('id', id);
    if (error) throw error;
  }

  async getDays(): Promise<Day[]> {
    const { data, error } = await supabase.from('days').select('*').order('date', { ascending: false });
    if (error) throw error;
    return data.map(d => ({ 
      id: d.id, 
      date: d.date, 
      status: d.status, 
      openedAt: d.opened_at, 
      closedAt: d.closed_at 
    }));
  }

  async getCurrentDay(): Promise<Day | null> {
    const today = new Date().toISOString().split('T')[0];
    const { data, error } = await supabase.from('days').select('*').eq('date', today).maybeSingle();
    if (error || !data) return null;
    return { 
      id: data.id, 
      date: data.date, 
      status: data.status, 
      openedAt: data.opened_at, 
      closedAt: data.closed_at 
    };
  }

  async openDay(): Promise<Day> {
    const today = new Date().toISOString().split('T')[0];
    const { data, error } = await supabase.from('days').upsert({ 
      date: today, 
      status: 'OPEN', 
      opened_at: new Date().toISOString() 
    }, { onConflict: 'date' }).select().single();
    if (error) throw error;
    return { 
      id: data.id, 
      date: data.date, 
      status: data.status, 
      openedAt: data.opened_at, 
      closedAt: data.closed_at 
    };
  }

  async closeDay(): Promise<void> {
    const today = new Date().toISOString().split('T')[0];
    const { error } = await supabase.from('days').update({ 
      status: 'CLOSED', 
      closed_at: new Date().toISOString() 
    }).eq('date', today);
    if (error) throw error;
  }

  async getOrdersByDay(dayId: string): Promise<Order[]> {
    const { data, error } = await supabase.from('orders').select('*').eq('day_id', dayId);
    if (error) throw error;
    return data.map(o => ({ 
      id: o.id, 
      dayId: o.day_id, 
      userId: o.user_id, 
      pizzaId: o.pizza_id, 
      slot_time: o.slot_time as SlotTime, 
      note: o.note, 
      createdAt: o.created_at, 
      updatedAt: o.updated_at 
    }));
  }

  async getUserOrderToday(userId: string): Promise<Order | null> {
    const currentDay = await this.getCurrentDay();
    if (!currentDay) return null;
    const { data, error } = await supabase.from('orders').select('*').eq('user_id', userId).eq('day_id', currentDay.id).maybeSingle();
    if (error || !data) return null;
    return { 
      id: data.id, 
      dayId: data.day_id, 
      userId: data.user_id, 
      pizzaId: data.pizza_id, 
      slotTime: data.slot_time as SlotTime, 
      note: data.note, 
      createdAt: data.created_at, 
      updatedAt: data.updated_at 
    };
  }

  async saveOrder(order: Partial<Order>): Promise<void> {
    const payload = { 
      day_id: order.dayId, 
      user_id: order.userId, 
      pizza_id: order.pizzaId, 
      slot_time: order.slotTime, 
      note: order.note, 
      updated_at: new Date().toISOString() 
    };
    const { error } = await supabase.from('orders').upsert(payload, { onConflict: 'day_id,user_id' });
    if (error) throw error;
  }
}

export const db = new DB();

import React, { useState } from 'react';
import { db } from '../services/db';
import { User, Role } from '../types';
import { Button, Input, Card } from '../components/UI';
import { ChevronRight, X, AlertCircle, Check } from '../components/Icons';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<'pin' | 'reset-search' | 'reset-verify' | 'reset-new-pin'>('pin');

  const [showRecover, setShowRecover] = useState(false);
  const [recoverEmail, setRecoverEmail] = useState('');
  const [isRecovering, setIsRecovering] = useState(false);
  const [recoverStatus, setRecoverStatus] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const [workerUsers, setWorkerUsers] = useState<User[]>([]);
  const [search, setSearch] = useState('');
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [masterCodeInput, setMasterCodeInput] = useState('');
  const [newPin, setNewPin] = useState('');

  const handleLogin = async () => {
    if (pin.length < 4) return;
    setLoading(true);
    setError('');
    try {
      const user = await db.getUserByPin(pin);
      if (user) {
        onLogin(user);
      } else {
        setError('PIN non valido');
        setPin('');
      }
    } catch (err) {
      setError('Errore di connessione');
    } finally {
      setLoading(false);
    }
  };

  const startReset = async () => {
    setLoading(true);
    try {
      const users = await db.getUsers();
      const onlyWorkers = users.filter(u => u.active && u.role === Role.WORKER);
      setWorkerUsers(onlyWorkers);
      setMode('reset-search');
    } catch (err) {
      setError('Errore nel recupero utenti');
    } finally {
      setLoading(false);
    }
  };

  const handleRecoverPin = async () => {
    if (!recoverEmail) return;
    setIsRecovering(true);
    setRecoverStatus(null);

    try {
      const result = await db.recoverPin(recoverEmail);
      if (result.success) {
        setRecoverStatus({ 
          type: 'success', 
          message: 'Se l’email è registrata, riceverai un messaggio con il tuo PIN.' 
        });
      } else {
        setRecoverStatus({ 
          type: 'error', 
          message: result.message || 'Errore durante l\'invio. Riprova più tardi.' 
        });
      }
    } catch (err) {
      setRecoverStatus({ 
        type: 'error', 
        message: 'Impossibile contattare il servizio di recupero.' 
      });
    } finally {
      setIsRecovering(false);
    }
  };

  const handleVerifyMasterCode = async () => {
    setLoading(true);
    try {
      const actualCode = await db.getMasterCode();
      if (masterCodeInput.toUpperCase() === actualCode.toUpperCase()) {
        setMode('reset-new-pin');
      } else {
        setError('Codice Locale errato');
      }
    } catch (err) {
      setError('Errore verifica');
    } finally {
      setLoading(false);
    }
  };

  const handleSetNewPin = async () => {
    if (!selectedUser || newPin.length < 4) return;
    setLoading(true);
    setError('');
    try {
      const isAvailable = await db.isPinAvailable(newPin);
      if (!isAvailable) {
        setError('Questo PIN è già in uso da un altro dipendente.');
        setNewPin('');
        setLoading(false);
        return;
      }

      await db.updateUserPin(selectedUser.id, newPin);
      setPin(newPin);
      setMode('pin');
      setError('PIN aggiornato! Ora puoi entrare.');
      setNewPin('');
      setMasterCodeInput('');
      setSelectedUser(null);
    } catch (err) {
      setError('Errore aggiornamento PIN');
    } finally {
      setLoading(false);
    }
  };

  const filteredUsers = workerUsers.filter(u => 
    `${u.firstName} ${u.lastName}`.toLowerCase().includes(search.toLowerCase())
  );

  const renderNumpad = (value: string, setValue: (v: string) => void, onConfirm: () => void, maxLength = 6) => (
    <div className="w-full">
      <div className="flex justify-center gap-4 mb-8">
        {[...Array(4)].map((_, i) => (
          <div key={i} className={`w-4 h-4 rounded-full border-2 transition-all ${value.length > i ? 'bg-[#007AFF] border-[#007AFF] scale-110' : 'bg-transparent border-[#C6C6C8]'}`} />
        ))}
      </div>
      <div className="grid grid-cols-3 gap-4">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d => (
          <button key={d} onClick={() => { if(value.length < maxLength) setValue(value + d); setError(''); }} className="h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA]">{d}</button>
        ))}
        <button onClick={() => setValue('')} className="h-16 rounded-full text-xs font-bold text-[#FF3B30]">CANCELLA</button>
        <button onClick={() => { if(value.length < maxLength) setValue(value + '0'); setError(''); }} className="h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA]">0</button>
        <button onClick={onConfirm} disabled={value.length < 4 || loading} className="h-16 rounded-full bg-[#007AFF] text-white text-sm font-bold shadow-md flex items-center justify-center">
          {loading ? <div className="loading-spinner border-white border-t-transparent" /> : 'OK'}
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#F2F2F7]">
      <div className="w-full max-sm flex flex-col items-center gap-8">

        <div className="flex flex-col items-center gap-3">
          <div className="w-32 h-32 bg-white rounded-full flex items-center justify-center shadow-xl p-0.5 overflow-hidden">
            <img 
              src="/logo.png" 
              alt="Pizza InTavola Logo" 
              className="w-full h-full object-contain scale-[1.05]"
              onError={(e) => {
                (e.target as HTMLImageElement).src = 'https://raw.githubusercontent.com/google/material-design-icons/master/png/maps/local_pizza/black/48dp/2x/local_pizza_black_48dp.png';
              }}
            />
          </div>
          <h1 className="text-3xl font-black tracking-tighter mt-4 text-[#1c1c1e]">Pizza InTavola</h1>
          <p className="text-[#8E8E93] font-medium text-center px-4">
            {mode === 'pin' ? 'Inserisci il tuo PIN personale' : 
             mode === 'reset-search' ? 'Cerca il tuo nome nella lista' :
             mode === 'reset-verify' ? `Ciao ${selectedUser?.firstName}, inserisci il Codice Locale` :
             'Imposta il tuo nuovo PIN di 4 cifre'}
          </p>
        </div>

        <div className="w-full">
          <div className="h-6 mb-4">
            {error && <p className={`text-center text-sm font-bold leading-tight px-4 ${error.includes('aggiornato') ? 'text-[#34C759]' : 'text-[#FF3B30]'}`}>{error}</p>}
          </div>

          {mode === 'pin' && (
            <div className="flex flex-col gap-4">
              {renderNumpad(pin, setPin, handleLogin)}
              <div className="flex flex-col gap-3 mt-4">
                <button onClick={() => { setShowRecover(true); setRecoverStatus(null); }} className="w-full text-[#007AFF] font-bold text-sm">
                  Non ricordi il PIN?
                </button>
                <button onClick={startReset} className="w-full text-[#8E8E93] font-medium text-xs">
                  Primo accesso o reset manuale
                </button>
              </div>
            </div>
          )}

          {mode === 'reset-search' && (
            <Card className="flex flex-col h-[400px]">
              <div className="p-3 border-b">
                <Input placeholder="Cerca il tuo nome..." value={search} onChange={e => setSearch(e.target.value)} autoFocus />
              </div>
              <div className="flex-1 overflow-y-auto">
                {filteredUsers.length > 0 ? filteredUsers.map(u => (
                  <button key={u.id} onClick={() => { setSelectedUser(u); setMode('reset-verify'); setError(''); }} className="w-full p-4 flex justify-between items-center border-b active:bg-[#F2F2F7]">
                    <span className="font-bold">{u.firstName} {u.lastName}</span>
                    <ChevronRight size={18} className="text-[#C6C6C8]" />
                  </button>
                )) : (
                  <p className="p-10 text-center text-[#8E8E93] text-sm italic">Nessun dipendente trovato</p>
                )}
              </div>
              <Button variant="ghost" onClick={() => setMode('pin')}>Annulla</Button>
            </Card>
          )}

          {mode === 'reset-verify' && (
            <div className="space-y-6">
              <div className="bg-white p-6 rounded-2xl ios-shadow space-y-4">
                <p className="text-xs font-bold text-[#8E8E93] uppercase text-center">Inserisci Codice Locale</p>
                <Input 
                  placeholder="Es: PIZZA2025" 
                  className="text-center font-bold tracking-widest uppercase" 
                  value={masterCodeInput} 
                  onChange={e => setMasterCodeInput(e.target.value)}
                  autoFocus
                />
                <Button fullWidth onClick={handleVerifyMasterCode} disabled={!masterCodeInput || loading}>Verifica Codice</Button>
                <Button variant="ghost" fullWidth onClick={() => setMode('reset-search')}>Torna indietro</Button>
              </div>
            </div>
          )}

          {mode === 'reset-new-pin' && renderNumpad(newPin, setNewPin, handleSetNewPin)}
        </div>
      </div>

      {showRecover && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => !isRecovering && setShowRecover(false)} />
          <div className="relative bg-white rounded-t-[32px] p-8 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-[#E5E5EA] rounded-full mx-auto mb-2" />

            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-bold">Recupero PIN</h2>
              <button disabled={isRecovering} onClick={() => setShowRecover(false)} className="bg-[#F2F2F7] p-2 rounded-full">
                <X size={20} />
              </button>
            </div>

            {recoverStatus?.type === 'success' ? (
              <div className="bg-[#F2F2F7] p-6 rounded-2xl flex flex-col items-center gap-4 text-center">
                <div className="w-12 h-12 bg-[#34C759] rounded-full flex items-center justify-center text-white">
                   <Check size={24} />
                </div>
                <p className="font-bold text-[#1c1c1e]">{recoverStatus.message}</p>
                <Button fullWidth onClick={() => setShowRecover(false)}>Chiudi</Button>
              </div>
            ) : (
              <>
                <div className="space-y-4">
                  {recoverStatus?.type === 'error' && (
                    <div className="p-3 bg-red-50 border border-red-100 rounded-xl flex items-center gap-2 text-[#FF3B30] text-xs font-bold">
                      <AlertCircle size={16} />
                      {recoverStatus.message}
                    </div>
                  )}
                  <p className="text-[#8E8E93] text-sm font-medium">
                    Inserisci l'email registrata. Riceverai un messaggio con il tuo PIN attuale.
                  </p>
                  <Input 
                    type="email"
                    placeholder="La tua email personale"
                    value={recoverEmail}
                    onChange={(e) => setRecoverEmail(e.target.value)}
                    disabled={isRecovering}
                    autoFocus
                  />
                </div>
                <div className="pt-2 flex flex-col gap-3">
                  <Button fullWidth onClick={handleRecoverPin} disabled={!recoverEmail || isRecovering}>
                    {isRecovering ? <div className="loading-spinner border-white border-t-transparent" /> : 'Invia PIN via Email'}
                  </Button>
                  <p className="text-[10px] text-center text-[#8E8E93]">
                    Se l'invio fallisce, usa l'opzione "Reset manuale" nella schermata principale usando il codice affisso in bacheca.
                  </p>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Login;

