import React, { useState, useEffect } from 'react';
import { AuthState, User, Role } from './types';
import { db } from './services/db';
import LoginView from './views/Login';
import WorkerDashboard from './views/WorkerDashboard';
import AdminDashboard from './views/AdminDashboard';
import AdminPizzas from './views/AdminPizzas';
import AdminUsers from './views/AdminUsers';
import AdminHistory from './views/AdminHistory';
import { Fingerprint, X } from './components/Icons';
import { Button } from './components/UI';

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('pizzastaff_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const [view, setView] = useState<'dashboard' | 'pizzas' | 'users' | 'history'>('dashboard');
  const [showBiometricPrompt, setShowBiometricPrompt] = useState(false);
  const [isBiometricSupported, setIsBiometricSupported] = useState(false);

  useEffect(() => {
    localStorage.setItem('pizzastaff_auth', JSON.stringify(auth));

    const checkSupport = async () => {
      const supported = !!(window.PublicKeyCredential && 
        await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable());
      setIsBiometricSupported(supported);
    };
    checkSupport();
  }, [auth]);

  const handleLogin = (user: User) => {
    setAuth({ user, isAuthenticated: true });

    const biometricEnabled = localStorage.getItem('pizzastaff_biometric_enabled') === 'true';
    const hasDeclined = localStorage.getItem('pizzastaff_biometric_declined') === 'true';

    if (!biometricEnabled && !hasDeclined && window.PublicKeyCredential) {
      setTimeout(() => setShowBiometricPrompt(true), 1500);
    }
  };

  const handleLogout = () => {
    setAuth({ user: null, isAuthenticated: false });
    setView('dashboard');
  };

  const enableBiometrics = () => {
    if (auth.user?.pin) {
      localStorage.setItem('pizzastaff_stored_pin', auth.user.pin);
      localStorage.setItem('pizzastaff_biometric_enabled', 'true');
      localStorage.removeItem('pizzastaff_biometric_declined');
      setShowBiometricPrompt(false);
    }
  };

  const declineBiometrics = () => {
    localStorage.setItem('pizzastaff_biometric_declined', 'true');
    setShowBiometricPrompt(false);
  };

  if (!auth.isAuthenticated || !auth.user) {
    return <LoginView onLogin={handleLogin} />;
  }

  return (
    <div className="bg-[#F2F2F7] min-h-screen">
      {auth.user?.role === Role.ADMIN || auth.user?.role === Role.SUPERVISOR ? (
        <>
          {view === 'pizzas' && <AdminPizzas onBack={() => setView('dashboard')} />}
          {view === 'users' && <AdminUsers onBack={() => setView('dashboard')} />}
          {view === 'history' && <AdminHistory onBack={() => setView('dashboard')} />}
          {view === 'dashboard' && <AdminDashboard user={auth.user!} onLogout={handleLogout} onNavigate={(v: any) => setView(v)} />}
        </>
      ) : (
        <WorkerDashboard user={auth.user!} onLogout={handleLogout} />
      )}

      {showBiometricPrompt && isBiometricSupported && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={declineBiometrics} />
          <div className="relative bg-white w-full max-w-sm rounded-[32px] p-8 shadow-2xl animate-in slide-in-from-bottom duration-500 text-center space-y-6">
            <div className="w-20 h-20 bg-[#F2F2F7] text-[#007AFF] rounded-full flex items-center justify-center mx-auto">
              <Fingerprint size={40} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-[#1c1c1e]">Accesso Rapido</h3>
              <p className="text-sm text-[#8E8E93] mt-2 leading-relaxed">
                Vuoi attivare il Face ID o l'impronta digitale per accedere più velocemente la prossima volta?
              </p>
            </div>
            <div className="space-y-3">
              <Button fullWidth onClick={enableBiometrics}>Attiva Ora</Button>
              <button 
                onClick={declineBiometrics}
                className="w-full py-2 text-sm font-bold text-[#8E8E93] uppercase tracking-widest"
              >
                Magari più tardi
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { PizzaIcon, ClockIcon, Search, Check, AlertCircle, X, Fingerprint, Lock } from '../components/Icons';
import { isBeforeCutoff } from '../services/utils';
import { SLOT_TIMES } from '../constants';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
}

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout }) => {
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [overrideActive, setOverrideActive] = useState(false);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [note, setNote] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  const canOrder = useMemo(() => {
    if (!currentDay || currentDay.status !== DayStatus.OPEN) return false;
    if (overrideActive) return true;
    return isBeforeCutoff();
  }, [currentDay, overrideActive]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, day, order, settings] = await Promise.all([
          db.getPizzas(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setCurrentDay(day);
        setMyOrder(order);
        setOverrideActive(settings.override_cutoff);
      } catch (err) {
        setMessage({ text: "Errore nel caricamento dei dati", type: "error" });
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const toggleBiometrics = () => {
    if (biometricEnabled) {
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
      setMessage({ text: "Face ID / Impronta disattivata", type: "success" });
    } else {
      localStorage.setItem('pizzastaff_stored_pin', user.pin);
      localStorage.setItem('pizzastaff_biometric_enabled', 'true');
      localStorage.removeItem('pizzastaff_biometric_declined');
      setBiometricEnabled(true);
      setMessage({ text: "Face ID / Impronta attivata!", type: "success" });
    }
    setTimeout(() => setMessage(null), 2000);
  };

  const filteredPizzas = pizzas.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
  );

  const handleConfirmOrder = async () => {
    if (!selectedPizza || !currentDay) return;
    setSubmitting(true);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay.id,
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        note: note
      };
      await db.saveOrder(order);
      const updatedOrder = await db.getUserOrderToday(user.id);
      setMyOrder(updatedOrder);
      setSelectedPizza(null);
      setNote('');
      setIsEditing(false);
      setMessage({ text: "Ordine Confermato ed inviato", type: "success" });
      setTimeout(() => setMessage(null), 3000);
    } catch (err) {
      setMessage({ text: "Errore durante il salvataggio", type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex flex-col items-center justify-center py-20 gap-4">
          <div className="loading-spinner !w-10 !h-10" />
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Ordina Pizza" onLogout={onLogout}>
      {message && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-10 duration-500 ${
          message.type === 'success' ? 'bg-[#34C759] text-white' : 'bg-[#FF3B30] text-white'
        }`}>
          {message.type === 'success' ? <Check size={20} /> : <AlertCircle size={20} />}
          <p className="font-bold text-sm flex-1">{message.text}</p>
        </div>
      )}

      {/* Banner Stato */}
      {!canOrder && currentDay && (
        <div className="bg-[#FF3B30] text-white p-4 rounded-2xl mb-6 flex items-center gap-3">
          <Lock size={24} />
          <div>
            <p className="font-bold">Ordini chiusi 🔒</p>
            <p className="text-xs opacity-90">Oltre l'orario limite (16:30).</p>
          </div>
        </div>
      )}

      {/* Card Sicurezza Accesso */}
      <Card className="p-4 mb-6 border-l-4 border-[#5856D6]">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>
              <Fingerprint size={20} />
            </div>
            <div>
              <p className="text-xs font-bold text-[#8E8E93] uppercase">Accesso Biometrico</p>
              <p className="text-sm font-bold">{biometricEnabled ? 'Face ID / Impronta Attivo' : 'Non Attivo'}</p>
            </div>
          </div>
          <button 
            onClick={toggleBiometrics}
            className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${
              biometricEnabled ? 'bg-red-50 text-[#FF3B30] border border-red-100' : 'bg-[#007AFF] text-white'
            }`}
          >
            {biometricEnabled ? 'Disattiva' : 'Attiva ora'}
          </button>
        </div>
      </Card>

      {/* Ordine Esistente */}
      {myOrder && !selectedPizza && !isEditing && (
        <Card className={`p-4 mb-6 border-2 ${overrideActive ? 'border-[#5856D6]' : 'border-[#34C759]'}`}>
          <div className="flex justify-between items-start mb-4">
            <div>
              <p className={`text-xs font-bold ${overrideActive ? 'text-[#5856D6]' : 'text-[#34C759]'} uppercase mb-1`}>Il tuo ordine di oggi</p>
              <h2 className="text-xl font-bold">
                {pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}
              </h2>
            </div>
            <div className="bg-[#F2F2F7] px-3 py-1 rounded-full flex items-center gap-1">
              <ClockIcon size={14} />
              <span className="text-sm font-bold">{myOrder.slotTime}</span>
            </div>
          </div>
          {canOrder && (
            <Button onClick={() => {
              const p = pizzas.find(px => px.id === myOrder.pizzaId);
              if(p) { setSelectedPizza(p); setSlot(myOrder.slotTime); setNote(myOrder.note); setIsEditing(true); }
            }} variant="secondary" fullWidth>
              Modifica Ordine
            </Button>
          )}
        </Card>
      )}

      {/* Menu Pizze */}
      {(!myOrder || isEditing) && !selectedPizza && (
        <>
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
            <Input 
              placeholder="Cerca pizza..." 
              className="pl-10 bg-white"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="space-y-3">
            {filteredPizzas.map(pizza => (
              <Card 
                key={pizza.id} 
                className="p-4 cursor-pointer active:scale-95 transition-all"
                onClick={() => canOrder && setSelectedPizza(pizza)}
              >
                <div className="flex justify-between items-center mb-1">
                  <h3 className="font-bold text-lg">{pizza.name}</h3>
                  {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-bold">VEG</span>}
                </div>
                <p className="text-xs text-[#8E8E93]">{pizza.ingredients?.join(', ')}</p>
              </Card>
            ))}
          </div>
        </>
      )}

      {/* Bottom Sheet Order */}
      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => { if(!submitting) setSelectedPizza(null); }} />
          <div className="relative bg-white rounded-t-[32px] p-6 space-y-6 shadow-2xl animate-in slide-in-from-bottom">
            <h2 className="text-2xl font-bold">{selectedPizza.name}</h2>
            <div className="space-y-4">
              <SegmentedControl options={SLOT_TIMES} selected={slot} onChange={(v) => setSlot(v as SlotTime)} />
              <Input placeholder="Note particolari..." value={note} onChange={(e) => setNote(e.target.value)} />
              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting}>
                {submitting ? 'Invio...' : 'Conferma'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default WorkerDashboard;

import React, { useState, useEffect } from 'react';
import { User, Day, DayStatus, SlotTime, Role } from '../types';
import { db, GlobalSettings } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { 
  UsersIcon, 
  PizzaIcon, 
  History, 
  Unlock, 
  Lock, 
  Edit2, 
  Check, 
  AlertCircle, 
  X,
  Fingerprint
} from '../components/Icons';
import { formatDate } from '../services/utils';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  onNavigate: (view: 'pizzas' | 'users' | 'history') => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout, onNavigate }) => {
  const [currentDay, setCurrentDay] = useState<Day | null>(null);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [settings, setSettings] = useState<GlobalSettings | null>(null);
  const [isEditingCode, setIsEditingCode] = useState(false);
  const [isEditingPhone, setIsEditingPhone] = useState(false);
  const [error, setError] = useState<{message: string, code?: string} | null>(null);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');
  const [toast, setToast] = useState<string | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [day, globalSettings] = await Promise.all([
        db.getCurrentDay(),
        db.getSettings()
      ]);
      setCurrentDay(day);
      setSettings(globalSettings);

      if (day) {
        const [dayOrders, users, pizzas] = await Promise.all([
          db.getOrdersByDay(day.id),
          db.getUsers(),
          db.getPizzas()
        ]);
        const hydratedOrders = dayOrders.map(o => ({
          ...o,
          user: users.find(u => u.id === o.userId),
          pizza: pizzas.find(p => p.id === o.pizzaId)
        }));
        setOrders(hydratedOrders);
      }
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes('relation "settings" does not exist')) {
        setError({ message: "Tabella 'settings' mancante.", code: '42P01' });
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const toggleBiometrics = () => {
    if (biometricEnabled) {
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
      setToast("Biometria disattivata");
    } else {
      localStorage.setItem('pizzastaff_stored_pin', user.pin);
      localStorage.setItem('pizzastaff_biometric_enabled', 'true');
      localStorage.removeItem('pizzastaff_biometric_declined');
      setBiometricEnabled(true);
      setToast("Biometria attivata");
    }
    setTimeout(() => setToast(null), 2000);
  };

  const updateSetting = async (key: keyof GlobalSettings, value: any) => {
    if (!settings) return;
    setActionLoading(true);
    try {
      await db.updateSettings({ [key]: value });
      setSettings({ ...settings, [key]: value });
      setIsEditingCode(false);
      setIsEditingPhone(false);
    } catch (err: any) {
      setError({ message: err.message || "Errore salvataggio.", code: err.code });
    } finally {
      setActionLoading(false);
    }
  };

  const isReadOnly = user.role === Role.SUPERVISOR;

  if (loading && !error) {
    return (
      <Layout title="Admin" onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-10 !h-10" /></div>
      </Layout>
    );
  }

  return (
    <Layout title="Dashboard Admin" onLogout={onLogout}>
      {toast && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] bg-black text-white px-4 py-2 rounded-full text-xs font-bold animate-in fade-in zoom-in duration-300">
          {toast}
        </div>
      )}

      <div className="space-y-6">
        {/* Gestione Biometria */}
        <Card className="p-4 border-l-4 border-[#5856D6]">
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-full ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>
                <Fingerprint size={20} />
              </div>
              <div>
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase">Sicurezza Accesso</p>
                <p className="text-sm font-bold">{biometricEnabled ? 'Biometria Attiva' : 'PIN Standard'}</p>
              </div>
            </div>
            <button 
              onClick={toggleBiometrics}
              className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase transition-all ${
                biometricEnabled ? 'bg-red-50 text-[#FF3B30]' : 'bg-[#007AFF] text-white'
              }`}
            >
              {biometricEnabled ? 'Disattiva' : 'Attiva ora'}
            </button>
          </div>
        </Card>

        {settings && (
          <>
            <Card className="p-4">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <p className="text-xs font-bold text-[#8E8E93] uppercase">Giorno</p>
                  <h2 className="text-lg font-bold">{formatDate(new Date())}</h2>
                </div>
                <div className={`px-3 py-1 rounded-full text-xs font-bold ${
                  currentDay?.status === DayStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                }`}>
                  {currentDay?.status || 'NON APERTO'}
                </div>
              </div>
              <div className="flex gap-2">
                {!currentDay || currentDay.status === DayStatus.CLOSED ? (
                  <Button onClick={() => db.openDay().then(fetchData)} className="flex-1" disabled={isReadOnly || actionLoading}>
                    <Unlock size={18} /> Apri Ordini
                  </Button>
                ) : (
                  <Button onClick={() => db.closeDay().then(fetchData)} className="flex-1" variant="danger" disabled={isReadOnly || actionLoading}>
                    <Lock size={18} /> Chiudi Ordini
                  </Button>
                )}
              </div>
            </Card>

            <div className="grid grid-cols-2 gap-3">
              <Card className="p-4 flex flex-col justify-center items-center text-center">
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1">Totale Ordini</p>
                <p className="text-3xl font-black text-[#007AFF]">{orders.length}</p>
              </Card>
              <Card className="p-4 flex flex-col justify-center items-center text-center">
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1">Codice Locale</p>
                <p className="text-lg font-mono font-black">{settings.master_code}</p>
              </Card>
            </div>
          </>
        )}

        <div className="space-y-2">
          <Button variant="secondary" fullWidth onClick={() => onNavigate('pizzas')} className="justify-start"><PizzaIcon size={18} /> Menu Pizze</Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('users')} className="justify-start"><UsersIcon size={18} /> Dipendenti</Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('history')} className="justify-start"><History size={18} /> Storico</Button>
        </div>
      </div>
    </Layout>
  );
};

export default AdminDashboard;

/**
 * Servizio per la gestione reale della biometria tramite WebAuthn
 */

export const isBiometricAvailable = async (): Promise<boolean> => {
  return !!(
    window.PublicKeyCredential &&
    await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()
  );
};

export const registerBiometrics = async (userId: string, userName: string): Promise<boolean> => {
  try {
    const challenge = new Uint8Array(32);
    window.crypto.getRandomValues(challenge);

    const userID = new TextEncoder().encode(userId);

    const publicKey: PublicKeyCredentialCreationOptions = {
      challenge,
      rp: { name: "Pizza InTavola", id: window.location.hostname },
      user: {
        id: userID,
        name: userName,
        displayName: userName,
      },
      pubKeyCredParams: [{ alg: -7, type: "public-key" }, { alg: -257, type: "public-key" }],
      authenticatorSelection: {
        authenticatorAttachment: "platform",
        userVerification: "required",
      },
      timeout: 60000,
    };

    const credential = await navigator.credentials.create({ publicKey });
    if (credential) {
      localStorage.setItem(`biometric_id_${userId}`, (credential as any).id);
      return true;
    }
    return false;
  } catch (err) {
    console.error("Errore registrazione biometria:", err);
    return false;
  }
};

export const verifyBiometrics = async (userId: string): Promise<boolean> => {
  try {
    const challenge = new Uint8Array(32);
    window.crypto.getRandomValues(challenge);

    const publicKey: PublicKeyCredentialRequestOptions = {
      challenge,
      timeout: 60000,
      userVerification: "required",
      allowCredentials: [], // Vuoto permette l'uso di qualsiasi credenziale registrata sulla piattaforma
    };

    const assertion = await navigator.credentials.get({ publicKey });
    return !!assertion;
  } catch (err) {
    console.error("Errore verifica biometria:", err);
    return false;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { 
  PizzaIcon, 
  ClockIcon, 
  Search, 
  Check, 
  AlertCircle, 
  X, 
  Fingerprint, 
  Lock, 
  Settings, 
  UserIcon,
  ChevronRight,
  ChevronLeft
} from '../components/Icons';
import { isBeforeCutoff } from '../services/utils';
import { SLOT_TIMES } from '../constants';
import { isBiometricAvailable, registerBiometrics } from '../services/biometrics';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
}

type ViewState = 'menu' | 'settings';

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout }) => {
  const [activeTab, setActiveTab] = useState<ViewState>('menu');
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [overrideActive, setOverrideActive] = useState(false);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [note, setNote] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
    };
    checkBio();
  }, []);

  const canOrder = useMemo(() => {
    if (!currentDay || currentDay.status !== DayStatus.OPEN) return false;
    if (overrideActive) return true;
    return isBeforeCutoff();
  }, [currentDay, overrideActive]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, day, order, settings] = await Promise.all([
          db.getPizzas(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setCurrentDay(day);
        setMyOrder(order);
        setOverrideActive(settings.override_cutoff);
      } catch (err) {
        setMessage({ text: "Errore caricamento dati", type: "error" });
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleToggleBiometrics = async () => {
    if (biometricEnabled) {
      // Disattiva
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
      setMessage({ text: "Accesso biometrico disattivato", type: "success" });
    } else {
      // Attiva REALE
      setSubmitting(true);
      const success = await registerBiometrics(user.id, `${user.firstName} ${user.lastName}`);
      if (success) {
        localStorage.setItem('pizzastaff_stored_pin', user.pin);
        localStorage.setItem('pizzastaff_biometric_enabled', 'true');
        localStorage.removeItem('pizzastaff_biometric_declined');
        setBiometricEnabled(true);
        setMessage({ text: "Configurazione Face ID / Touch ID riuscita!", type: "success" });
      } else {
        setMessage({ text: "Operazione annullata o non supportata", type: "error" });
      }
      setSubmitting(false);
    }
    setTimeout(() => setMessage(null), 3000);
  };

  const handleConfirmOrder = async () => {
    if (!selectedPizza || !currentDay) return;
    setSubmitting(true);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay.id,
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        note: note
      };
      await db.saveOrder(order);
      const updatedOrder = await db.getUserOrderToday(user.id);
      setMyOrder(updatedOrder);
      setSelectedPizza(null);
      setNote('');
      setIsEditing(false);
      setMessage({ text: "Ordine inviato con successo!", type: "success" });
      setTimeout(() => setMessage(null), 3000);
    } catch (err) {
      setMessage({ text: "Errore durante il salvataggio", type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-8 !h-8" /></div>
      </Layout>
    );
  }

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    return (
      <div className="space-y-6">
        {/* Banner Stato */}
        {!canOrder && currentDay && (
          <div className="bg-[#FF3B30] text-white p-4 rounded-2xl flex items-center gap-3 shadow-lg">
            <Lock size={24} />
            <div>
              <p className="font-bold">Ordini chiusi 🔒</p>
              <p className="text-xs opacity-90">Oltre l'orario limite (16:30).</p>
            </div>
          </div>
        )}

        {/* Ordine Esistente */}
        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 ${overrideActive ? 'border-[#5856D6]' : 'border-[#34C759]'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <p className={`text-[10px] font-black ${overrideActive ? 'text-[#5856D6]' : 'text-[#34C759]'} uppercase tracking-widest mb-1`}>Prenotazione Attiva</p>
                <h2 className="text-2xl font-black">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <ClockIcon size={16} className="text-[#8E8E93]" />
                <span className="text-sm font-bold">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { setSelectedPizza(p); setSlot(myOrder.slotTime); setNote(myOrder.note); setIsEditing(true); }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] hover:!bg-[#E5E5EA]">
                Modifica Scelta
              </Button>
            )}
          </Card>
        )}

        {/* Menu Pizze */}
        {(!myOrder || isEditing) && !selectedPizza && (
          <>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
              <Input 
                placeholder="Cerca la tua pizza..." 
                className="pl-10 !rounded-2xl border-none shadow-sm"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            <div className="space-y-3">
              {filteredPizzas.map(pizza => (
                <Card 
                  key={pizza.id} 
                  className="p-4 cursor-pointer active:scale-95 transition-transform"
                  onClick={() => canOrder && setSelectedPizza(pizza)}
                >
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-black">VEG</span>}
                  </div>
                  <p className="text-xs text-[#8E8E93] leading-relaxed">{pizza.ingredients?.join(', ')}</p>
                </Card>
              ))}
            </div>
          </>
        )}
      </div>
    );
  };

  const renderSettings = () => (
    <div className="space-y-6 animate-in slide-in-from-right duration-300">
      {/* Profilo */}
      <div className="text-center py-6">
        <div className="w-20 h-20 bg-[#007AFF] rounded-full flex items-center justify-center text-white mx-auto shadow-xl mb-3">
          <UserIcon size={40} />
        </div>
        <h2 className="text-xl font-black">{user.firstName} {user.lastName}</h2>
        <p className="text-xs font-bold text-[#8E8E93] uppercase tracking-widest mt-1">Dipendente</p>
      </div>

      <div className="space-y-4">
        <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest px-4">Sicurezza e Accesso</p>
        <Card className="divide-y divide-[#F2F2F7]">
          {isBioSupported ? (
            <div className="p-4 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-xl ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-[#F2F2F7] text-[#8E8E93]'}`}>
                  <Fingerprint size={20} />
                </div>
                <div>
                  <p className="text-sm font-bold">Face ID / Touch ID</p>
                  <p className="text-[10px] text-[#8E8E93]">{biometricEnabled ? 'Attivo per questo dispositivo' : 'Accedi senza inserire il PIN'}</p>
                </div>
              </div>
              <button 
                onClick={handleToggleBiometrics}
                disabled={submitting}
                className={`w-12 h-6 rounded-full p-1 transition-colors duration-200 ${biometricEnabled ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full shadow-sm transform transition-transform duration-200 ${biometricEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
              </button>
            </div>
          ) : (
            <div className="p-4 flex items-center gap-3 opacity-50">
              <Fingerprint size={20} className="text-[#8E8E93]" />
              <p className="text-sm font-medium text-[#8E8E93]">Biometria non supportata</p>
            </div>
          )}

          <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-[#F2F2F7] text-[#8E8E93]">
                <Lock size={20} />
              </div>
              <div>
                <p className="text-sm font-bold">PIN Personale</p>
                <p className="text-[10px] text-[#8E8E93]">Il tuo codice: ****</p>
              </div>
            </div>
            <span className="text-xs text-[#8E8E93] font-bold">PRIVATO</span>
          </div>
        </Card>

        <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest px-4 pt-4">Account</p>
        <Card>
          <button 
            onClick={onLogout}
            className="w-full p-4 flex justify-between items-center active:bg-[#F2F2F7] transition-colors"
          >
            <div className="flex items-center gap-3 text-[#FF3B30]">
              <div className="p-2 rounded-xl bg-red-50">
                <LogOut size={20} />
              </div>
              <span className="text-sm font-bold">Esci dall'applicazione</span>
            </div>
            <ChevronRight size={18} className="text-[#C6C6C8]" />
          </button>
        </Card>

        <p className="text-center text-[10px] text-[#8E8E93] font-medium pt-8">
          Pizza InTavola Staff v2.1.0<br/>
          Sviluppato per InTavola SRL
        </p>
      </div>
    </div>
  );

  return (
    <Layout 
      title={activeTab === 'menu' ? 'Menu Pizze' : 'Impostazioni'}
      onBack={activeTab === 'settings' ? () => setActiveTab('menu') : undefined}
    >
      {message && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-10 duration-500 ${
          message.type === 'success' ? 'bg-[#34C759] text-white' : 'bg-[#FF3B30] text-white'
        }`}>
          {message.type === 'success' ? <Check size={20} /> : <AlertCircle size={20} />}
          <p className="font-bold text-sm flex-1">{message.text}</p>
        </div>
      )}

      {activeTab === 'menu' ? renderMenu() : renderSettings()}

      {/* Tab Bar iOS Style */}
      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-lg ios-blur border-t border-[#C6C6C8] px-8 py-3 pb-8 flex justify-between items-center z-40">
        <button 
          onClick={() => setActiveTab('menu')}
          className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'menu' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}
        >
          <PizzaIcon size={24} />
          <span className="text-[10px] font-bold">Ordina</span>
        </button>
        <button 
          onClick={() => setActiveTab('settings')}
          className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'settings' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}
        >
          <Settings size={24} />
          <span className="text-[10px] font-bold">Impostazioni</span>
        </button>
      </nav>

      {/* Bottom Sheet Order */}
      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { if(!submitting) setSelectedPizza(null); }} />
          <div className="relative bg-white rounded-t-[32px] p-6 pb-12 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-[#E5E5EA] rounded-full mx-auto" />
            <h2 className="text-2xl font-black">{selectedPizza.name}</h2>
            <div className="space-y-6">
              <div className="space-y-2">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Orario di ritiro</p>
                <SegmentedControl options={SLOT_TIMES} selected={slot} onChange={(v) => setSlot(v as SlotTime)} />
              </div>
              <div className="space-y-2">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Note o varianti</p>
                <Input placeholder="Es: Senza mozzarella, ben cotta..." value={note} onChange={(e) => setNote(e.target.value)} />
              </div>
              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting}>
                {submitting ? <div className="loading-spinner border-white border-t-transparent" /> : 'Invia Ordine'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default WorkerDashboard;

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { User } from '../types';
import { Fingerprint } from '../components/Icons';
import { isBiometricAvailable, verifyBiometrics } from '../services/biometrics';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isBioSupported, setIsBioSupported] = useState(false);
  const [hasStoredPin, setHasStoredPin] = useState(false);

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);

      const enabled = localStorage.getItem('pizzastaff_biometric_enabled') === 'true';
      const stored = localStorage.getItem('pizzastaff_stored_pin');
      setHasStoredPin(enabled && !!stored);

      // Prova il login automatico se configurato
      if (enabled && stored) {
        handleBiometricLogin(stored);
      }
    };
    checkBio();
  }, []);

  const handleBiometricLogin = async (storedPin?: string) => {
    const pinToUse = storedPin || localStorage.getItem('pizzastaff_stored_pin');
    if (!pinToUse) return;

    try {
      const verified = await verifyBiometrics("current_user"); // WebAuthn trigger reale
      if (verified) {
        setLoading(true);
        const user = await db.getUserByPin(pinToUse);
        if (user) {
          onLogin(user);
        } else {
          localStorage.removeItem('pizzastaff_stored_pin');
          setHasStoredPin(false);
        }
      }
    } catch (err) {
      console.error("Biometric error", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async () => {
    if (pin.length < 4) return;
    setLoading(true);
    setError('');
    try {
      const user = await db.getUserByPin(pin);
      if (user) {
        onLogin(user);
      } else {
        setError('PIN non valido');
        setPin('');
      }
    } catch (err) {
      setError('Errore di connessione');
    } finally {
      setLoading(false);
    }
  };

  const addDigit = (d: string) => {
    if (pin.length < 6) {
      const newPin = pin + d;
      setPin(newPin);
      setError('');
      if (newPin.length >= 4) {
        // Opzionale: invio automatico al raggiungimento di 4 cifre
      }
    }
  };

  const renderNumpad = () => (
    <div className="w-full max-w-[280px]">
      <div className="flex justify-center gap-4 mb-10">
        {[...Array(4)].map((_, i) => (
          <div 
            key={i} 
            className={`w-3 h-3 rounded-full border-2 transition-all duration-200 ${
              pin.length > i ? 'bg-[#007AFF] border-[#007AFF] scale-125' : 'bg-transparent border-[#C6C6C8]'
            }`} 
          />
        ))}
      </div>
      <div className="grid grid-cols-3 gap-y-4 gap-x-6">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d => (
          <button 
            key={d} 
            onClick={() => addDigit(d)} 
            className="w-16 h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA] transition-colors flex items-center justify-center mx-auto"
          >
            {d}
          </button>
        ))}

        <button 
          onClick={() => handleBiometricLogin()}
          className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto transition-all ${
            hasStoredPin ? 'text-[#007AFF] bg-white ios-shadow active:bg-[#E5E5EA]' : 'text-[#8E8E93] opacity-20'
          }`}
          disabled={!hasStoredPin}
        >
          <Fingerprint size={32} />
        </button>

        <button 
          onClick={() => addDigit('0')} 
          className="w-16 h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA] flex items-center justify-center mx-auto"
        >
          0
        </button>

        <button 
          onClick={handleLogin} 
          disabled={pin.length < 4 || loading} 
          className="w-16 h-16 rounded-full bg-[#007AFF] text-white text-sm font-black shadow-lg flex items-center justify-center mx-auto active:scale-95 disabled:opacity-50 transition-all"
        >
          {loading ? <div className="loading-spinner border-white border-t-transparent" /> : 'ENTRA'}
        </button>
      </div>
      <button 
        onClick={() => setPin('')} 
        className="w-full mt-8 text-[10px] font-black text-[#8E8E93] uppercase tracking-[0.2em]"
      >
        Cancella
      </button>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#F2F2F7]">
      <div className="w-full max-w-xs flex flex-col items-center gap-10">
        <div className="flex flex-col items-center gap-4">
          <div className="w-24 h-24 bg-white rounded-[28px] flex items-center justify-center shadow-2xl p-4">
             <img 
               src="https://raw.githubusercontent.com/google/material-design-icons/master/png/maps/local_pizza/black/48dp/2x/local_pizza_black_48dp.png" 
               alt="Logo" 
               className="w-full h-full object-contain opacity-80" 
             />
          </div>
          <div className="text-center">
            <h1 className="text-2xl font-black tracking-tight">Staff InTavola</h1>
            <p className="text-[#8E8E93] text-xs font-bold uppercase tracking-widest mt-1">Area Dipendenti</p>
          </div>
        </div>

        <div className="w-full flex flex-col items-center">
          {error && <p className="text-center text-sm font-bold mb-6 text-[#FF3B30] animate-bounce">{error}</p>}
          {renderNumpad()}
          <p className="text-center mt-12 text-[9px] font-bold text-[#C6C6C8] uppercase tracking-[0.1em] max-w-[200px] leading-relaxed">
            In caso di smarrimento del PIN rivolgersi al responsabile.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { 
  PizzaIcon, 
  ClockIcon, 
  Search, 
  Check, 
  AlertCircle, 
  X, 
  Fingerprint, 
  Lock, 
  Settings, 
  UserIcon,
  ChevronRight,
  ChevronLeft,
  LogOut
} from '../components/Icons';
import { isBeforeCutoff } from '../services/utils';
import { SLOT_TIMES } from '../constants';
import { isBiometricAvailable, registerBiometrics } from '../services/biometrics';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
}

type ViewState = 'menu' | 'settings';

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout }) => {
  const [activeTab, setActiveTab] = useState<ViewState>('menu');
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [overrideActive, setOverrideActive] = useState(false);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [note, setNote] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
    };
    checkBio();
  }, []);

  const canOrder = useMemo(() => {
    if (!currentDay || currentDay.status !== DayStatus.OPEN) return false;
    if (overrideActive) return true;
    return isBeforeCutoff();
  }, [currentDay, overrideActive]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, day, order, settings] = await Promise.all([
          db.getPizzas(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setCurrentDay(day);
        setMyOrder(order);
        setOverrideActive(settings.override_cutoff);
      } catch (err) {
        setMessage({ text: "Errore caricamento dati", type: "error" });
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleToggleBiometrics = async () => {
    if (biometricEnabled) {
      // Disattiva
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
      setMessage({ text: "Accesso biometrico disattivato", type: "success" });
    } else {
      // Attiva REALE
      setSubmitting(true);
      const success = await registerBiometrics(user.id, `${user.firstName} ${user.lastName}`);
      if (success) {
        localStorage.setItem('pizzastaff_stored_pin', user.pin);
        localStorage.setItem('pizzastaff_biometric_enabled', 'true');
        localStorage.removeItem('pizzastaff_biometric_declined');
        setBiometricEnabled(true);
        setMessage({ text: "Configurazione Face ID / Touch ID riuscita!", type: "success" });
      } else {
        setMessage({ text: "Operazione annullata o non supportata", type: "error" });
      }
      setSubmitting(false);
    }
    setTimeout(() => setMessage(null), 3000);
  };

  const handleConfirmOrder = async () => {
    if (!selectedPizza || !currentDay) return;
    setSubmitting(true);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay.id,
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        note: note
      };
      await db.saveOrder(order);
      const updatedOrder = await db.getUserOrderToday(user.id);
      setMyOrder(updatedOrder);
      setSelectedPizza(null);
      setNote('');
      setIsEditing(false);
      setMessage({ text: "Ordine inviato con successo!", type: "success" });
      setTimeout(() => setMessage(null), 3000);
    } catch (err) {
      setMessage({ text: "Errore durante il salvataggio", type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-8 !h-8" /></div>
      </Layout>
    );
  }

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    return (
      <div className="space-y-6">
        {/* Banner Stato */}
        {!canOrder && currentDay && (
          <div className="bg-[#FF3B30] text-white p-4 rounded-2xl flex items-center gap-3 shadow-lg">
            <Lock size={24} />
            <div>
              <p className="font-bold">Ordini chiusi 🔒</p>
              <p className="text-xs opacity-90">Oltre l'orario limite (16:30).</p>
            </div>
          </div>
        )}

        {/* Ordine Esistente */}
        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 ${overrideActive ? 'border-[#5856D6]' : 'border-[#34C759]'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <p className={`text-[10px] font-black ${overrideActive ? 'text-[#5856D6]' : 'text-[#34C759]'} uppercase tracking-widest mb-1`}>Prenotazione Attiva</p>
                <h2 className="text-2xl font-black">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <ClockIcon size={16} className="text-[#8E8E93]" />
                <span className="text-sm font-bold">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { setSelectedPizza(p); setSlot(myOrder.slotTime); setNote(myOrder.note); setIsEditing(true); }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] hover:!bg-[#E5E5EA]">
                Modifica Scelta
              </Button>
            )}
          </Card>
        )}

        {/* Menu Pizze */}
        {(!myOrder || isEditing) && !selectedPizza && (
          <>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
              <Input 
                placeholder="Cerca la tua pizza..." 
                className="pl-10 !rounded-2xl border-none shadow-sm"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            <div className="space-y-3">
              {filteredPizzas.map(pizza => (
                <Card 
                  key={pizza.id} 
                  className="p-4 cursor-pointer active:scale-95 transition-transform"
                  onClick={() => canOrder && setSelectedPizza(pizza)}
                >
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-black">VEG</span>}
                  </div>
                  <p className="text-xs text-[#8E8E93] leading-relaxed">{pizza.ingredients?.join(', ')}</p>
                </Card>
              ))}
            </div>
          </>
        )}
      </div>
    );
  };

  const renderSettings = () => (
    <div className="space-y-6 animate-in slide-in-from-right duration-300">
      {/* Profilo */}
      <div className="text-center py-6">
        <div className="w-20 h-20 bg-[#007AFF] rounded-full flex items-center justify-center text-white mx-auto shadow-xl mb-3">
          <UserIcon size={40} />
        </div>
        <h2 className="text-xl font-black">{user.firstName} {user.lastName}</h2>
        <p className="text-xs font-bold text-[#8E8E93] uppercase tracking-widest mt-1">Dipendente</p>
      </div>

      <div className="space-y-4">
        <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest px-4">Sicurezza e Accesso</p>
        <Card className="divide-y divide-[#F2F2F7]">
          {isBioSupported ? (
            <div className="p-4 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-xl ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-[#F2F2F7] text-[#8E8E93]'}`}>
                  <Fingerprint size={20} />
                </div>
                <div>
                  <p className="text-sm font-bold">Face ID / Touch ID</p>
                  <p className="text-[10px] text-[#8E8E93]">{biometricEnabled ? 'Attivo per questo dispositivo' : 'Accedi senza inserire il PIN'}</p>
                </div>
              </div>
              <button 
                onClick={handleToggleBiometrics}
                disabled={submitting}
                className={`w-12 h-6 rounded-full p-1 transition-colors duration-200 ${biometricEnabled ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full shadow-sm transform transition-transform duration-200 ${biometricEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
              </button>
            </div>
          ) : (
            <div className="p-4 flex items-center gap-3 opacity-50">
              <Fingerprint size={20} className="text-[#8E8E93]" />
              <p className="text-sm font-medium text-[#8E8E93]">Biometria non supportata</p>
            </div>
          )}

          <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-[#F2F2F7] text-[#8E8E93]">
                <Lock size={20} />
              </div>
              <div>
                <p className="text-sm font-bold">PIN Personale</p>
                <p className="text-[10px] text-[#8E8E93]">Il tuo codice: ****</p>
              </div>
            </div>
            <span className="text-xs text-[#8E8E93] font-bold">PRIVATO</span>
          </div>
        </Card>

        <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest px-4 pt-4">Account</p>
        <Card>
          <button 
            onClick={onLogout}
            className="w-full p-4 flex justify-between items-center active:bg-[#F2F2F7] transition-colors"
          >
            <div className="flex items-center gap-3 text-[#FF3B30]">
              <div className="p-2 rounded-xl bg-red-50">
                <LogOut size={20} />
              </div>
              <span className="text-sm font-bold">Esci dall'applicazione</span>
            </div>
            <ChevronRight size={18} className="text-[#C6C6C8]" />
          </button>
        </Card>

        <p className="text-center text-[10px] text-[#8E8E93] font-medium pt-8">
          Pizza InTavola Staff v2.1.0<br/>
          Sviluppato per InTavola SRL
        </p>
      </div>
    </div>
  );

  return (
    <Layout 
      title={activeTab === 'menu' ? 'Menu Pizze' : 'Impostazioni'}
      onBack={activeTab === 'settings' ? () => setActiveTab('menu') : undefined}
    >
      {message && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-10 duration-500 ${
          message.type === 'success' ? 'bg-[#34C759] text-white' : 'bg-[#FF3B30] text-white'
        }`}>
          {message.type === 'success' ? <Check size={20} /> : <AlertCircle size={20} />}
          <p className="font-bold text-sm flex-1">{message.text}</p>
        </div>
      )}

      {activeTab === 'menu' ? renderMenu() : renderSettings()}

      {/* Tab Bar iOS Style */}
      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-lg ios-blur border-t border-[#C6C6C8] px-8 py-3 pb-8 flex justify-between items-center z-40">
        <button 
          onClick={() => setActiveTab('menu')}
          className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'menu' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}
        >
          <PizzaIcon size={24} />
          <span className="text-[10px] font-bold">Ordina</span>
        </button>
        <button 
          onClick={() => setActiveTab('settings')}
          className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'settings' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}
        >
          <Settings size={24} />
          <span className="text-[10px] font-bold">Impostazioni</span>
        </button>
      </nav>

      {/* Bottom Sheet Order */}
      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { if(!submitting) setSelectedPizza(null); }} />
          <div className="relative bg-white rounded-t-[32px] p-6 pb-12 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-[#E5E5EA] rounded-full mx-auto" />
            <h2 className="text-2xl font-black">{selectedPizza.name}</h2>
            <div className="space-y-6">
              <div className="space-y-2">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Orario di ritiro</p>
                <SegmentedControl options={SLOT_TIMES} selected={slot} onChange={(v) => setSlot(v as SlotTime)} />
              </div>
              <div className="space-y-2">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Note o varianti</p>
                <Input placeholder="Es: Senza mozzarella, ben cotta..." value={note} onChange={(e) => setNote(e.target.value)} />
              </div>
              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting}>
                {submitting ? <div className="loading-spinner border-white border-t-transparent" /> : 'Invia Ordine'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

