interface AdminHistoryProps {
  onBack: () => void;
}

const AdminHistory: React.FC<AdminHistoryProps> = ({ onBack }) => {
  const [days, setDays] = useState<Day[]>([]);
  const [selectedDay, setSelectedDay] = useState<Day | null>(null);
  const [orders, setOrders] = useState<any[]>([]);
  const [modifications, setModifications] = useState<Modification[]>([]);
  const [loading, setLoading] = useState(true);
  const [ordersLoading, setOrdersLoading] = useState(false);

  useEffect(() => {
    const fetchDays = async () => {
      setLoading(true);
      try {
        const [dayList, modList] = await Promise.all([
          db.getDays(),
          db.getModifications()
        ]);
        setDays(dayList);
        setModifications(modList);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchDays();
  }, []);

  const handleSelectDay = async (day: Day) => {
    setSelectedDay(day);
    setOrdersLoading(true);
    try {
      const dayOrders = await db.getOrdersByDay(day.id);
      const [users, pizzas] = await Promise.all([
        db.getUsers(),
        db.getPizzas()
      ]);

      setOrders(dayOrders.map(o => ({
        ...o,
        user: users.find(u => u.id === o.userId),
        pizza: pizzas.find(p => p.id === o.pizzaId),
        addMod: modifications.find(m => m.id === o.addModificationId),
        removeMod: modifications.find(m => m.id === o.removeModificationId)
      })));
    } catch (err) {
      console.error(err);
    } finally {
      setOrdersLoading(false);
    }
