      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const toggleBiometrics = () => {
    if (biometricEnabled) {
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
      setToast("Biometria disattivata");
    } else {
      localStorage.setItem('pizzastaff_stored_pin', user.pin);
      localStorage.setItem('pizzastaff_biometric_enabled', 'true');
      localStorage.removeItem('pizzastaff_biometric_declined');
      setBiometricEnabled(true);
      setToast("Biometria attivata");
    }
    setTimeout(() => setToast(null), 2000);
  };

  const isReadOnly = user.role === Role.SUPERVISOR;

  if (loading && !error) {
    return (
      <Layout title="Admin" onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-10 !h-10" /></div>
      </Layout>
    );
  }

  return (
    <Layout title="Dashboard Admin" onLogout={onLogout}>
      {toast && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] bg-black text-white px-4 py-2 rounded-full text-xs font-bold animate-in fade-in zoom-in duration-300">
          {toast}
        </div>
      )}

      <div className="space-y-6">
        {schemaError && (
          <Card className="p-4 bg-red-50 border-2 border-red-200 animate-pulse">
            <div className="flex items-start gap-3 text-red-700">
              <AlertCircle className="shrink-0 mt-1" size={20} />
              <div className="space-y-2">
                <p className="text-xs font-black uppercase">Errore Critico Database</p>
                <p className="text-sm font-bold leading-tight">{schemaError}</p>
                <Button onClick={fetchData} variant="secondary" className="!py-1.5 !text-[10px] !bg-white">
                  <RefreshCw size={12} /> Riprova
                </Button>
              </div>
            </div>
          </Card>
        )}

        {/* Pulsante Ordina per Admin/Supervisor */}
        <Card className="p-4 border-l-4 border-[#FF9500] bg-orange-50/30">
           <div className="flex justify-between items-center">
             <div className="flex items-center gap-3">
               <div className="p-2 bg-orange-100 text-orange-600 rounded-full">
                 <PizzaIcon size={24} />
               </div>
               <div>
                 <p className="text-[10px] font-bold text-[#8E8E93] uppercase">Sezione Personale</p>
                 <p className="text-sm font-bold">Prenota la tua pizza oggi</p>
               </div>
             </div>
             <Button onClick={onGoToOrder} size="sm" className="!py-2">
               Vai al Menu
             </Button>
           </div>
        </Card>

        <Card className="p-4 border-l-4 border-[#5856D6]">
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-full ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>
                <Fingerprint size={20} />
              </div>
              <div>
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase">Sicurezza Accesso</p>
                <p className="text-sm font-bold">{biometricEnabled ? 'Biometria Attiva' : 'PIN Standard'}</p>
              </div>
            </div>
            <button 
              onClick={toggleBiometrics}
              className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase transition-all ${
                biometricEnabled ? 'bg-red-50 text-[#FF3B30]' : 'bg-[#007AFF] text-white'
              }`}
            >
              {biometricEnabled ? 'Disattiva' : 'Attiva ora'}
            </button>
          </div>
        </Card>

        {settings && (
          <>
            <Card className="p-4">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <p className="text-xs font-bold text-[#8E8E93] uppercase">Giorno</p>
                  <h2 className="text-lg font-bold">{formatDate(new Date())}</h2>
                </div>
                <div className={`px-3 py-1 rounded-full text-xs font-bold ${
                  currentDay?.status === DayStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                }`}>
                  {currentDay?.status || 'NON APERTO'}
                </div>
              </div>
              <div className="flex gap-2">
                {!currentDay || currentDay.status === DayStatus.CLOSED ? (
                  <Button onClick={() => db.openDay().then(fetchData)} className="flex-1" disabled={isReadOnly || actionLoading}>
                    <Unlock size={18} /> Apri Ordini
                  </Button>
                ) : (
                  <Button onClick={() => db.closeDay().then(fetchData)} className="flex-1" variant="danger" disabled={isReadOnly || actionLoading}>
                    <Lock size={18} /> Chiudi Ordini
                  </Button>
                )}
              </div>
            </Card>

            <div className="grid grid-cols-2 gap-3">
              <Card className="p-4 flex flex-col justify-center items-center text-center">
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1">Totale Ordini</p>
                <p className="text-3xl font-black text-[#007AFF]">{orders.length}</p>
              </Card>
              <Card className="p-4 flex flex-col justify-center items-center text-center">
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1">Codice Locale</p>
                <p className="text-lg font-mono font-black">{settings.master_code}</p>
              </Card>
            </div>
          </>
        )}

        <div className="space-y-2">
          <Button variant="secondary" fullWidth onClick={() => onNavigate('pizzas')} className="justify-start"><PizzaIcon size={18} /> Menu Pizze</Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('modifications')} className="justify-start"><Sliders size={18} /> Variazioni</Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('users')} className="justify-start"><UsersIcon size={18} /> Dipendenti</Button>
          <Button variant="secondary" fullWidth onClick={() => onNavigate('history')} className="justify-start"><History size={18} /> Storico</Button>
        </div>
      </div>
    </Layout>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus, Modification, Role } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { 
  PizzaIcon, 
  ClockIcon, 
  Search, 
  Check, 
  AlertCircle, 
  X, 
  Fingerprint, 
  Lock, 
  Settings, 
  UserIcon,
  ChevronRight,
  ChevronLeft,
  LogOut,
  Plus,
  Trash2,
  Sliders
} from '../components/Icons';
import { isBeforeCutoff } from '../services/utils';
import { SLOT_TIMES } from '../constants';
import { isBiometricAvailable, registerBiometrics } from '../services/biometrics';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
  onBackToAdmin?: () => void;
}

type ViewState = 'menu' | 'settings';

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout, onBackToAdmin }) => {
  const [activeTab, setActiveTab] = useState<ViewState>('menu');
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [modifications, setModifications] = useState<Modification[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [overrideActive, setOverrideActive] = useState(false);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [selectedAddIds, setSelectedAddIds] = useState<string[]>([]);
  const [selectedRemoveIds, setSelectedRemoveIds] = useState<string[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  const addOptions = modifications.filter(m => m.type === 'ADD' && m.active);
  const removeOptions = modifications.filter(m => m.type === 'REMOVE' && m.active);

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
    };
    checkBio();
  }, []);

  const canOrder = useMemo(() => {
    if (!currentDay || currentDay.status !== DayStatus.OPEN) return false;
    if (overrideActive) return true;
    return isBeforeCutoff();
  }, [currentDay, overrideActive]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, modList, day, order, settings] = await Promise.all([
          db.getPizzas(),
          db.getModifications(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setModifications(modList || []);
        setCurrentDay(day);
        setMyOrder(order);
        setOverrideActive(settings.override_cutoff);
      } catch (err: any) {
        setMessage({ text: err.message || "Errore nel caricamento dei dati", type: "error" });
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleToggleAdd = (id: string) => {
    setSelectedAddIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleToggleRemove = (id: string) => {
    setSelectedRemoveIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleConfirmOrder = async () => {
    if (!selectedPizza || !currentDay) return;
    setSubmitting(true);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay.id,
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        addModificationIds: selectedAddIds,
        removeModificationIds: selectedRemoveIds,
        note: ''
      };
      await db.saveOrder(order);
      const updatedOrder = await db.getUserOrderToday(user.id);
      setMyOrder(updatedOrder);
      setSelectedPizza(null);
      setSelectedAddIds([]);
      setSelectedRemoveIds([]);
      setIsEditing(false);
      setMessage({ text: "Ordine inviato con successo!", type: "success" });
      setTimeout(() => setMessage(null), 3000);
    } catch (err: any) {
      setMessage({ text: err.message || "Errore durante il salvataggio", type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-8 !h-8" /></div>
      </Layout>
    );
  }

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    return (
      <div className="space-y-6">
        {!canOrder && currentDay && (
          <div className="bg-[#FF3B30] text-white p-4 rounded-2xl flex items-center gap-3 shadow-lg">
            <Lock size={24} />
            <div>
              <p className="font-bold">Ordini chiusi 🔒</p>
              <p className="text-xs opacity-90">Oltre l'orario limite (16:30).</p>
            </div>
          </div>
        )}

        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 ${overrideActive ? 'border-[#5856D6]' : 'border-[#34C759]'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <p className={`text-[10px] font-black ${overrideActive ? 'text-[#5856D6]' : 'text-[#34C759]'} uppercase tracking-widest mb-1`}>Prenotazione Attiva</p>
                <h2 className="text-2xl font-black">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
                <div className="mt-2 flex flex-wrap gap-1">
                  {myOrder.addModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-green-100 text-green-700">+{mod.name}</span> : null;
                  })}
                  {myOrder.removeModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-red-100 text-red-700">-{mod.name}</span> : null;
                  })}
                </div>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <ClockIcon size={16} className="text-[#8E8E93]" />
                <span className="text-sm font-bold">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { 
                  setSelectedPizza(p); 
                  setSlot(myOrder.slotTime); 
                  setSelectedAddIds(myOrder.addModificationIds || []); 
                  setSelectedRemoveIds(myOrder.removeModificationIds || []);
                  setIsEditing(true); 
                }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] hover:!bg-[#E5E5EA]">
                Modifica Scelta
              </Button>
            )}
          </Card>
        )}

        {(!myOrder || isEditing) && !selectedPizza && (
          <>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
              <Input 
                placeholder="Cerca la tua pizza..." 
                className="pl-10 !rounded-2xl border-none shadow-sm"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            <div className="space-y-3">
              {filteredPizzas.map(pizza => (
                <Card 
                  key={pizza.id} 
                  className="p-4 cursor-pointer active:scale-95 transition-transform"
                  onClick={() => canOrder && setSelectedPizza(pizza)}
                >
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-black">VEG</span>}
                  </div>
                  <p className="text-xs text-[#8E8E93] leading-relaxed">{pizza.ingredients?.join(', ')}</p>
                </Card>
              ))}
            </div>
          </>
        )}
      </div>
    );
  };

  const isManagement = user.role === Role.ADMIN || user.role === Role.SUPERVISOR;

  return (
    <Layout 
      title={activeTab === 'menu' ? 'Menu Pizze' : 'Impostazioni'}
      onBack={activeTab === 'settings' ? () => setActiveTab('menu') : undefined}
    >
      {message && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-10 duration-500 ${
          message.type === 'success' ? 'bg-[#34C759] text-white' : 'bg-[#FF3B30] text-white'
        }`}>
          {message.type === 'success' ? <Check size={20} /> : <AlertCircle size={20} />}
          <p className="font-bold text-sm flex-1">{message.text}</p>
        </div>
      )}

      {activeTab === 'menu' ? renderMenu() : (
        <div className="space-y-6 animate-in slide-in-from-right duration-300">
           <div className="text-center py-6">
            <div className="w-20 h-20 bg-[#007AFF] rounded-full flex items-center justify-center text-white mx-auto shadow-xl mb-3">
              <UserIcon size={40} />
            </div>
            <h2 className="text-xl font-black">{user.firstName} {user.lastName}</h2>
            <p className="text-xs font-bold text-[#8E8E93] uppercase tracking-widest mt-1">{user.role}</p>
          </div>
          <Card>
            <button onClick={onLogout} className="w-full p-4 flex justify-between items-center text-[#FF3B30] font-bold">
              <span>Esci</span>
              <LogOut size={20} />
            </button>
          </Card>

          {isManagement && onBackToAdmin && (
            <Card className="border-2 border-[#5856D6]">
              <button onClick={onBackToAdmin} className="w-full p-4 flex justify-between items-center text-[#5856D6] font-bold">
                <span>Pannello Admin</span>
                <Sliders size={20} />
              </button>
            </Card>
          )}
        </div>
      )}

      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-lg ios-blur border-t border-[#C6C6C8] px-8 py-3 pb-8 flex justify-between items-center z-40">
        <button onClick={() => setActiveTab('menu')} className={`flex flex-col items-center gap-1 ${activeTab === 'menu' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}>
          <PizzaIcon size={24} />
          <span className="text-[10px] font-bold">Ordina</span>
        </button>

        {isManagement && onBackToAdmin && (
           <button onClick={onBackToAdmin} className="flex flex-col items-center gap-1 text-[#5856D6]">
             <Sliders size={24} />
             <span className="text-[10px] font-bold">Admin</span>
           </button>
        )}

        <button onClick={() => setActiveTab('settings')} className={`flex flex-col items-center gap-1 ${activeTab === 'settings' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}>
          <Settings size={24} />
          <span className="text-[10px] font-bold">Impostazioni</span>
        </button>
      </nav>

      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => !submitting && setSelectedPizza(null)} />
          <div className="relative bg-[#F2F2F7] rounded-t-[32px] p-6 pb-12 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300 overflow-y-auto max-h-[90vh]">
            <div className="w-12 h-1.5 bg-[#C6C6C8] rounded-full mx-auto" />
            <h2 className="text-2xl font-black text-center">{selectedPizza.name}</h2>

            <div className="space-y-6">
              <section className="space-y-3">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Orario di ritiro</p>
                <SegmentedControl options={SLOT_TIMES} selected={slot} onChange={(v) => setSlot(v as SlotTime)} />
              </section>

              <section className="space-y-3">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Aggiunte (+)</p>
                <div className="bg-white rounded-2xl overflow-hidden divide-y divide-[#F2F2F7]">
                  {addOptions.map(opt => (
                    <button 
                      key={opt.id} 
                      onClick={() => handleToggleAdd(opt.id)}
                      className="w-full flex items-center justify-between p-4 active:bg-[#F2F2F7] transition-colors"
                    >
                      <span className="text-sm font-medium">{opt.name}</span>
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        selectedAddIds.includes(opt.id) ? 'bg-[#007AFF] border-[#007AFF]' : 'border-[#C6C6C8]'
                      }`}>
                        {selectedAddIds.includes(opt.id) && <Check size={14} className="text-white" />}
                      </div>
                    </button>
                  ))}
                  {addOptions.length === 0 && <p className="p-4 text-xs text-[#8E8E93] text-center">Nessuna opzione disponibile</p>}
                </div>
              </section>

              <section className="space-y-3">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Rimossoni (-)</p>
                <div className="bg-white rounded-2xl overflow-hidden divide-y divide-[#F2F2F7]">
                  {removeOptions.map(opt => (
                    <button 
                      key={opt.id} 
                      onClick={() => handleToggleRemove(opt.id)}
                      className="w-full flex items-center justify-between p-4 active:bg-[#F2F2F7] transition-colors"
                    >
                      <span className="text-sm font-medium">{opt.name}</span>
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        selectedRemoveIds.includes(opt.id) ? 'bg-[#FF3B30] border-[#FF3B30]' : 'border-[#C6C6C8]'
                      }`}>
                        {selectedRemoveIds.includes(opt.id) && <Check size={14} className="text-white" />}
                      </div>
                    </button>
                  ))}
                   {removeOptions.length === 0 && <p className="p-4 text-xs text-[#8E8E93] text-center">Nessuna opzione disponibile</p>}
                </div>
              </section>

              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting}>
                {submitting ? <div className="loading-spinner border-white border-t-transparent" /> : 'Invia Ordine'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default WorkerDashboard;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md',
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "rounded-xl font-semibold text-sm transition-all active:scale-[0.98] disabled:opacity-50 disabled:active:scale-100 flex items-center justify-center gap-2";

  const sizeStyles = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-4 py-3 text-sm",
    lg: "px-6 py-4 text-base"
  };

  const variants = {
    primary: "bg-[#007AFF] text-white shadow-sm",
    secondary: "bg-[#E5E5EA] text-[#000000] hover:bg-[#D1D1D6]",
    danger: "bg-[#FF3B30] text-white shadow-sm",
    ghost: "bg-transparent text-[#007AFF] hover:bg-[#F2F2F7]"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizeStyles[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export const Input: React.FC<React.InputHTMLAttributes<HTMLInputElement>> = ({ className = '', ...props }) => {
  return (
    <input 
      className={`w-full px-4 py-3 rounded-xl bg-white border border-[#C6C6C8] focus:border-[#007AFF] focus:ring-1 focus:ring-[#007AFF] outline-none transition-all ${className}`}
      {...props}
    />
  );
};

interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
}

export const Card: React.FC<CardProps> = ({ children, className = '', ...props }) => {
  return (
    <div 
      className={`bg-white rounded-2xl ios-shadow overflow-hidden ${className}`}
      {...props}
    >
      {children}
    </div>
  );
};

export const SegmentedControl: React.FC<{
  options: string[];
  selected: string;
  onChange: (value: string) => void;
}> = ({ options, selected, onChange }) => {
  return (
    <div className="flex p-1 bg-[#E5E5EA] rounded-xl w-full">
      {options.map((option) => (
        <button
          key={option}
          type="button"
          onClick={() => onChange(option)}
          className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${
            selected === option 
              ? "bg-white text-black shadow-sm" 
              : "text-[#8E8E93] hover:text-[#000000]"
          }`}
        >
          {option}
        </button>
      ))}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role } from '../types';
import { db } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { Plus, Edit2, Trash2, X, AlertCircle, Check, Copy, MessageCircle, RefreshCw } from '../components/Icons';

interface AdminUsersProps {
  onBack: () => void;
}

const AdminUsers: React.FC<AdminUsersProps> = ({ onBack }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [editing, setEditing] = useState<Partial<User> | null>(null);
  const [successUser, setSuccessUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [toast, setToast] = useState<string | null>(null);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const data = await db.getUsers();
      setUsers(data);
    } catch (err) {
      console.error("Errore fetch users:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const showToast = (msg: string) => {
    setToast(msg);
    setTimeout(() => setToast(null), 2000);
  };

  const getPINMessage = (user: User) => {
    return `Ciao ${user.firstName}! Sono lo staff di InTavola. Questo è il tuo codice personale per ordinare la pizza: ${user.pin}. Accedi qui: ${window.location.origin}`;
  };

  const copyToClipboard = async (user: User) => {
    const msg = getPINMessage(user);
    try {
      await navigator.clipboard.writeText(msg);
      showToast("Copiato ✅");
    } catch (err) {
      alert("Errore nella copia");
    }
  };

  const sendWhatsApp = (user: User) => {
    const phone = user.phone_e164 || '';
    if (!phone) {
      alert("Numero di telefono mancante!");
      return;
    }

    // Pulizia aggressiva del numero: tieni solo i numeri
    // WhatsApp wa.me richiede il numero nel formato: prefisso + numero senza '+' o spazi
    // Esempio: 393331234567
    const cleanPhone = phone.replace(/\D/g, '');

    if (cleanPhone.length < 10) {
      alert("Il numero di telefono sembra incompleto o errato.");
      return;
    }

    const msg = encodeURIComponent(getPINMessage(user));
    // Utilizziamo l'endpoint api.whatsapp.com per una compatibilità maggiore su mobile
    const whatsappUrl = `https://api.whatsapp.com/send?phone=${cleanPhone}&text=${msg}`;

    window.open(whatsappUrl, '_blank');
  };

  const handleSave = async () => {
    if (!editing?.firstName || !editing?.lastName || !editing?.pin || !editing?.phone_e164) {
      setError('Tutti i campi (Nome, Cognome, Telefono e PIN) sono obbligatori');
      return;
    }

    // Validazione base del numero di telefono
    if (!editing.phone_e164.includes('+')) {
      setError('Inserisci il prefisso internazionale (es. +39 per Italia)');
      return;
    }

    if (editing.pin.length < 4 || editing.pin.length > 6 || !/^\d+$/.test(editing.pin)) {
      setError('Il PIN deve essere composto da 4-6 cifre numeriche');
      return;
    }

    setSaving(true);
    setError('');

    try {
      const isAvailable = await db.isPinAvailable(editing.pin, editing.id);
      if (!isAvailable) {
        setError('Questo PIN è già in uso da un altro utente attivo');
        setSaving(false);
        return;
      }

      await db.saveUser(editing);
      await fetchUsers();

      setSuccessUser({ ...editing as User });
      setEditing(null);
    } catch (err: any) {
      setError(err.message || "Errore nel salvataggio. Verifica che il numero di telefono sia univoco.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Layout title="Gestione Personale" onBack={onBack}>
      {toast && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] bg-black/80 text-white px-4 py-2 rounded-full text-sm font-bold animate-in fade-in zoom-in duration-200">
          {toast}
        </div>
      )}

      <div className="space-y-4">
        <Button fullWidth onClick={() => { setEditing({ role: Role.WORKER, pin: '', active: true, phone_e164: '+39' }); setError(''); }}>
          <Plus size={20} /> Nuovo Dipendente
        </Button>

        {loading ? (
          <div className="flex justify-center py-20"><div className="loading-spinner" /></div>
        ) : (
          <div className="space-y-3">
            {users.length === 0 ? (
              <p className="text-center text-[#8E8E93] py-10">Nessun dipendente registrato</p>
            ) : (
              users.map(u => (
                <Card key={u.id} className={`p-4 ${!u.active ? 'opacity-50 grayscale' : ''}`}>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white ${
                        u.role === Role.ADMIN ? 'bg-[#FF3B30]' : u.role === Role.SUPERVISOR ? 'bg-[#5856D6]' : 'bg-[#007AFF]'
                      }`}>
                        {u.firstName[0]}{u.lastName[0]}
                      </div>
                      <div>
                        <h3 className="font-bold">{u.firstName} {u.lastName}</h3>
                        <p className="text-[10px] font-bold text-[#8E8E93] uppercase tracking-wider">{u.role}</p>
                      </div>
                    </div>
                    <div className="flex gap-1">
                      <button onClick={() => { setEditing(u); setError(''); }} className="p-2 text-[#007AFF] bg-[#F2F2F7] rounded-full">
                        <Edit2 size={16} />
                      </button>
                      <button onClick={() => { if(window.confirm(`Eliminare ${u.firstName}?`)) db.deleteUser(u.id).then(fetchUsers) }} className="p-2 text-[#FF3B30] bg-red-50 rounded-full">
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                  <div className="mt-3 pt-3 border-t border-[#F2F2F7] flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-bold text-green-600 flex items-center gap-1">
                        <Check size={14} /> PIN configurato
                      </span>
                      <button 
                        onClick={() => { setEditing({ ...u, pin: '' }); setError(''); }}
                        className="text-[10px] bg-[#F2F2F7] px-2 py-1 rounded-full font-bold uppercase flex items-center gap-1 hover:bg-[#E5E5EA]"
                      >
                        <RefreshCw size={10} /> Rigenera
                      </button>
                    </div>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${u.active ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {u.active ? 'ATTIVO' : 'SOSPESO'}
                    </span>
                  </div>
                </Card>
              ))
            )}
          </div>
        )}
      </div>

      {/* Form Creazione/Modifica */}
      {editing && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40" onClick={() => !saving && setEditing(null)} />
          <div className="relative bg-white rounded-t-[32px] p-6 pb-10 space-y-4 shadow-2xl max-h-[90vh] overflow-y-auto animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">{editing.id ? 'Aggiorna Dipendente' : 'Nuovo Dipendente'}</h2>
              <button onClick={() => setEditing(null)} className="p-2 bg-[#F2F2F7] rounded-full">
                <X size={20} />
              </button>
            </div>

            {error && (
              <div className="bg-red-50 p-3 rounded-xl border border-red-100 flex items-center gap-2 text-[#FF3B30] text-xs font-bold animate-in fade-in duration-200">
                <AlertCircle size={16} className="shrink-0" />
                <span>{error}</span>
              </div>
            )}

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-[#8E8E93] uppercase pl-1">Nome</label>
                  <Input placeholder="Nome" value={editing.firstName || ''} onChange={e => setEditing({...editing, firstName: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-[#8E8E93] uppercase pl-1">Cognome</label>
                  <Input placeholder="Cognome" value={editing.lastName || ''} onChange={e => setEditing({...editing, lastName: e.target.value})} />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-[#8E8E93] uppercase pl-1">WhatsApp (es. +393331234567)</label>
                <Input 
                  placeholder="+39..."
                  type="tel"
                  value={editing.phone_e164 || ''} 
                  onChange={e => setEditing({...editing, phone_e164: e.target.value})} 
                />
                <p className="text-[9px] text-[#8E8E93] mt-1 italic">* Includi sempre il prefisso internazionale</p>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-[#8E8E93] uppercase pl-1">PIN Personale (4-6 cifre)</label>
                <Input 
                  type="text"
                  inputMode="numeric"
                  placeholder="Inserisci PIN"
                  className="font-mono tracking-widest text-lg"
                  value={editing.pin || ''} 
                  onChange={e => setEditing({...editing, pin: e.target.value.replace(/\D/g, '').slice(0, 6)})} 
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-[#8E8E93] uppercase pl-1">Ruolo</label>
                <select 
                  className="w-full px-4 py-3 rounded-xl bg-white border border-[#C6C6C8] outline-none text-sm font-medium"
                  value={editing.role}
                  onChange={e => setEditing({...editing, role: e.target.value as Role})}
                >
                  <option value={Role.WORKER}>Dipendente</option>
                  <option value={Role.SUPERVISOR}>Supervisor (Sola Lettura)</option>
                  <option value={Role.ADMIN}>Amministratore</option>
                </select>
              </div>

              <div className="flex items-center gap-2 py-2">
                <input 
                  type="checkbox" 
                  id="active_cb"
                  className="w-5 h-5 accent-[#007AFF]"
                  checked={editing.active !== false}
                  onChange={e => setEditing({...editing, active: e.target.checked})}
                />
                <label htmlFor="active_cb" className="text-sm font-bold text-[#1c1c1e]">Utente Attivo</label>
              </div>
            </div>

            <Button fullWidth onClick={handleSave} disabled={saving} className="mt-4">
              {saving ? <div className="loading-spinner border-white border-t-transparent" /> : 'Salva e Prepara Messaggio'}
            </Button>
          </div>
        </div>
      )}

      {/* Overlay Successo / Condivisione */}
      {successUser && (
        <div className="fixed inset-0 z-[60] flex flex-col justify-center items-center p-6">
          <div className="absolute inset-0 bg-[#007AFF]/95 backdrop-blur-md" />
          <div className="relative w-full max-w-sm bg-white rounded-[32px] p-8 text-center space-y-6 shadow-2xl animate-in zoom-in duration-300">
            <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-2">
              <Check size={40} />
            </div>

            <div>
              <h2 className="text-2xl font-black tracking-tight text-[#1c1c1e]">Dati Salvati!</h2>
              <p className="text-[#8E8E93] text-sm mt-1">Invia le credenziali a <span className="text-black font-bold">{successUser.firstName}</span></p>
            </div>

            <div className="bg-[#F2F2F7] p-4 rounded-2xl border border-[#E5E5EA]">
              <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1 tracking-widest">PIN Da Comunicare</p>
              <p className="text-3xl font-mono font-black tracking-[0.2em] text-[#007AFF]">{successUser.pin}</p>
            </div>

            <div className="space-y-3 pt-2">
              <Button fullWidth className="!bg-[#25D366] !text-white border-none shadow-lg" onClick={() => sendWhatsApp(successUser)}>
                <MessageCircle size={20} /> Invia su WhatsApp
              </Button>
              <Button fullWidth variant="secondary" className="border border-[#D1D1D6]" onClick={() => copyToClipboard(successUser)}>
                <Copy size={20} /> Copia Messaggio Testuale
              </Button>
              <p className="text-[10px] text-[#8E8E93] px-4 leading-relaxed italic">
                Nota: WhatsApp aprirà una chat. Dovrai premere "Invia" manualmente per completare la consegna.
              </p>
              <button 
                onClick={() => setSuccessUser(null)} 
                className="w-full text-xs font-bold text-[#8E8E93] uppercase tracking-widest pt-2"
              >
                Ho terminato
              </button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

