  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [selectedAddIds, setSelectedAddIds] = useState<string[]>([]);
  const [selectedRemoveIds, setSelectedRemoveIds] = useState<string[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  const addOptions = modifications.filter(m => m.type === 'ADD' && m.active);
  const removeOptions = modifications.filter(m => m.type === 'REMOVE' && m.active);

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
    };
    checkBio();
  }, []);

  // Determina se oggi è possibile ordinare
  const availability = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return getDayAvailability(
        today, 
        settings?.active_days || [], 
        overrides, 
        currentDay
    );
  }, [settings, overrides, currentDay]);

  const canOrder = useMemo(() => {
    if (settings?.override_cutoff) return true; // Master override per admin debugging
    return availability.isActive;
  }, [availability, settings]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, modList, day, order, globalSettings, dayOverrides] = await Promise.all([
          db.getPizzas(),
          db.getModifications(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings(),
          db.getOverrides()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setModifications(modList || []);
        setCurrentDay(day);
        setMyOrder(order);
        setSettings(globalSettings);
        setOverrides(dayOverrides);
      } catch (err: any) {
        setErrorMessage(err.message || "Errore nel caricamento dei dati");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleToggleBiometrics = async () => {
    if (biometricEnabled) {
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
    } else {
      try {
        const success = await registerBiometrics(user.id, user.firstName);
        if (success) {
          localStorage.setItem('pizzastaff_stored_pin', user.pin);
          localStorage.setItem('pizzastaff_biometric_enabled', 'true');
          localStorage.removeItem('pizzastaff_biometric_declined');
          setBiometricEnabled(true);
        } else {
          setErrorMessage("Registrazione biometrica non riuscita.");
        }
      } catch (err) {
        setErrorMessage("Errore durante l'attivazione della biometria.");
      }
    }
  };

  const handleToggleAdd = (id: string) => {
    setSelectedAddIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleToggleRemove = (id: string) => {
    setSelectedRemoveIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleConfirmOrder = async () => {
    if (!selectedPizza) return;
    setSubmitting(true);
    setErrorMessage(null);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay?.id, // Può essere null, db.saveOrder creerà la giornata
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        addModificationIds: selectedAddIds,
        removeModificationIds: selectedRemoveIds,
        note: ''
      };
      await db.saveOrder(order);

      setShowSuccess(true);
      setSelectedPizza(null);

      setTimeout(() => {
        onLogout();
      }, 2000);

    } catch (err: any) {
      setErrorMessage(err.message || "Errore durante il salvataggio");
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-8 !h-8" /></div>
      </Layout>
    );
  }

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    const isAfterCutoff = !isBeforeCutoff();
    const showClosedMessage = !canOrder;

    return (
      <div className="space-y-6">
        {showClosedMessage && (
          <div className="bg-[#FF3B30] text-white p-5 rounded-2xl flex items-center gap-4 shadow-xl animate-in slide-in-from-top-4 duration-300">
            <div className="p-3 bg-white/20 rounded-full">
                <Lock size={28} />
            </div>
            <div>
              <p className="font-black text-lg tracking-tight">Servizio non attivo</p>
              <p className="text-xs font-medium opacity-90 leading-tight">
                {isAfterCutoff && availability.isActive === false && availability.label.includes('Cutoff')
                    ? "Gli ordini sono chiusi dopo le 16:30."
                    : "Oggi non è prevista l'ordinazione delle pizze staff."
                }
              </p>
            </div>
          </div>
        )}

        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 ${availability.isActive ? 'border-[#34C759]' : 'border-[#C6C6C8] opacity-80 grayscale'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <p className={`text-[10px] font-black ${availability.isActive ? 'text-[#34C759]' : 'text-[#8E8E93]'} uppercase tracking-widest mb-1`}>La tua scelta per oggi</p>
                <h2 className="text-2xl font-black">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
                <div className="mt-2 flex flex-wrap gap-1">
                  {myOrder.addModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-green-100 text-green-700">+{mod.name}</span> : null;
                  })}
                  {myOrder.removeModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-red-100 text-red-700">-{mod.name}</span> : null;
                  })}
                </div>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <ClockIcon size={16} className="text-[#8E8E93]" />
                <span className="text-sm font-bold">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { 
                  setSelectedPizza(p); 
                  setSlot(myOrder.slotTime); 
                  setSelectedAddIds(myOrder.addModificationIds || []); 
                  setSelectedRemoveIds(myOrder.removeModificationIds || []);
                  setIsEditing(true); 
                }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] hover:!bg-[#E5E5EA]">
                Modifica Scelta
              </Button>
            )}
          </Card>
        )}

        {(!myOrder || isEditing) && !selectedPizza && (
          <div className={`${!canOrder ? 'opacity-40 pointer-events-none' : ''}`}>
            <div className="relative mb-6">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
              <Input 
                placeholder="Cerca la tua pizza..." 
                className="pl-10 !rounded-2xl border-none shadow-sm"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            <div className="space-y-3">
              {filteredPizzas.map(pizza => (
                <Card 
                  key={pizza.id} 
                  className="p-4 cursor-pointer active:scale-95 transition-transform"
                  onClick={() => canOrder && setSelectedPizza(pizza)}
                >
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-black">VEG</span>}
                  </div>
                  <p className="text-xs text-[#8E8E93] leading-relaxed">{pizza.ingredients?.join(', ')}</p>
                </Card>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  const isManagement = user.role === Role.ADMIN || user.role === Role.SUPERVISOR;

  return (
    <Layout 
      title={activeTab === 'menu' ? 'Menu Pizze' : 'Impostazioni'}
      onBack={activeTab === 'settings' ? () => setActiveTab('menu') : undefined}
    >
      {showSuccess && (
        <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center p-6 bg-white/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 animate-in zoom-in duration-500">
            <Check size={48} strokeWidth={3} />
          </div>
          <h2 className="text-3xl font-black text-[#1c1c1e] tracking-tight">Pizza ordinata</h2>
          <p className="text-[#8E8E93] font-bold mt-2 uppercase tracking-[0.2em] text-[10px]">Arrivederci!</p>
        </div>
      )}

      {errorMessage && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl bg-[#FF3B30] text-white flex items-center gap-3 animate-in fade-in slide-in-from-top-10 duration-500">
          <AlertCircle size={20} />
          <p className="font-bold text-sm flex-1">{errorMessage}</p>
          <button onClick={() => setErrorMessage(null)}><X size={18} /></button>
        </div>
      )}

      {activeTab === 'menu' ? renderMenu() : (
        <div className="space-y-6 animate-in slide-in-from-right duration-300">
           <div className="text-center py-6">
            <div className="w-20 h-20 bg-[#007AFF] rounded-full flex items-center justify-center text-white mx-auto shadow-xl mb-3">
              <UserIcon size={40} />
            </div>
            <h2 className="text-xl font-black">{user.firstName} {user.lastName}</h2>
            <p className="text-xs font-bold text-[#8E8E93] uppercase tracking-widest mt-1">{user.role}</p>
          </div>

          <section className="space-y-2">
            <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest pl-2">Accesso Rapido</p>
            <Card className="divide-y divide-[#F2F2F7]">
              {isBioSupported ? (
                <div className="p-4 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-[#F2F2F7] text-[#8E8E93]'}`}>
                      <Fingerprint size={20} />
                    </div>
                    <div>
                      <p className="text-sm font-bold">Face ID / Touch ID</p>
                      <p className="text-[10px] text-[#8E8E93] uppercase font-black">Accedi senza PIN</p>
                    </div>
                  </div>
                  <button 
                    onClick={handleToggleBiometrics}
                    className={`w-12 h-6 rounded-full transition-colors relative flex items-center px-1 ${
                      biometricEnabled ? 'bg-[#34C759]' : 'bg-[#C6C6C8]'
                    }`}
                  >
                    <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform duration-200 ${
                      biometricEnabled ? 'translate-x-6' : 'translate-x-0'
                    }`} />
                  </button>
                </div>
              ) : (
                <div className="p-4 flex items-center gap-3 opacity-50">
                   <div className="p-2 rounded-full bg-gray-100 text-gray-400">
                      <Fingerprint size={20} />
                    </div>
                    <div>
                      <p className="text-sm font-bold">Biometria non supportata</p>
                      <p className="text-[10px] text-[#8E8E93] uppercase font-black">Browser o hardware limitato</p>
                    </div>
                </div>
              )}
            </Card>
          </section>

          <section className="space-y-2">
            <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest pl-2">Account</p>
            <Card className="divide-y divide-[#F2F2F7]">
              <button onClick={onLogout} className="w-full p-4 flex justify-between items-center text-[#FF3B30] font-bold active:bg-[#F2F2F7] transition-colors">
                <span>Esci dall'app</span>
                <LogOut size={20} />
              </button>

              {isManagement && onBackToAdmin && (
                <button onClick={onBackToAdmin} className="w-full p-4 flex justify-between items-center text-[#5856D6] font-bold active:bg-[#F2F2F7] transition-colors">
                  <span>Pannello Admin</span>
                  <Sliders size={20} />
                </button>
              )}
            </Card>
          </section>
        </div>
      )}

      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-lg ios-blur border-t border-[#C6C6C8] px-8 py-3 pb-8 flex justify-between items-center z-40">
        <button onClick={() => setActiveTab('menu')} className={`flex flex-col items-center gap-1 ${activeTab === 'menu' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}>
          <PizzaIcon size={24} />
          <span className="text-[10px] font-bold">Ordina</span>
        </button>

        {isManagement && onBackToAdmin && (
           <button onClick={onBackToAdmin} className="flex flex-col items-center gap-1 text-[#5856D6]">
             <Sliders size={24} />
             <span className="text-[10px] font-bold">Admin</span>
           </button>
        )}

        <button onClick={() => setActiveTab('settings')} className={`flex flex-col items-center gap-1 ${activeTab === 'settings' ? 'text-[#007AFF]' : 'text-[#8E8E93]'}`}>
          <Settings size={24} />
          <span className="text-[10px] font-bold">Impostazioni</span>
        </button>
      </nav>

      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => !submitting && setSelectedPizza(null)} />
          <div className="relative bg-[#F2F2F7] rounded-t-[32px] p-6 pb-12 space-y-6 shadow-2xl animate-in slide-in-from-bottom duration-300 overflow-y-auto max-h-[90vh]">
            <div className="w-12 h-1.5 bg-[#C6C6C8] rounded-full mx-auto" />
            <h2 className="text-2xl font-black text-center">{selectedPizza.name}</h2>

            <div className="space-y-6">
              <section className="space-y-3">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Orario di ritiro</p>
                <SegmentedControl options={SLOT_TIMES} selected={slot} onChange={(v) => setSlot(v as SlotTime)} />
              </section>

              <section className="space-y-3">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Aggiunte (+)</p>
                <div className="bg-white rounded-2xl overflow-hidden divide-y divide-[#F2F2F7]">
                  {addOptions.map(opt => (
                    <button 
                      key={opt.id} 
                      onClick={() => handleToggleAdd(opt.id)}
                      className="w-full flex items-center justify-between p-4 active:bg-[#F2F2F7] transition-colors"
                    >
                      <span className="text-sm font-medium">{opt.name}</span>
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        selectedAddIds.includes(opt.id) ? 'bg-[#007AFF] border-[#007AFF]' : 'border-[#C6C6C8]'
                      }`}>
                        {selectedAddIds.includes(opt.id) && <Check size={14} className="text-white" />}
                      </div>
                    </button>
                  ))}
                  {addOptions.length === 0 && <p className="p-4 text-xs text-[#8E8E93] text-center">Nessuna opzione disponibile</p>}
                </div>
              </section>

              <section className="space-y-3">
                <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Rimossoni (-)</p>
                <div className="bg-white rounded-2xl overflow-hidden divide-y divide-[#F2F2F7]">
                  {removeOptions.map(opt => (
                    <button 
                      key={opt.id} 
                      onClick={() => handleToggleRemove(opt.id)}
                      className="w-full flex items-center justify-between p-4 active:bg-[#F2F2F7] transition-colors"
                    >
                      <span className="text-sm font-medium">{opt.name}</span>
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        selectedRemoveIds.includes(opt.id) ? 'bg-[#FF3B30] border-[#FF3B30]' : 'border-[#C6C6C8]'
                      }`}>
                        {selectedRemoveIds.includes(opt.id) && <Check size={14} className="text-white" />}
                      </div>
                    </button>
                  ))}
                   {removeOptions.length === 0 && <p className="p-4 text-xs text-[#8E8E93] text-center">Nessuna opzione disponibile</p>}
                </div>
              </section>

              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting}>
                {submitting ? <div className="loading-spinner border-white border-t-transparent" /> : 'Invia Ordine'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default WorkerDashboard;

import React, { useState, useEffect } from 'react';
import { AuthState, User, Role } from './types';
import { db } from './services/db';
import LoginView from './views/Login';
import WorkerDashboard from './views/WorkerDashboard';
import AdminDashboard from './views/AdminDashboard';
import AdminPizzas from './views/AdminPizzas';
import AdminUsers from './views/AdminUsers';
import AdminHistory from './views/AdminHistory';
import AdminModifications from './views/AdminModifications';
import AdminCalendar from './views/AdminCalendar';
import { Fingerprint } from './components/Icons';
import { Button } from './components/UI';

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('pizzastaff_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const [view, setView] = useState<'dashboard' | 'pizzas' | 'users' | 'history' | 'modifications' | 'order' | 'calendar'>('dashboard');
  const [showBiometricPrompt, setShowBiometricPrompt] = useState(false);
  const [isBiometricSupported, setIsBiometricSupported] = useState(false);

  useEffect(() => {
    localStorage.setItem('pizzastaff_auth', JSON.stringify(auth));

    const checkSupport = async () => {
      const supported = !!(window.PublicKeyCredential && 
        await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable());
      setIsBiometricSupported(supported);
    };
    checkSupport();
  }, [auth]);

  const handleLogin = (user: User) => {
    setAuth({ user, isAuthenticated: true });

    const biometricEnabled = localStorage.getItem('pizzastaff_biometric_enabled') === 'true';
    const hasDeclined = localStorage.getItem('pizzastaff_biometric_declined') === 'true';

    if (!biometricEnabled && !hasDeclined && window.PublicKeyCredential) {
      setTimeout(() => setShowBiometricPrompt(true), 1500);
    }
  };

  const handleLogout = () => {
    setAuth({ user: null, isAuthenticated: false });
    setView('dashboard');
  };

  const enableBiometrics = () => {
    if (auth.user?.pin) {
      localStorage.setItem('pizzastaff_stored_pin', auth.user.pin);
      localStorage.setItem('pizzastaff_biometric_enabled', 'true');
      localStorage.removeItem('pizzastaff_biometric_declined');
      setShowBiometricPrompt(false);
    }
  };

  const declineBiometrics = () => {
    localStorage.setItem('pizzastaff_biometric_declined', 'true');
    setShowBiometricPrompt(false);
  };

  if (!auth.isAuthenticated || !auth.user) {
    return <LoginView onLogin={handleLogin} />;
  }

  // Se l'utente è un semplice Worker, vede solo la dashboard ordini
  if (auth.user.role === Role.WORKER) {
    return <WorkerDashboard user={auth.user} onLogout={handleLogout} />;
  }

  // Se l'utente è ADMIN o SUPERVISOR, ha accesso a tutto
  return (
    <div className="bg-[#F2F2F7] min-h-screen">
      {view === 'pizzas' && <AdminPizzas onBack={() => setView('dashboard')} />}
      {view === 'users' && <AdminUsers onBack={() => setView('dashboard')} />}
      {view === 'history' && <AdminHistory onBack={() => setView('dashboard')} />}
      {view === 'modifications' && <AdminModifications onBack={() => setView('dashboard')} />}
      {view === 'calendar' && <AdminCalendar onBack={() => setView('dashboard')} />}
      {view === 'order' && <WorkerDashboard user={auth.user} onLogout={handleLogout} onBackToAdmin={() => setView('dashboard')} />}
      {view === 'dashboard' && (
        <AdminDashboard 
          user={auth.user} 
          onLogout={handleLogout} 
          onNavigate={(v: any) => setView(v)} 
          onGoToOrder={() => setView('order')}
        />
      )}

      {showBiometricPrompt && isBiometricSupported && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={declineBiometrics} />
          <div className="relative bg-white w-full max-w-sm rounded-[32px] p-8 shadow-2xl animate-in slide-in-from-bottom duration-500 text-center space-y-6">
            <div className="w-20 h-20 bg-[#F2F2F7] text-[#007AFF] rounded-full flex items-center justify-center mx-auto">
              <Fingerprint size={40} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-[#1c1c1e]">Accesso Rapido</h3>
              <p className="text-sm text-[#8E8E93] mt-2 leading-relaxed">
                Vuoi attivare il Face ID o l'impronta digitale per accedere più velocemente la prossima volta?
              </p>
            </div>
            <div className="space-y-3">
              <Button fullWidth onClick={enableBiometrics}>Attiva Ora</Button>
              <button 
                onClick={declineBiometrics}
                className="w-full py-2 text-sm font-bold text-[#8E8E93] uppercase tracking-widest"
              >
                Magari più tardi
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db, GlobalSettings } from '../services/db';
import { DayOverride, OverrideType, Day } from '../types';
import { Layout } from '../components/Layout';
import { Card, Button } from '../components/UI';
import { Calendar, Trash2, Check, ClockIcon, X, Unlock, Lock, RotateCcw } from '../components/Icons';
import { formatDate, getDayAvailability } from '../services/utils';

const WEEKDAYS = [
  { id: 'MON', label: 'Lunedì' },
  { id: 'TUE', label: 'Martedì' },
  { id: 'WED', label: 'Mercoledì' },
  { id: 'THU', label: 'Giovedì' },
  { id: 'FRI', label: 'Venerdì' },
  { id: 'SAT', label: 'Sabato' },
  { id: 'SUN', label: 'Domenica' }
];

const AdminCalendar: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [settings, setSettings] = useState<GlobalSettings | null>(null);
  const [overrides, setOverrides] = useState<DayOverride[]>([]);
  const [currentDayRecord, setCurrentDayRecord] = useState<Day | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [s, o, d] = await Promise.all([
        db.getSettings(),
        db.getOverrides(),
        db.getCurrentDay()
      ]);
      setSettings(s);
      setOverrides(o);
      setCurrentDayRecord(d);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const toggleRecurringDay = async (dayId: string) => {
    if (!settings) return;
    const active = settings.active_days || [];
    const newActive = active.includes(dayId) 
      ? active.filter(d => d !== dayId) 
      : [...active, dayId];

    try {
      await db.updateSettings({ active_days: newActive });
      setSettings({ ...settings, active_days: newActive });
    } catch (err) {
      alert("Errore salvataggio ricorrenza");
    }
  };

  const handleToggleOverride = async (dateStr: string, currentStatus: any) => {
    setActionLoading(dateStr);
    try {
      const existingOverride = overrides.find(o => o.date === dateStr);

      if (existingOverride) {
        // Se esiste già un'eccezione, la rimuoviamo (ripristina default)
        await db.deleteOverride(existingOverride.id);
      } else {
        // Se non esiste, creiamo l'eccezione opposta allo stato attuale
        const newType = currentStatus.isActive ? OverrideType.DISABLED : OverrideType.EXTRA;
        await db.saveOverride({
          date: dateStr,
          type: newType,
          note: 'Manuale da calendario'
        });
      }
      await fetchData();
    } catch (err) {
      alert("Errore nell'aggiornamento della data");
    } finally {
      setActionLoading(null);
    }
  };

  const getNextDays = () => {
    const days = [];
    const start = new Date();
    for (let i = 0; i < 14; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      days.push({
        dateStr: dStr,
        availability: getDayAvailability(dStr, settings?.active_days || [], overrides, i === 0 ? currentDayRecord : null)
      });
    }
    return days;
  };

  if (loading && !settings) return <Layout title="Calendario" onBack={onBack}><div className="flex justify-center py-20"><div className="loading-spinner" /></div></Layout>;

  return (
    <Layout title="Gestione Date" onBack={onBack}>
      <div className="space-y-8 pb-10">

        {/* Sezione Giorni Ricorrenti */}
        <section className="space-y-3">
          <div className="flex items-center gap-2 px-1">
            <ClockIcon size={18} className="text-[#007AFF]" />
            <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Programma Settimanale (Loop)</p>
          </div>
          <Card className="p-4">
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
              {WEEKDAYS.map(day => {
                const isActive = settings?.active_days.includes(day.id);
                return (
                  <button
                    key={day.id}
                    onClick={() => toggleRecurringDay(day.id)}
                    className={`px-3 py-2.5 rounded-xl text-xs font-black transition-all border-2 flex items-center justify-center gap-2 ${
                      isActive 
                        ? 'bg-[#007AFF] text-white border-[#007AFF]' 
                        : 'bg-white text-[#8E8E93] border-[#F2F2F7] shadow-sm'
                    }`}
                  >
                    {isActive && <Check size={14} />}
                    {day.label}
                  </button>
                );
              })}
            </div>
            <p className="text-[9px] text-[#8E8E93] mt-3 italic text-center">I giorni selezionati saranno aperti automaticamente ogni settimana.</p>
          </Card>
        </section>

        {/* Prossimi 14 Giorni Interattivi */}
        <section className="space-y-3">
          <div className="flex items-center gap-2 px-1">
            <Calendar size={18} className="text-[#34C759]" />
            <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest">Calendario Prossime 2 Settimane</p>
          </div>

          <div className="space-y-3">
            {getNextDays().map(({ dateStr, availability }) => {
              const hasOverride = overrides.some(o => o.date === dateStr);
              const isToday = availability.isToday;

              return (
                <Card key={dateStr} className={`p-4 flex flex-col gap-3 transition-all ${isToday ? 'ring-2 ring-[#007AFF] ring-inset' : ''}`}>
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="flex items-center gap-2">
                         <span className="text-sm font-black text-[#1c1c1e]">{formatDate(dateStr)}</span>
                         {isToday && <span className="bg-[#007AFF] text-white text-[8px] px-1.5 py-0.5 rounded-full font-bold uppercase">Oggi</span>}
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                        <span className={`text-[9px] font-black px-1.5 py-0.5 rounded-full uppercase tracking-tighter ${availability.colorClass}`}>
                          {availability.label}
                        </span>
                        {hasOverride && (
                          <span className="text-[8px] font-bold text-[#5856D6] uppercase flex items-center gap-0.5">
                            <RotateCcw size={10} /> Eccezione Attiva
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="text-right">
                       <span className={`text-[10px] font-black uppercase ${availability.isActive ? 'text-green-500' : 'text-red-500'}`}>
                         {availability.isActive ? '● Aperto' : '● Chiuso'}
                       </span>
                    </div>
                  </div>

                  <div className="flex gap-2">
                    {availability.isActive ? (
                      <Button 
                        fullWidth 
                        size="sm" 
                        variant="danger" 
                        className="!rounded-xl !text-[10px] !py-2"
                        disabled={actionLoading === dateStr}
                        onClick={() => handleToggleOverride(dateStr, availability)}
                      >
                        {actionLoading === dateStr ? <div className="loading-spinner border-white" /> : <><Lock size={14} /> Forza Chiusura</>}
                      </Button>
                    ) : (
                      <Button 
                        fullWidth 
                        size="sm" 
                        variant="primary" 
                        className="!rounded-xl !text-[10px] !py-2 !bg-[#34C759]"
                        disabled={actionLoading === dateStr}
                        onClick={() => handleToggleOverride(dateStr, availability)}
                      >
                        {actionLoading === dateStr ? <div className="loading-spinner border-white" /> : <><Unlock size={14} /> Forza Apertura</>}
                      </Button>
                    )}

                    {hasOverride && (
                      <button 
                        onClick={() => handleToggleOverride(dateStr, availability)}
                        className="p-2 bg-[#F2F2F7] text-[#8E8E93] rounded-xl active:bg-[#E5E5EA]"
                        title="Ripristina Default"
                      >
                        <RotateCcw size={18} />
                      </button>
                    )}
                  </div>
                </Card>
              );
            })}
          </div>
        </section>

      </div>
    </Layout>
  );
};

export default AdminCalendar;

import { CUTOFF_TIME } from '../constants';
import { DayOverride, OverrideType, DayStatus, Day } from '../types';

/**
 * Verifica se l'ora corrente è prima del cutoff (16:30)
 */
export const isBeforeCutoff = (): boolean => {
  const now = new Date();
  const [cutoffHour, cutoffMinute] = CUTOFF_TIME.split(':').map(Number);

  const cutoff = new Date(now);
  cutoff.setHours(cutoffHour, cutoffMinute, 0, 0);

  return now < cutoff;
};

/**
 * Determina se una data specifica è considerata giornata di ordini attiva
 */
export const getDayAvailability = (
  dateStr: string,
  recurringDays: string[], // ['MON', 'TUE'...]
  overrides: DayOverride[],
  manualDayRecord?: Day | null
) => {
  // Parsing robusto della data per evitare problemi di fuso orario
  const [year, month, day] = dateStr.split('-').map(Number);
  const date = new Date(year, month - 1, day);

  const dayNames = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
  const dayName = dayNames[date.getDay()];

  const override = overrides.find(o => o.date === dateStr);

  let isActive = false;
  let label = '';
  let colorClass = '';

  // 1. Controllo Override (Priorità Massima)
  if (override) {
    if (override.type === OverrideType.DISABLED || override.type === OverrideType.FORCE_CLOSED) {
      isActive = false;
      label = 'DISATTIVATO (Manuale)';
      colorClass = 'text-red-500 bg-red-50';
    } else if (override.type === OverrideType.EXTRA || override.type === OverrideType.FORCE_OPEN) {
      isActive = true;
      label = 'GIORNATA EXTRA';
      colorClass = 'text-[#FF9500] bg-orange-50';
    }
  } else {
    // 2. Controllo Ricorrenza
    isActive = recurringDays.includes(dayName);
    label = isActive ? 'RICORRENTE' : 'NON PREVISTO';
    colorClass = isActive ? 'text-green-600 bg-green-50' : 'text-gray-400 bg-gray-50';
  }

  // 3. Controllo record manuale di chiusura (se esiste nel DB record di 'days')
  if (manualDayRecord && manualDayRecord.status === DayStatus.CLOSED) {
    isActive = false;
    label = 'CHIUSA MANUALMENTE';
    colorClass = 'text-red-500 bg-red-50';
  }

  // 4. Controllo cutoff temporale (solo se oggi)
  const todayStr = new Date().toISOString().split('T')[0];
  const isToday = dateStr === todayStr;
  if (isActive && isToday && !isBeforeCutoff()) {
    isActive = false;
    label = 'CHIUSA (Oltre 16:30)';
    colorClass = 'text-[#8E8E93] bg-[#E5E5EA]';
  }

  return { isActive, label, colorClass, isToday };
};

export const formatTime = (date: string | Date): string => {
  return new Date(date).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' });
};

export const formatDate = (date: string | Date): string => {
  // Parsing robusto per la visualizzazione
  const d = typeof date === 'string' ? new Date(date + 'T12:00:00') : date;
  return d.toLocaleDateString('it-IT', { 
    weekday: 'long', 
    day: 'numeric', 
    month: 'long'
  });
};

export const getDayNameShort = (date: Date): string => {
  const dayNames = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
  return dayNames[date.getDay()];
};

