                    key={day.id}
                    onClick={() => toggleDay(day.id)}
                    className={`h-14 rounded-2xl flex flex-col items-center justify-center transition-all relative overflow-hidden active:scale-90 ${
                      isActive 
                        ? 'bg-[#007AFF] text-white shadow-lg' 
                        : 'bg-[#F2F2F7] text-[#8E8E93]'
