      if (err.message?.includes('SCHEMA ERROR') || err.message?.includes('add_modification_ids')) {
        setSchemaError("CONFIGURAZIONE DATABASE NECESSARIA: Manca la colonna 'add_modification_ids'. Esegui lo script SQL nel pannello di controllo.");
      } else if (err.message?.includes('relation "settings" does not exist')) {
        setError({ message: "Tabella 'settings' mancante.", code: '42P01' });
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleTitleClick = () => {
    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);

    const newCount = clickCount + 1;
    setClickCount(newCount);

    if (newCount === 7) {
      setShowResetPin(true);
      setClickCount(0);
    } else {
      resetTimerRef.current = setTimeout(() => setClickCount(0), 3000);
    }
  };

  const handleResetPinSubmit = () => {
    if (resetPin === '1131') {
      setShowResetPin(false);
      setShowFinalConfirm(true);
      setResetPin('');
    } else {
      alert("PIN Errato");
      setResetPin('');
    }
  };

  const executeSeasonalReset = async () => {
    setIsResetting(true);
    try {
      await db.resetSeasonalData();
      setShowFinalConfirm(false);
      setToast("Reset Stagionale Completato ✅");
      setTimeout(() => setToast(null), 3000);
      await fetchData();
    } catch (err: any) {
      alert("Errore durante il reset: " + err.message);
    } finally {
      setIsResetting(false);
    }
  };

  const handleToggleDay = async (action: 'open' | 'close') => {
    setActionLoading(true);
    try {
      if (action === 'open') {
        await db.openDay();
      } else {
        await db.closeDay();
      }
      await fetchData();
    } catch (err: any) {
      alert("Errore durante l'operazione: " + err.message);
    } finally {
      setActionLoading(false);
    }
  };

  const handleDownloadReport = () => {
    if (!currentDay || orders.length === 0) {
      alert("Nessun ordine presente per oggi.");
      return;
    }
    generateDayReportPDF(currentDay.date, orders, SLOT_TIMES);
  };

  const isAdmin = user.role === Role.ADMIN;
  const isSupervisor = user.role === Role.SUPERVISOR;

  if (loading && !error) {
    return (
      <Layout title="Admin" onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-10 !h-10" /></div>
      </Layout>
    );
  }

  return (
    <Layout 
      title="Dashboard Gestionale" 
      onLogout={onLogout}
    >
      {/* Easter Egg Trigger sul titolo invisibile (sovrapposto al titolo del layout tramite contatore interno) */}
      <div 
        className="fixed top-0 left-1/4 right-1/4 h-14 z-[60] cursor-default" 
        onClick={handleTitleClick}
      />

      {toast && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] bg-black text-white px-4 py-2 rounded-full text-xs font-bold animate-in fade-in zoom-in duration-300">
          {toast}
        </div>
      )}

      {/* Overlay PIN Reset */}
      {showResetPin && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <Card className="w-full max-w-sm p-8 space-y-6">
            <div className="text-center space-y-2">
              <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto">
                <Lock size={32} />
              </div>
              <h3 className="text-xl font-black">Area Riservata</h3>
              <p className="text-xs text-[#8E8E93] font-bold uppercase tracking-widest">Inserisci Codice Reset Stagione</p>
            </div>
            <Input 
              type="password" 
              placeholder="••••" 
              className="text-center text-3xl tracking-[1em] font-black"
              value={resetPin}
              onChange={e => setResetPin(e.target.value)}
              maxLength={4}
              autoFocus
            />
            <div className="flex gap-3">
              <Button variant="secondary" className="flex-1" onClick={() => { setShowResetPin(false); setResetPin(''); }}>Annulla</Button>
              <Button className="flex-1 !bg-red-600" onClick={handleResetPinSubmit}>Sblocca</Button>
            </div>
          </Card>
        </div>
      )}

      {/* Overlay Conferma Finale Reset */}
      {showFinalConfirm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-red-600/90 backdrop-blur-lg animate-in fade-in duration-300">
          <Card className="w-full max-w-sm p-8 space-y-6 text-center shadow-2xl">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto animate-pulse">
              <RotateCcw size={40} />
            </div>
            <div className="space-y-2">
              <h3 className="text-2xl font-black text-red-600">ATTENZIONE!</h3>
              <p className="text-sm font-bold text-[#1c1c1e] leading-tight">
                Stai per cancellare DEFINITIVAMENTE:<br/>
                <span className="text-red-600 font-black">• Tutti gli ordini passati</span><br/>
                <span className="text-red-600 font-black">• Tutte le giornate registrate</span>
              </p>
              <p className="text-[10px] text-[#8E8E93] font-medium italic pt-2">
                Dipendenti, Pizze e Variazioni NON saranno toccati.
              </p>
            </div>
            <div className="space-y-3 pt-4">
              <Button 
                fullWidth 
                variant="danger" 
                className="!py-4 text-lg !bg-red-700 shadow-xl" 
                onClick={executeSeasonalReset}
                disabled={isResetting}
              >
                {isResetting ? <RefreshCw className="animate-spin" /> : "SÌ, CANCELLA TUTTO"}
              </Button>
              <button 
                className="w-full text-xs font-black text-[#8E8E93] uppercase tracking-widest py-2"
                onClick={() => setShowFinalConfirm(false)}
                disabled={isResetting}
              >
                Annulla e Torna Indietro
              </button>
            </div>
          </Card>
        </div>
      )}

      <div className="space-y-6">
        {schemaError && (
          <Card className="p-4 bg-red-50 border-2 border-red-200 animate-pulse">
            <div className="flex items-start gap-3 text-red-700">
              <AlertCircle className="shrink-0 mt-1" size={20} />
              <div className="space-y-2">
                <p className="text-xs font-black uppercase">Errore Critico Database</p>
                <p className="text-sm font-bold leading-tight">{schemaError}</p>
                <Button onClick={fetchData} variant="secondary" className="!py-1.5 !text-[10px] !bg-white">
                  <RefreshCw size={12} /> Riprova
                </Button>
              </div>
            </div>
          </Card>
        )}

        <Card className="p-4 border-l-4 border-[#FF9500] bg-orange-50/30">
           <div className="flex justify-between items-center">
             <div className="flex items-center gap-3">
               <div className="p-2 bg-orange-100 text-orange-600 rounded-full">
                 <PizzaIcon size={24} />
               </div>
               <div>
                 <p className="text-[10px] font-bold text-[#8E8E93] uppercase">Sezione Personale</p>
                 <p className="text-sm font-bold">Ordina la tua pizza</p>
               </div>
             </div>
             <Button onClick={onGoToOrder} size="sm" className="!py-2">
               Vai al Menu
             </Button>
           </div>
        </Card>

        {settings && (
          <>
            <Card className="p-4">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <p className="text-xs font-bold text-[#8E8E93] uppercase">Status Ordini Staff</p>
                  <h2 className="text-lg font-bold">{formatDate(new Date())}</h2>
                </div>
                <div className={`px-3 py-1 rounded-full text-xs font-bold ${
                  currentDay?.status === DayStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                }`}>
                  {currentDay?.status || 'NON APERTO'}
                </div>
              </div>
              <div className="flex gap-2">
                {!currentDay || currentDay.status === DayStatus.CLOSED ? (
                  <Button 
                    onClick={() => handleToggleDay('open')} 
                    className="flex-1" 
                    disabled={actionLoading}
                  >
                    <Unlock size={18} /> Apri Ordini
                  </Button>
                ) : (
                  <Button 
                    onClick={() => handleToggleDay('close')} 
                    className="flex-1" 
                    variant="danger" 
                    disabled={actionLoading}
                  >
                    <Lock size={18} /> Chiudi Ordini
                  </Button>
                )}
              </div>
              <p className="text-[9px] text-[#8E8E93] mt-3 text-center uppercase font-bold tracking-wider">
                Azioni rapide per {isSupervisor ? 'Supervisore' : 'Admin'}
              </p>
            </Card>

            <div className="grid grid-cols-2 gap-3">
              <Card className="p-4 flex flex-col justify-center items-center text-center">
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1">Totale Ordini Oggi</p>
                <p className="text-3xl font-black text-[#007AFF]">{orders.length}</p>
              </Card>
              <Card className="p-4 flex flex-col justify-center items-center text-center">
                <p className="text-[10px] font-bold text-[#8E8E93] uppercase mb-1">Codice Locale</p>
                <p className="text-lg font-mono font-black">{settings.master_code}</p>
              </Card>
            </div>

            {orders.length > 0 && (
              <Button 
                variant="primary" 
                fullWidth 
                onClick={handleDownloadReport}
                className="!bg-[#34C759] hover:!bg-[#28A745] !py-4 shadow-lg active:scale-95"
              >
                <FileText size={20} /> Scarica Report Giornaliero
              </Button>
            )}
          </>
        )}

        {/* SEZIONE GESTIONE - SOLO PER ADMIN */}
        {isAdmin && (
          <div className="space-y-2 pt-4 border-t border-[#C6C6C8]">
            <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-[0.2em] mb-3 pl-1">Amministrazione</p>
            <Button variant="secondary" fullWidth onClick={() => onNavigate('calendar')} className="justify-start !bg-white border-2 border-[#F2F2F7]"><Calendar size={18} className="text-[#007AFF]" /> Programmazione Calendario</Button>
            <Button variant="secondary" fullWidth onClick={() => onNavigate('pizzas')} className="justify-start"><PizzaIcon size={18} /> Menu Pizze</Button>
            <Button variant="secondary" fullWidth onClick={() => onNavigate('modifications')} className="justify-start"><Sliders size={18} /> Variazioni</Button>
            <Button variant="secondary" fullWidth onClick={() => onNavigate('users')} className="justify-start"><UsersIcon size={18} /> Gestione PIN e Dipendenti</Button>
            <Button variant="secondary" fullWidth onClick={() => onNavigate('history')} className="justify-start"><History size={18} /> Storico Giornate</Button>
          </div>
        )}

        {!isAdmin && (
          <p className="text-center text-[10px] text-[#8E8E93] font-bold uppercase py-6">
            Accesso limitato al ruolo Supervisore
          </p>
        )}
      </div>
    </Layout>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus, Modification, Role, DayOverride } from '../types';
import { db, GlobalSettings } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { 
  PizzaIcon, 
  ClockIcon, 
  Search, 
  Check, 
  AlertCircle, 
  X, 
  Lock, 
  Settings, 
  UserIcon,
  LogOut,
  Sliders,
  Fingerprint,
  ChevronRight
} from '../components/Icons';
import { isBeforeCutoff, getDayAvailability } from '../services/utils';
import { SLOT_TIMES } from '../constants';
import { isBiometricAvailable, registerBiometrics } from '../services/biometrics';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
  onBackToAdmin?: () => void;
}

type ViewState = 'menu' | 'settings';

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout, onBackToAdmin }) => {
  const [activeTab, setActiveTab] = useState<ViewState>('menu');
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [modifications, setModifications] = useState<Modification[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [settings, setSettings] = useState<GlobalSettings | null>(null);
  const [overrides, setOverrides] = useState<DayOverride[]>([]);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [selectedAddIds, setSelectedAddIds] = useState<string[]>([]);
  const [selectedRemoveIds, setSelectedRemoveIds] = useState<string[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [showRecap, setShowRecap] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  const addOptions = modifications.filter(m => m.type === 'ADD' && m.active);
  const removeOptions = modifications.filter(m => m.type === 'REMOVE' && m.active);

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
    };
    checkBio();
  }, []);

  // Determina se oggi è possibile ordinare
  const availability = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return getDayAvailability(
        today, 
        settings?.active_days || [], 
        overrides, 
        currentDay
    );
  }, [settings, overrides, currentDay]);

  const canOrder = useMemo(() => {
    if (settings?.override_cutoff) return true; // Master override per admin debugging
    return availability.isActive;
  }, [availability, settings]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, modList, day, order, globalSettings, dayOverrides] = await Promise.all([
          db.getPizzas(),
          db.getModifications(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings(),
          db.getOverrides()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setModifications(modList || []);
        setCurrentDay(day);
        setMyOrder(order);
        setSettings(globalSettings);
        setOverrides(dayOverrides);
      } catch (err: any) {
        setErrorMessage(err.message || "Errore nel caricamento dei dati");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleToggleBiometrics = async () => {
    if (biometricEnabled) {
      localStorage.removeItem('pizzastaff_stored_pin');
      localStorage.setItem('pizzastaff_biometric_enabled', 'false');
      setBiometricEnabled(false);
    } else {
      try {
        const success = await registerBiometrics(user.id, user.firstName);
        if (success) {
          localStorage.setItem('pizzastaff_stored_pin', user.pin);
          localStorage.setItem('pizzastaff_biometric_enabled', 'true');
          localStorage.removeItem('pizzastaff_biometric_declined');
          setBiometricEnabled(true);
        } else {
          setErrorMessage("Registrazione biometrica non riuscita.");
        }
      } catch (err) {
        setErrorMessage("Errore durante l'attivazione della biometria.");
      }
    }
  };

  const handleToggleAdd = (id: string) => {
    setSelectedAddIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleToggleRemove = (id: string) => {
    setSelectedRemoveIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleConfirmOrder = async () => {
    if (!selectedPizza) return;
    setSubmitting(true);
    setErrorMessage(null);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay?.id, 
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        addModificationIds: selectedAddIds,
        removeModificationIds: selectedRemoveIds,
        note: ''
      };
      await db.saveOrder(order);

      setShowRecap(false);
      setShowSuccess(true);
      setSelectedPizza(null);

      setTimeout(() => {
        onLogout();
      }, 2000);

    } catch (err: any) {
      setErrorMessage(err.message || "Errore durante il salvataggio");
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Layout title="Caricamento..." onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-8 !h-8" /></div>
      </Layout>
    );
  }

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    const isAfterCutoff = !isBeforeCutoff();
    const showClosedMessage = !canOrder;

    return (
      <div className="space-y-6">
        {showClosedMessage && (
          <div className="bg-[#FF3B30] text-white p-5 rounded-2xl flex items-center gap-4 shadow-xl animate-in slide-in-from-top-4 duration-300">
            <div className="p-3 bg-white/20 rounded-full">
                <Lock size={28} />
            </div>
            <div>
              <p className="font-black text-lg tracking-tight">Servizio non attivo</p>
              <p className="text-xs font-medium opacity-90 leading-tight">
                {isAfterCutoff && availability.isActive === false && availability.label.includes('Cutoff')
                    ? "Gli ordini sono chiusi dopo le 16:30."
                    : "Oggi non è prevista l'ordinazione delle pizze staff."
                }
              </p>
            </div>
          </div>
        )}

        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 ${availability.isActive ? 'border-[#34C759]' : 'border-[#C6C6C8] opacity-80 grayscale'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <p className={`text-[10px] font-black ${availability.isActive ? 'text-[#34C759]' : 'text-[#8E8E93]'} uppercase tracking-widest mb-1`}>La tua scelta per oggi</p>
                <h2 className="text-2xl font-black">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
                <div className="mt-2 flex flex-wrap gap-1">
                  {myOrder.addModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-green-100 text-green-700">+{mod.name}</span> : null;
                  })}
                  {myOrder.removeModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-red-100 text-red-700">-{mod.name}</span> : null;
                  })}
                </div>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <ClockIcon size={16} className="text-[#8E8E93]" />
                <span className="text-sm font-bold">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { 
                  setSelectedPizza(p); 
                  setSlot(myOrder.slotTime); 
                  setSelectedAddIds(myOrder.addModificationIds || []); 
                  setSelectedRemoveIds(myOrder.removeModificationIds || []);
                  setIsEditing(true); 
                }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] hover:!bg-[#E5E5EA]">
                Modifica Scelta
              </Button>
            )}
          </Card>
        )}

        {(!myOrder || isEditing) && !selectedPizza && (
          <div className={`${!canOrder ? 'opacity-40 pointer-events-none' : ''}`}>
            <div className="relative mb-6">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={18} />
              <Input 
                placeholder="Cerca la tua pizza..." 
                className="pl-10 !rounded-2xl border-none shadow-sm"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            <div className="space-y-3">
              {filteredPizzas.map(pizza => (
                <Card 
                  key={pizza.id} 
                  className="p-4 cursor-pointer active:scale-95 transition-transform"
                  onClick={() => canOrder && setSelectedPizza(pizza)}
                >
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-lg">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-black">VEG</span>}
                  </div>
                  <p className="text-xs text-[#8E8E93] leading-relaxed">{pizza.ingredients?.join(', ')}</p>
                </Card>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  const isManagement = user.role === Role.ADMIN || user.role === Role.SUPERVISOR;

  return (
    <Layout 
      title={activeTab === 'menu' ? 'Menu Pizze' : 'Impostazioni'}
      onBack={activeTab === 'settings' ? () => setActiveTab('menu') : undefined}
    >
      {showSuccess && (
        <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center p-6 bg-white/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 animate-in zoom-in duration-500">
            <Check size={48} strokeWidth={3} />
          </div>
          <h2 className="text-3xl font-black text-[#1c1c1e] tracking-tight">Pizza ordinata</h2>
          <p className="text-[#8E8E93] font-bold mt-2 uppercase tracking-[0.2em] text-[10px]">Arrivederci!</p>
        </div>
      )}

      {errorMessage && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm p-4 rounded-2xl shadow-2xl bg-[#FF3B30] text-white flex items-center gap-3 animate-in fade-in slide-in-from-top-10 duration-500">
          <AlertCircle size={20} />
          <p className="font-bold text-sm flex-1">{errorMessage}</p>
          <button onClick={() => setErrorMessage(null)}><X size={18} /></button>
        </div>
      )}

      {activeTab === 'menu' ? renderMenu() : (
        <div className="space-y-6 animate-in slide-in-from-right duration-300">
           <div className="text-center py-6">
            <div className="w-20 h-20 bg-[#007AFF] rounded-full flex items-center justify-center text-white mx-auto shadow-xl mb-3">
              <UserIcon size={40} />
            </div>
            <h2 className="text-xl font-black">{user.firstName} {user.lastName}</h2>
            <p className="text-xs font-bold text-[#8E8E93] uppercase tracking-widest mt-1">{user.role}</p>
          </div>

          <section className="space-y-2">
            <p className="text-[10px] font-black text-[#8E8E93] uppercase tracking-widest pl-2">Accesso Rapido</p>
            <Card className="divide-y divide-[#F2F2F7]">
              {isBioSupported ? (
                <div className="p-4 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-[#F2F2F7] text-[#8E8E93]'}`}>
                      <Fingerprint size={20} />
                    </div>
