        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-6 border-2 max-w-2xl mx-auto ${availability.isActive ? 'border-[#34C759] shadow-lg' : 'border-[#C6C6C8] opacity-80 grayscale'}`}>
