        setModifications(modList || []);
        setCurrentDay(day);
        setMyOrder(order);
        setSettings(globalSettings);
        setOverrides(dayOverrides);
      } catch (err: any) {
        setErrorMessage(err.message || "Errore nel caricamento dei dati");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

