import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, DayStatus, Modification, Role, DayOverride } from '../types';
import { db, GlobalSettings } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { 
  PizzaIcon, 
  ClockIcon, 
  Search, 
  Check, 
  AlertCircle, 
  X, 
  Lock, 
  Settings, 
  UserIcon,
  LogOut,
  Sliders,
  Fingerprint
} from '../components/Icons';
import { isBeforeCutoff, getDayAvailability, getTodayDateString } from '../services/utils';
import { SLOT_TIMES } from '../constants';
import { isBiometricAvailable, registerBiometrics } from '../services/biometrics';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
  onBackToAdmin?: () => void;
}

type ViewState = 'menu' | 'settings';

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout, onBackToAdmin }) => {
  const [activeTab, setActiveTab] = useState<ViewState>('menu');
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [modifications, setModifications] = useState<Modification[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [settings, setSettings] = useState<GlobalSettings | null>(null);
  const [overrides, setOverrides] = useState<DayOverride[]>([]);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [selectedAddIds, setSelectedAddIds] = useState<string[]>([]);
  const [selectedRemoveIds, setSelectedRemoveIds] = useState<string[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [showRecap, setShowRecap] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_biometric_enabled') === 'true');

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
    };
    checkBio();
  }, []);

  const availability = useMemo(() => {
    const today = getTodayDateString();
    return getDayAvailability(
        today, 
        settings?.active_days || [], 
        overrides, 
        currentDay,
        settings?.cutoff_time || '16:30'
    );
  }, [settings, overrides, currentDay]);

  const canOrder = useMemo(() => {
    if (settings?.override_cutoff) return true;
    return availability.isActive;
  }, [availability, settings]);

  const addOptions = useMemo(() => modifications.filter(m => m.type === 'ADD' && m.active), [modifications]);
  const removeOptions = useMemo(() => modifications.filter(m => m.type === 'REMOVE' && m.active), [modifications]);

  const handleToggleAdd = (id: string) => {
    setSelectedAddIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleToggleRemove = (id: string) => {
    setSelectedRemoveIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, modList, day, order, globalSettings, dayOverrides] = await Promise.all([
          db.getPizzas(),
          db.getModifications(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings(),
          db.getOverrides()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setModifications(modList || []);
        setCurrentDay(day);
        setMyOrder(order);
        setSettings(globalSettings);
        setOverrides(dayOverrides);
      } catch (err: any) {
        setErrorMessage(err.message || "Errore nel caricamento dei dati");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleConfirmOrder = async () => {
    if (!selectedPizza) return;
    setSubmitting(true);
    setErrorMessage(null);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay?.id, 
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        addModificationIds: selectedAddIds,
        removeModificationIds: selectedRemoveIds,
        note: ''
      };
      await db.saveOrder(order);
      setShowRecap(false);
      setShowSuccess(true);
      setSelectedPizza(null);
      setTimeout(() => onLogout(), 2000);
    } catch (err: any) {
      setErrorMessage(err.message || "Errore durante il salvataggio");
      setSubmitting(false);
    }
  };

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    const showClosedMessage = !canOrder;

    return (
      <div className="space-y-5">
        <div className="pt-2 pb-1">
          <h1 className="text-[28px] font-black text-[#1c1c1e] tracking-tight leading-[1.1]">
            Ciao {user.firstName}!
          </h1>
          <p className="text-base font-bold text-[#8E8E93] mt-1">
            Cosa ti prepariamo oggi?
          </p>
        </div>

        {showClosedMessage && (
          <div className="bg-[#FF3B30] text-white p-4 rounded-2xl flex items-center gap-3 shadow-lg animate-in slide-in-from-top-4 duration-300">
            <div className="p-2 bg-white/20 rounded-full shrink-0">
                <Lock size={20} />
            </div>
            <div className="flex-1">
              <p className="font-black text-sm tracking-tight">Servizio non attivo</p>
              <p className="text-[10px] font-medium opacity-90 leading-tight">
                {availability.label.includes('OLTRE') 
                    ? `Gli ordini sono terminati alle ${settings?.cutoff_time}.`
                    : "Servizio non disponibile per la giornata odierna."
                }
              </p>
            </div>
          </div>
        )}

        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 max-w-2xl mx-auto ${availability.isActive ? 'border-[#34C759] shadow-lg' : 'border-[#C6C6C8] opacity-80 grayscale'}`}>
            <div className="flex justify-between items-start gap-3 mb-5">
              <div className="flex-1">
                <p className={`text-[9px] font-black ${availability.isActive ? 'text-[#34C759]' : 'text-[#8E8E93]'} uppercase tracking-[0.2em] mb-1.5`}>Il tuo ordine per oggi</p>
                <h2 className="text-xl font-black truncate">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
                <div className="mt-2 flex flex-wrap gap-1.5">
                  {myOrder.addModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-2 py-0.5 rounded-full bg-green-100 text-green-700">+{mod.name}</span> : null;
                  })}
                  {myOrder.removeModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-2 py-0.5 rounded-full bg-red-100 text-red-700">-{mod.name}</span> : null;
                  })}
                </div>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-xl flex items-center gap-1.5 shrink-0">
                <ClockIcon size={14} className="text-[#8E8E93]" />
                <span className="text-sm font-black">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { 
                  setSelectedPizza(p); 
                  setSlot(myOrder.slotTime); 
                  setSelectedAddIds(myOrder.addModificationIds || []); 
                  setSelectedRemoveIds(myOrder.removeModificationIds || []);
                  setIsEditing(true); 
                }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] !py-3">
                Modifica Scelta
              </Button>
            )}
          </Card>
        )}

        {(!myOrder || isEditing) && !selectedPizza && (
          <div className={`space-y-5 ${!canOrder ? 'opacity-40 pointer-events-none' : ''}`}>
            <div className="max-w-2xl mx-auto">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={16} />
                <Input 
                  placeholder="Cerca pizza..." 
                  className="pl-10 !py-3 !rounded-xl border-none shadow-sm bg-white"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pb-4">
              {filteredPizzas.map(pizza => (
                <Card 
                  key={pizza.id} 
                  className="p-4 cursor-pointer hover:shadow-md active:scale-[0.97] transition-all flex flex-col h-full border border-transparent hover:border-[#007AFF]/10"
                  onClick={() => canOrder && setSelectedPizza(pizza)}
                >
                  <div className="flex justify-between items-start mb-1.5">
                    <h3 className="font-black text-base text-[#1c1c1e] truncate pr-2">{pizza.name}</h3>
                    {pizza.isVegetarian && (
                      <span className="bg-green-100 text-green-700 text-[8px] px-1.5 py-0.5 rounded-full font-black tracking-wider shrink-0">VEG</span>
                    )}
                  </div>
                  <p className="text-[11px] text-[#8E8E93] leading-snug flex-1 italic line-clamp-2">
                    {pizza.ingredients?.join(', ')}
                  </p>
                  <div className="mt-3 pt-2 border-t border-[#F2F2F7] flex justify-end">
                    <span className="text-[#007AFF] text-[9px] font-black uppercase tracking-widest">Seleziona</span>
                  </div>
                </Card>
              ))}
