        <div className="w-full max-w-lg px-10 flex justify-between items-center">
          <button 
            onClick={() => setActiveTab('menu')} 
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'menu' ? 'text-[#007AFF] font-bold' : 'text-[#8E8E93] opacity-60'}`}
          >
            <PizzaIcon size={22} />
            <span className="text-[9px] font-black uppercase tracking-tighter">Menu</span>
          </button>

          {isManagement && onBackToAdmin && (
             <button onClick={onBackToAdmin} className="flex flex-col items-center gap-1 text-[#5856D6] active:scale-105 transition-transform">
               <Sliders size={22} />
               <span className="text-[9px] font-black uppercase tracking-tighter">Admin</span>
             </button>
          )}

          <button 
            onClick={() => setActiveTab('settings')} 
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'settings' ? 'text-[#007AFF] font-bold' : 'text-[#8E8E93] opacity-60'}`}
          >
            <Settings size={22} />
            <span className="text-[9px] font-black uppercase tracking-tighter">Profilo</span>
          </button>
        </div>
      </nav>

      {/* Modal selezione pizza adattata per Safe Area */}
      {selectedPizza && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end items-center overflow-hidden">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => !submitting && setSelectedPizza(null)} />
          <div className="relative bg-[#F2F2F7] w-full max-w-lg rounded-t-[28px] p-5 space-y-5 shadow-2xl animate-in slide-in-from-bottom duration-300 overflow-y-auto max-h-[90dvh] pb-[calc(2rem+env(safe-area-inset-bottom))]">
            <div className="w-10 h-1 bg-[#C6C6C8] rounded-full mx-auto shrink-0 mb-1" />

            <div className="text-center">
              <h2 className="text-xl font-black text-[#1c1c1e] truncate">{selectedPizza.name}</h2>
              <p className="text-[11px] text-[#8E8E93] mt-1 font-medium">{selectedPizza.ingredients?.join(', ')}</p>
            </div>

            <div className="space-y-5">
              <section className="space-y-2">
                <p className="text-[9px] font-black text-[#8E8E93] uppercase tracking-widest pl-1">Orario di ritiro</p>
                <div className="bg-white p-1.5 rounded-xl shadow-sm">
                  <SegmentedControl options={SLOT_TIMES} selected={slot} onChange={(v) => setSlot(v as SlotTime)} />
                </div>
              </section>

              <div className="space-y-5">
                <section className="space-y-2">
                  <p className="text-[9px] font-black text-[#8E8E93] uppercase tracking-widest pl-1">Aggiungi (+)</p>
                  <div className="bg-white rounded-xl shadow-sm overflow-hidden divide-y divide-[#F2F2F7]">
                    {addOptions.length === 0 && <p className="p-3 text-[10px] text-center text-gray-400 italic">Nessun ingrediente extra</p>}
                    {addOptions.map(opt => (
                      <button 
                        key={opt.id} 
                        onClick={() => handleToggleAdd(opt.id)}
                        className="w-full flex items-center justify-between p-3 active:bg-[#F2F2F7] transition-colors"
                      >
                        <span className="text-xs font-bold text-[#1c1c1e]">{opt.name}</span>
                        <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${
                          selectedAddIds.includes(opt.id) ? 'bg-[#007AFF] border-[#007AFF]' : 'border-[#C6C6C8]'
                        }`}>
                          {selectedAddIds.includes(opt.id) && <Check size={12} className="text-white" strokeWidth={3} />}
                        </div>
                      </button>
                    ))}
                  </div>
                </section>

                <section className="space-y-2">
                  <p className="text-[9px] font-black text-[#8E8E93] uppercase tracking-widest pl-1">Togli (-)</p>
                  <div className="bg-white rounded-xl shadow-sm overflow-hidden divide-y divide-[#F2F2F7]">
                    {removeOptions.length === 0 && <p className="p-3 text-[10px] text-center text-gray-400 italic">Nessuna rimozione</p>}
                    {removeOptions.map(opt => (
                      <button 
                        key={opt.id} 
                        onClick={() => handleToggleRemove(opt.id)}
                        className="w-full flex items-center justify-between p-3 active:bg-[#F2F2F7] transition-colors"
                      >
                        <span className="text-xs font-bold text-[#1c1c1e]">{opt.name}</span>
                        <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${
                          selectedRemoveIds.includes(opt.id) ? 'bg-[#FF3B30] border-[#FF3B30]' : 'border-[#C6C6C8]'
                        }`}>
                          {selectedRemoveIds.includes(opt.id) && <Check size={12} className="text-white" strokeWidth={3} />}
                        </div>
                      </button>
                    ))}
                  </div>
                </section>
              </div>

              <Button fullWidth onClick={() => setShowRecap(true)} disabled={submitting} className="!py-3.5 !text-base">
                Conferma Ordine
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Riepilogo finale compatto */}
      {showRecap && selectedPizza && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/70 backdrop-blur-md" onClick={() => !submitting && setShowRecap(false)} />
          <Card className="relative w-full max-w-xs p-5 space-y-5 shadow-2xl bg-white rounded-[24px]">
            <div className="text-center space-y-1">
              <h3 className="text-lg font-black text-[#1c1c1e] tracking-tight">Riepilogo</h3>
              <p className="text-[9px] text-[#8E8E93] font-bold uppercase tracking-widest">Verifica prima di inviare</p>
            </div>

            <div className="bg-[#F2F2F7] p-4 rounded-xl space-y-3">
                <div className="flex flex-col">
                  <p className="text-[8px] font-black text-[#8E8E93] uppercase tracking-tighter">La tua pizza</p>
                  <p className="text-base font-black truncate">{selectedPizza.name}</p>
                </div>
                <div className="flex flex-col">
                  <p className="text-[8px] font-black text-[#8E8E93] uppercase tracking-tighter">Orario</p>
                  <p className="text-base font-black">{slot}</p>
                </div>

              {(selectedAddIds.length > 0 || selectedRemoveIds.length > 0) && (
                <div className="pt-2 border-t border-[#C6C6C8]/20 space-y-1.5">
                  <div className="flex flex-wrap gap-1">
                    {selectedAddIds.map(id => {
                      const m = modifications.find(mod => mod.id === id);
                      return m ? <span key={id} className="text-[8px] font-black bg-green-100 text-green-700 px-1.5 py-0.5 rounded-full">+{m.name}</span> : null;
                    })}
                    {selectedRemoveIds.map(id => {
                      const m = modifications.find(mod => mod.id === id);
                      return m ? <span key={id} className="text-[8px] font-black bg-red-100 text-red-700 px-1.5 py-0.5 rounded-full">-{m.name}</span> : null;
                    })}
                  </div>
                </div>
              )}
            </div>

            <div className="flex flex-col gap-2 pt-1">
              <Button fullWidth onClick={handleConfirmOrder} disabled={submitting} className="!py-3.5 !text-sm shadow-md">
                {submitting ? <div className="loading-spinner border-white border-t-transparent" /> : 'SÌ, INVIA ORDINE'}
              </Button>
              <button 
                onClick={() => setShowRecap(false)}
                disabled={submitting}
                className="w-full py-2 text-[9px] font-black text-[#8E8E93] uppercase tracking-widest"
              >
                Modifica
              </button>
            </div>
          </Card>
        </div>
      )}
    </Layout>
  );
};

export default WorkerDashboard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { User, Day, DayStatus, SlotTime, Role, Modification, DayOverride } from '../types';
import { db, GlobalSettings } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, Input } from '../components/UI';
import { 
  UsersIcon, 
  PizzaIcon, 
  History, 
  Unlock, 
  Lock, 
  AlertCircle, 
  Sliders,
  RefreshCw,
  FileText,
  Calendar,
  RotateCcw,
  X,
  Check,
  ClockIcon
} from '../components/Icons';
import { formatDate, getDayAvailability, getTodayDateString } from '../services/utils';
import { generateDayReportPDF, HydratedOrder } from '../services/exportService';
import { SLOT_TIMES } from '../constants';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  onNavigate: (view: 'pizzas' | 'users' | 'history' | 'modifications' | 'calendar') => void;
  onGoToOrder: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout, onNavigate, onGoToOrder }) => {
  const [currentDay, setCurrentDay] = useState<Day | null>(null);
  const [orders, setOrders] = useState<HydratedOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [settings, setSettings] = useState<GlobalSettings | null>(null);
  const [overrides, setOverrides] = useState<DayOverride[]>([]);
  const [error, setError] = useState<{message: string, code?: string} | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  const [clickCount, setClickCount] = useState(0);
  const [showResetPin, setShowResetPin] = useState(false);
  const [resetPin, setResetPin] = useState('');
  const [showFinalConfirm, setShowFinalConfirm] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const resetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [day, globalSettings, dayOverrides] = await Promise.all([
        db.getCurrentDay(),
        db.getSettings(),
        db.getOverrides()
      ]);
      setCurrentDay(day);
      setSettings(globalSettings);
      setOverrides(dayOverrides);

      if (day) {
        const [dayOrders, users, pizzas, modifications] = await Promise.all([
          db.getOrdersByDay(day.id),
          db.getUsers(),
          db.getPizzas(),
          db.getModifications()
        ]);

        const hydratedOrders: HydratedOrder[] = dayOrders.map(o => ({
          ...o,
          user: users.find(u => u.id === o.userId),
          pizza: pizzas.find(p => p.id === o.pizzaId),
          addMods: (o.addModificationIds || []).map(id => modifications.find(m => m.id === id)).filter(Boolean) as Modification[],
          removeMods: (o.removeModificationIds || []).map(id => modifications.find(m => m.id === id)).filter(Boolean) as Modification[]
        }));

        setOrders(hydratedOrders);
      } else {
        setOrders([]);
      }
    } catch (err: any) {
      console.error(err);
      setError({ message: err.message || "Errore caricamento dati" });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Calcolo della disponibilità effettiva per oggi
  const currentAvailability = useMemo(() => {
    if (!settings) return null;
    return getDayAvailability(
      getTodayDateString(),
      settings.active_days,
      overrides,
      currentDay,
      settings.cutoff_time
    );
  }, [settings, overrides, currentDay]);

  const handleTitleClick = () => {
    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
    const newCount = clickCount + 1;
    setClickCount(newCount);
    if (newCount === 7) {
      setShowResetPin(true);
      setClickCount(0);
    } else {
      resetTimerRef.current = setTimeout(() => setClickCount(0), 3000);
    }
  };

  const handleResetPinSubmit = () => {
    if (resetPin === '1131') {
      setShowResetPin(false);
      setShowFinalConfirm(true);
      setResetPin('');
    } else {
      alert("PIN Errato");
      setResetPin('');
    }
  };

  const executeSeasonalReset = async () => {
    setIsResetting(true);
    try {
      await db.resetSeasonalData();
      setShowFinalConfirm(false);
      setToast("Reset Stagionale Completato ✅");
      setTimeout(() => setToast(null), 3000);
      await fetchData();
    } catch (err: any) {
      alert("Errore durante il reset: " + err.message);
    } finally {
      setIsResetting(false);
    }
  };

  const handleToggleDay = async (action: 'open' | 'close') => {
    setActionLoading(true);
    try {
      if (action === 'open') {
        await db.openDay();
      } else {
        await db.closeDay();
      }
      await fetchData();
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setActionLoading(false);
    }
  };

  const handleDownloadReport = () => {
    if (!currentDay || orders.length === 0) {
      alert("Nessun ordine presente per oggi.");
      return;
    }
    generateDayReportPDF(currentDay.date, orders, SLOT_TIMES);
  };

  const isAdmin = user.role === Role.ADMIN;

  if (loading && !error) {
    return (
      <Layout title="InTavola Admin" onLogout={onLogout}>
        <div className="flex justify-center py-20"><div className="loading-spinner !w-10 !h-10" /></div>
      </Layout>
    );
  }

  return (
    <Layout title="Gestione Locale" onLogout={onLogout}>
      {/* Elemento invisibile per reset stagionale, spostato per non interferire con header */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-20 h-10 z-[60]" onClick={handleTitleClick} />

      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-black text-white px-4 py-2 rounded-full text-[10px] font-bold animate-in fade-in zoom-in duration-300">
          {toast}
        </div>
      )}

      <div className="space-y-6">
        {/* Card Personale */}
