import AdminDashboard from './views/AdminDashboard';
import AdminPizzas from './views/AdminPizzas';
import AdminUsers from './views/AdminUsers';
import AdminHistory from './views/AdminHistory';
import AdminModifications from './views/AdminModifications';
import AdminCalendar from './views/AdminCalendar';
import { Fingerprint } from './components/Icons';
import { Button } from './components/UI';

const BACKGROUND_LOGOUT_THRESHOLD_MS = 0; // Logout immediato al cambio visibilità

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('pizzastaff_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const [view, setView] = useState<'dashboard' | 'pizzas' | 'users' | 'history' | 'modifications' | 'order' | 'calendar'>('dashboard');
  const [showPasskeyPrompt, setShowPasskeyPrompt] = useState(false);
  const [isBiometricSupported, setIsBiometricSupported] = useState(false);

  const handleLogout = useCallback(() => {
    setAuth({ user: null, isAuthenticated: false });
    localStorage.removeItem('pizzastaff_auth');
    setView('dashboard');
  }, []);

  // --- SESSION GUARD: Logout on Background ---
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        localStorage.setItem('pizzastaff_last_background_at', Date.now().toString());
      } else {
        const lastBg = localStorage.getItem('pizzastaff_last_background_at');
        if (lastBg) {
          const elapsed = Date.now() - parseInt(lastBg);
          if (elapsed >= BACKGROUND_LOGOUT_THRESHOLD_MS && auth.isAuthenticated) {
            handleLogout();
            // Opzionale: Mostra un toast di sistema o log
            console.log("Sessione invalidata per inattività in background.");
          }
          localStorage.removeItem('pizzastaff_last_background_at');
        }
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('pagehide', handleLogout); // Extra safety per chiusura tab

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('pagehide', handleLogout);
    };
  }, [auth.isAuthenticated, handleLogout]);

  useEffect(() => {
    if (auth.isAuthenticated) {
      localStorage.setItem('pizzastaff_auth', JSON.stringify(auth));
    }

    const checkSupport = async () => {
      const supported = !!(window.PublicKeyCredential && 
        await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable());
      setIsBiometricSupported(supported);
    };
    checkSupport();
  }, [auth]);

  const handleLogin = (user: User) => {
    setAuth({ user, isAuthenticated: true });

    const passkeyActive = localStorage.getItem('pizzastaff_passkey_active') === 'true';
    const hasDeclined = localStorage.getItem('pizzastaff_passkey_declined') === 'true';

    if (!passkeyActive && !hasDeclined && isBiometricSupported) {
      setTimeout(() => setShowPasskeyPrompt(true), 1500);
    }
  };

  const declinePasskey = () => {
    localStorage.setItem('pizzastaff_passkey_declined', 'true');
    setShowPasskeyPrompt(false);
  };

  if (!auth.isAuthenticated || !auth.user) {
    return <LoginView onLogin={handleLogin} />;
  }

  return (
    <div className="bg-[#F2F2F7] h-full overflow-hidden flex flex-col">
      <div className="flex-1 overflow-y-auto">
        {view === 'pizzas' && <AdminPizzas onBack={() => setView('dashboard')} />}
        {view === 'users' && <AdminUsers currentUser={auth.user} onBack={() => setView('dashboard')} />}
        {view === 'history' && <AdminHistory onBack={() => setView('dashboard')} />}
        {view === 'modifications' && <AdminModifications onBack={() => setView('dashboard')} />}
        {view === 'calendar' && <AdminCalendar onBack={() => setView('dashboard')} />}
        {view === 'order' && <WorkerDashboard user={auth.user} onLogout={handleLogout} onBackToAdmin={() => setView('dashboard')} />}
        {view === 'dashboard' && auth.user.role !== Role.WORKER && (
          <AdminDashboard 
            user={auth.user} 
            onLogout={handleLogout} 
            onNavigate={(v: any) => setView(v)} 
            onGoToOrder={() => setView('order')}
          />
        )}
        {auth.user.role === Role.WORKER && (
          <WorkerDashboard user={auth.user} onLogout={handleLogout} />
        )}
      </div>

      {showPasskeyPrompt && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={declinePasskey} />
          <div className="relative bg-white w-full max-w-sm rounded-[32px] p-8 shadow-2xl animate-in slide-in-from-bottom duration-500 text-center space-y-6">
            <div className="w-20 h-20 bg-[#F2F2F7] text-[#007AFF] rounded-full flex items-center justify-center mx-auto">
              <Fingerprint size={40} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-[#1c1c1e]">Accesso Biometrico</h3>
              <p className="text-sm text-[#8E8E93] mt-2 leading-relaxed">
                Vuoi attivare il Face ID o l'impronta digitale? Potrai entrare istantaneamente senza PIN la prossima volta.
              </p>
            </div>
            <div className="space-y-3">
              <Button fullWidth onClick={() => { setShowPasskeyPrompt(false); setView('order'); }}>Configura nel profilo</Button>
              <button 
                onClick={declinePasskey}
                className="w-full py-2 text-sm font-bold text-[#8E8E93] uppercase tracking-widest"
              >
                No, grazie
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { User } from '../types';
import { Fingerprint, PizzaIcon } from '../components/Icons';
import { isBiometricAvailable, authenticatePasskey } from '../services/biometrics';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isBioSupported, setIsBioSupported] = useState(false);
  const [passkeyActive, setPasskeyActive] = useState(false);

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);
      setPasskeyActive(localStorage.getItem('pizzastaff_passkey_active') === 'true');
    };
    checkBio();
  }, []);

  const handlePasskeyLogin = async () => {
    setLoading(true);
    setError('');
    try {
      const user = await authenticatePasskey();
      if (user) {
        onLogin(user);
      } else {
        // Silenzioso o feedback leggero se annullato dall'utente
      }
    } catch (err) {
      setError('Autenticazione biometrica fallita');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async () => {
    if (pin.length < 4) return;
    setLoading(true);
    setError('');
    try {
      const user = await db.getUserByPin(pin);
      if (user) {
        onLogin(user);
      } else {
        setError('PIN non valido');
        setPin('');
      }
    } catch (err) {
      setError('Errore di connessione');
    } finally {
      setLoading(false);
    }
  };

  const addDigit = (d: string) => {
    if (pin.length < 6) {
      const newPin = pin + d;
      setPin(newPin);
      setError('');
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#F2F2F7] safe-top safe-bottom">
      <div className="w-full max-w-xs flex flex-col items-center gap-8">
        <div className="flex flex-col items-center gap-6">
          <div className="w-24 h-24 bg-gradient-to-br from-[#007AFF] to-[#5856D6] rounded-[22%] flex items-center justify-center shadow-2xl">
             <PizzaIcon size={48} className="text-white" />
          </div>
          <div className="text-center">
            <h1 className="text-3xl font-black tracking-tighter text-[#1c1c1e]">InTavola Staff</h1>
            <p className="text-[#8E8E93] text-[10px] font-black uppercase tracking-[0.3em] mt-1">Area Riservata Dipendenti</p>
          </div>
        </div>

        <div className="w-full flex flex-col items-center">
          {error && <p className="text-center text-sm font-bold mb-6 text-[#FF3B30] animate-bounce">{error}</p>}

          <div className="w-full max-w-[280px]">
            <div className="flex justify-center gap-4 mb-10">
              {[...Array(4)].map((_, i) => (
                <div key={i} className={`w-3 h-3 rounded-full border-2 transition-all duration-200 ${pin.length > i ? 'bg-[#007AFF] border-[#007AFF] scale-125' : 'bg-transparent border-[#C6C6C8]'}`} />
              ))}
            </div>

            <div className="grid grid-cols-3 gap-y-4 gap-x-6">
              {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d => (
                <button key={d} onClick={() => addDigit(d)} className="w-16 h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA] flex items-center justify-center mx-auto transition-colors">{d}</button>
              ))}

              <button 
                onClick={handlePasskeyLogin}
                className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto transition-all ${isBioSupported && passkeyActive ? 'text-[#007AFF] bg-white ios-shadow active:bg-[#E5E5EA]' : 'text-[#8E8E93] opacity-20 pointer-events-none'}`}
              >
                <Fingerprint size={32} />
              </button>

              <button onClick={() => addDigit('0')} className="w-16 h-16 rounded-full bg-white text-2xl font-semibold ios-shadow active:bg-[#E5E5EA] flex items-center justify-center mx-auto">0</button>

              <button 
                onClick={handleLogin} 
                disabled={pin.length < 4 || loading} 
                className="w-16 h-16 rounded-full bg-[#007AFF] text-white text-sm font-black shadow-lg flex items-center justify-center mx-auto active:scale-95 disabled:opacity-50 transition-all"
              >
                {loading ? <div className="loading-spinner border-white border-t-transparent" /> : 'ENTRA'}
              </button>
            </div>

            <button onClick={() => setPin('')} className="w-full mt-8 text-[10px] font-black text-[#8E8E93] uppercase tracking-[0.2em]">Cancella</button>
          </div>

          <p className="text-center mt-12 text-[9px] font-bold text-[#C6C6C8] uppercase tracking-[0.1em] max-w-[200px] leading-relaxed">
            Per sicurezza, la sessione scade quando chiudi l'app.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Pizza, Order, SlotTime, Modification, Role, DayOverride } from '../types';
import { db, GlobalSettings } from '../services/db';
import { Layout } from '../components/Layout';
import { Card, Button, SegmentedControl, Input } from '../components/UI';
import { 
  PizzaIcon, 
  ClockIcon, 
  Search, 
  Check, 
  AlertCircle, 
  X, 
  Lock, 
  Settings, 
  UserIcon,
  LogOut,
  Sliders,
  Fingerprint
} from '../components/Icons';
import { getDayAvailability, getTodayDateString } from '../services/utils';
import { SLOT_TIMES } from '../constants';
import { isBiometricAvailable, registerPasskey, revokePasskeys } from '../services/biometrics';

interface WorkerDashboardProps {
  user: User;
  onLogout: () => void;
  onBackToAdmin?: () => void;
}

type ViewState = 'menu' | 'settings';

const WorkerDashboard: React.FC<WorkerDashboardProps> = ({ user, onLogout, onBackToAdmin }) => {
  const [activeTab, setActiveTab] = useState<ViewState>('menu');
  const [pizzas, setPizzas] = useState<Pizza[]>([]);
  const [modifications, setModifications] = useState<Modification[]>([]);
  const [currentDay, setCurrentDay] = useState<any>(null);
  const [settings, setSettings] = useState<GlobalSettings | null>(null);
  const [overrides, setOverrides] = useState<DayOverride[]>([]);
  const [myOrder, setMyOrder] = useState<Order | null>(null);
  const [search, setSearch] = useState('');
  const [selectedPizza, setSelectedPizza] = useState<Pizza | null>(null);
  const [slot, setSlot] = useState<SlotTime>('18:00');
  const [selectedAddIds, setSelectedAddIds] = useState<string[]>([]);
  const [selectedRemoveIds, setSelectedRemoveIds] = useState<string[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [showRecap, setShowRecap] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isBioSupported, setIsBioSupported] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(localStorage.getItem('pizzastaff_passkey_active') === 'true');
  const [actionLoading, setActionLoading] = useState(false);

  useEffect(() => {
    const checkBio = async () => {
      const available = await isBiometricAvailable();
      setIsBioSupported(available);

      const serverHasPasskeys = await db.hasPasskeys(user.id);
      if (serverHasPasskeys) {
        localStorage.setItem('pizzastaff_passkey_active', 'true');
        setBiometricEnabled(true);
      } else {
        localStorage.removeItem('pizzastaff_passkey_active');
        setBiometricEnabled(false);
      }
    };
    checkBio();
  }, [user.id]);

  const availability = useMemo(() => {
    const today = getTodayDateString();
    return getDayAvailability(
        today, 
        settings?.active_days || [], 
        overrides, 
        currentDay,
        settings?.cutoff_time || '16:30'
    );
  }, [settings, overrides, currentDay]);

  const canOrder = useMemo(() => {
    if (settings?.override_cutoff) return true;
    return availability.isActive;
  }, [availability, settings]);

  const addOptions = useMemo(() => modifications.filter(m => m.type === 'ADD' && m.active), [modifications]);
  const removeOptions = useMemo(() => modifications.filter(m => m.type === 'REMOVE' && m.active), [modifications]);

  const handleToggleAdd = (id: string) => {
    setSelectedAddIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleToggleRemove = (id: string) => {
    setSelectedRemoveIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pizzaList, modList, day, order, globalSettings, dayOverrides] = await Promise.all([
          db.getPizzas(),
          db.getModifications(),
          db.getCurrentDay(),
          db.getUserOrderToday(user.id),
          db.getSettings(),
          db.getOverrides()
        ]);
        setPizzas(pizzaList.filter(p => p.active));
        setModifications(modList || []);
        setCurrentDay(day);
        setMyOrder(order);
        setSettings(globalSettings);
        setOverrides(dayOverrides);
      } catch (err: any) {
        setErrorMessage(err.message || "Errore nel caricamento dei dati");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user.id]);

  const handleConfirmOrder = async () => {
    if (!selectedPizza) return;
    setSubmitting(true);
    setErrorMessage(null);
    try {
      const order: Partial<Order> = {
        id: myOrder?.id,
        dayId: currentDay?.id, 
        userId: user.id,
        pizzaId: selectedPizza.id,
        slotTime: slot,
        addModificationIds: selectedAddIds,
        removeModificationIds: selectedRemoveIds,
        note: ''
      };
      await db.saveOrder(order);
      setShowRecap(false);
      setShowSuccess(true);
      setSelectedPizza(null);
      setTimeout(() => onLogout(), 2000);
    } catch (err: any) {
      setErrorMessage(err.message || "Errore durante il salvataggio");
      setSubmitting(false);
    }
  };

  const handleTogglePasskey = async () => {
    setActionLoading(true);
    try {
      if (biometricEnabled) {
        if (confirm("Vuoi disattivare l'accesso biometrico su tutti i dispositivi?")) {
          await revokePasskeys(user.id);
          setBiometricEnabled(false);
          alert("Accesso rapido disattivato.");
        }
      } else {
        const success = await registerPasskey(user.id);
        if (success) {
          setBiometricEnabled(true);
          alert("Accesso rapido con Face ID / Impronta attivato ✅");
        }
      }
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setActionLoading(false);
    }
  };

  const renderMenu = () => {
    const filteredPizzas = pizzas.filter(p => 
      p.name.toLowerCase().includes(search.toLowerCase()) || 
      p.ingredients?.some(i => i.toLowerCase().includes(search.toLowerCase()))
    );

    return (
      <div className="space-y-5">
        <div className="pt-2 pb-1">
          <h1 className="text-[28px] font-black text-[#1c1c1e] tracking-tight leading-[1.1]">Ciao {user.firstName}!</h1>
          <p className="text-base font-bold text-[#8E8E93] mt-1">Cosa ti prepariamo oggi?</p>
        </div>

        {!canOrder && (
          <div className="bg-[#FF3B30] text-white p-4 rounded-2xl flex items-center gap-3 shadow-lg">
            <div className="p-2 bg-white/20 rounded-full shrink-0"><Lock size={20} /></div>
            <div className="flex-1">
              <p className="font-black text-sm tracking-tight">Servizio non attivo</p>
              <p className="text-[10px] font-medium opacity-90 leading-tight">
                {availability.label.includes('OLTRE') ? `Gli ordini sono terminati alle ${settings?.cutoff_time}.` : "Servizio non disponibile per oggi."}
              </p>
            </div>
          </div>
        )}

        {myOrder && !selectedPizza && !isEditing && (
          <Card className={`p-5 border-2 max-w-2xl mx-auto ${availability.isActive ? 'border-[#34C759] shadow-lg' : 'border-[#C6C6C8] opacity-80 grayscale'}`}>
            <div className="flex justify-between items-start gap-3 mb-5">
              <div className="flex-1">
                <p className={`text-[9px] font-black ${availability.isActive ? 'text-[#34C759]' : 'text-[#8E8E93]'} uppercase tracking-[0.2em] mb-1.5`}>Il tuo ordine</p>
                <h2 className="text-xl font-black truncate">{pizzas.find(p => p.id === myOrder.pizzaId)?.name || 'Pizza'}</h2>
                <div className="mt-2 flex flex-wrap gap-1.5">
                  {myOrder.addModificationIds?.map(id => {
                    const mod = modifications.find(m => m.id === id);
                    return mod ? <span key={id} className="text-[9px] font-black px-2 py-0.5 rounded-full bg-green-100 text-green-700">+{mod.name}</span> : null;
                  })}
                </div>
              </div>
              <div className="bg-[#F2F2F7] px-3 py-1.5 rounded-xl flex items-center gap-1.5">
                <ClockIcon size={14} className="text-[#8E8E93]" />
                <span className="text-sm font-black">{myOrder.slotTime}</span>
              </div>
            </div>
            {canOrder && (
              <Button onClick={() => {
                const p = pizzas.find(px => px.id === myOrder.pizzaId);
                if(p) { setSelectedPizza(p); setSlot(myOrder.slotTime); setSelectedAddIds(myOrder.addModificationIds || []); setSelectedRemoveIds(myOrder.removeModificationIds || []); setIsEditing(true); }
              }} variant="secondary" fullWidth className="!bg-[#F2F2F7] !py-3">Modifica Scelta</Button>
            )}
          </Card>
        )}

        {(!myOrder || isEditing) && !selectedPizza && (
          <div className={`space-y-5 ${!canOrder ? 'opacity-40 pointer-events-none' : ''}`}>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8E8E93]" size={16} />
              <Input placeholder="Cerca pizza..." className="pl-10 !py-3 !rounded-xl border-none shadow-sm bg-white" value={search} onChange={(e) => setSearch(e.target.value)} />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pb-4">
              {filteredPizzas.map(pizza => (
                <Card key={pizza.id} className="p-4 cursor-pointer hover:shadow-md active:scale-[0.97] transition-all flex flex-col h-full border border-transparent hover:border-[#007AFF]/10" onClick={() => canOrder && setSelectedPizza(pizza)}>
                  <div className="flex justify-between items-start mb-1.5">
                    <h3 className="font-black text-base text-[#1c1c1e] truncate pr-2">{pizza.name}</h3>
                    {pizza.isVegetarian && <span className="bg-green-100 text-green-700 text-[8px] px-1.5 py-0.5 rounded-full font-black tracking-wider shrink-0">VEG</span>}
                  </div>
                  <p className="text-[11px] text-[#8E8E93] leading-snug flex-1 italic line-clamp-2">{pizza.ingredients?.join(', ')}</p>
                  <div className="mt-3 pt-2 border-t border-[#F2F2F7] flex justify-end">
                    <span className="text-[#007AFF] text-[9px] font-black uppercase tracking-widest">Seleziona</span>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  const isManagement = user.role === Role.ADMIN || user.role === Role.SUPERVISOR;

  return (
    <Layout title={activeTab === 'menu' ? 'InTavola Staff' : 'Profilo'} onBack={activeTab === 'settings' ? () => setActiveTab('menu') : undefined}>
      {showSuccess && (
        <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center p-6 bg-white/95 backdrop-blur-2xl animate-in fade-in duration-300">
          <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-5 animate-in zoom-in duration-500 shadow-md"><Check size={32} strokeWidth={3} /></div>
          <h2 className="text-xl font-black text-[#1c1c1e] tracking-tight">Ordine Ricevuto!</h2>
          <p className="text-[#8E8E93] font-bold mt-1.5 uppercase tracking-widest text-[9px]">A tra poco in cucina</p>
        </div>
      )}

      {activeTab === 'menu' ? renderMenu() : (
        <div className="max-w-2xl mx-auto space-y-6 animate-in slide-in-from-right duration-300">
           <Card className="p-6 text-center bg-white shadow-md">
            <div className="w-16 h-16 bg-gradient-to-br from-[#007AFF] to-[#5856D6] rounded-full flex items-center justify-center text-white mx-auto shadow-md mb-4"><UserIcon size={32} /></div>
            <h2 className="text-lg font-black text-[#1c1c1e]">{user.firstName} {user.lastName}</h2>
            <p className="text-[9px] font-black text-[#007AFF] uppercase tracking-widest mt-1 bg-[#F2F2F7] inline-block px-3 py-0.5 rounded-full">{user.role}</p>
          </Card>

          <div className="grid grid-cols-1 gap-5">
            <section className="space-y-2">
              <p className="text-[9px] font-black text-[#8E8E93] uppercase tracking-widest pl-1">Sicurezza</p>
              <Card className="overflow-hidden">
                {isBioSupported ? (
                  <div className="p-4 flex items-center justify-between hover:bg-[#F2F2F7] transition-colors cursor-pointer" onClick={handleTogglePasskey}>
                    <div className="flex items-center gap-3">
                      <div className={`p-1.5 rounded-lg ${biometricEnabled ? 'bg-green-100 text-green-600' : 'bg-[#F2F2F7] text-[#8E8E93]'}`}>
                        <Fingerprint size={18} />
                      </div>
                      <div>
                        <p className="text-xs font-bold">Accesso Rapido</p>
                        <p className="text-[9px] text-[#8E8E93] font-bold tracking-tight">Face ID / Touch ID</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {actionLoading && <div className="loading-spinner" />}
                      <div className={`w-10 h-6 rounded-full transition-colors relative flex items-center px-1 ${biometricEnabled ? 'bg-[#34C759]' : 'bg-[#C6C6C8]'}`}>
